struct TestLocalBootstrap;

impl LocalBootstrapTransport for TestLocalBootstrap {
    fn run_id(&self) -> &str {
        "00112233445566778899aabbccddeeff"
    }

    fn is_ready(&self) -> bool {
        true
    }

    fn request_cancelled(&self, _request_id: &str) -> bool {
        false
    }

