struct SyntheticDirectoryEventSource {
    head: u64,
    requests: std::sync::Mutex<Vec<(u64, usize)>>,
}

impl DirectoryEventPageSource for SyntheticDirectoryEventSource {
    async fn directory_event_head(&self) -> Result<u64, DirectoryError> {
        Ok(self.head)
    }

    async fn directory_event_page(&self, since: u64, limit: usize) -> Result<Vec<DirectoryEvent>, DirectoryError> {
        self.requests.lock().expect("request lock").push((since, limit));
        let limit = u64::try_from(limit).map_err(|error| DirectoryError::Backend(error.to_string()))?;
        let end = since.saturating_add(limit).min(self.head);
        Ok(((since + 1)..=end)
            .map(|seq| DirectoryEvent {
                seq,
                id: format!("event-{seq}"),
                hlc: os_directory::Hlc { physical_ms: i64::try_from(seq).expect("bounded synthetic sequence"), logical: 0 },
                actor: DirectoryActor { kind: DirectoryActorKind::System, id: "system:paged-read-law".into() },
                space_id: Some("default".into()),
                user_id: None,
                body: os_directory::DirectoryEventBody::SpaceRenamed { space_id: "default".into(), name: format!("paged-{seq}") },
                recorded_at_ms: 0,
            })
            .collect())
    }
}

/// 📁️ A fresh, never-reused temp directory per call — the owned `time_ordered_id` rather than
/// `now_ms()` alone, since `cargo test` runs this whole module's `#[tokio::test]`s
/// concurrently within one process: two tests calling `test_state()` in the same millisecond
/// would otherwise collide on the identical `os-hub-test-db-<pid>-<ms>` path and open the SAME
/// `db::Database` storage root, corrupting each other's catalog/WAL state.
fn tempdir(name: &str) -> std::path::PathBuf {
    let mut dir = crate::test_artifact_root::test_artifact_root();
    dir.push(format!("os-hub-test-{name}-{}", directory::os_identity::time_ordered_id()));
    std::fs::create_dir_all(&dir).expect("owned temporary fixture directory");
    dir
}

fn run_socket_test<F, Fut>(test: F)
where
    F: FnOnce() -> Fut + Send + 'static,
    Fut: std::future::Future<Output = ()> + 'static,
{
    std::thread::Builder::new()
        .name("hub-socket-test".into())
        .stack_size(32 * 1024 * 1024)
        .spawn(move || tokio::runtime::Builder::new_current_thread().enable_all().build().expect("test runtime").block_on(test()))
        .expect("socket test thread")
        .join()
        .expect("socket test");
}

/// 🏝️ A law that saturates a process-global capacity (the database's DB I/O credit ledger) owns a
/// whole process: inside a shared test process it re-runs itself as the only law of a child process
/// and reports that child's verdict, so it never refuses the writes of the laws running beside it; a
/// runner that already gives every law its own process (nextest) runs it in place. Returns `true`
/// where the law body must run. The database's own laws use the same protocol
/// (`db_storage::process_isolated_law`).
fn process_isolated_law(law: &str) -> bool {
    const ISOLATED_LAW: &str = "SEMIO_HUB_ISOLATED_LAW";
    const ISOLATED_LAW_WATCHDOG: std::time::Duration = std::time::Duration::from_secs(600);
    if std::env::var_os("NEXTEST").is_some() || std::env::var(ISOLATED_LAW).is_ok_and(|isolated| isolated == law) {
        return true;
    }
    let executable = std::env::current_exe().expect("process-isolated law resolves its test executable");
    let log_path = tempdir("isolated-law").join("child.log");
    let log = std::fs::File::create(&log_path).expect("process-isolated law creates its child log");
    let mut child = std::process::Command::new(executable)
        .args(["--exact", law, "--test-threads=1"])
        .env(ISOLATED_LAW, law)
        .stdout(log.try_clone().expect("process-isolated law shares its child log"))
        .stderr(log)
        .spawn()
        .expect("process-isolated law spawns its child process");
    let deadline = std::time::Instant::now() + ISOLATED_LAW_WATCHDOG;
    let status = loop {
        if let Some(status) = child.try_wait().expect("process-isolated law observes its child") {
            break Some(status);
        }
        if std::time::Instant::now() >= deadline {
            let _ = child.kill();
            let _ = child.wait();
            break None;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    };
    let output = std::fs::read_to_string(&log_path).unwrap_or_default();
    let _ = std::fs::remove_dir_all(log_path.parent().expect("child log directory"));
    assert!(status.is_some_and(|status| status.success()) && output.contains("test result: ok. 1 passed"), "process-isolated law {law} did not pass as the only law of its own process ({status:?}):\n{output}");
    false
}

