async fn presence_lease_enforces_shared_roster_bounds_and_actor_order() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/👥️presence-lease-v1/🔣️.json")).expect("presence lease fixture");
