CREATE TABLE IF NOT EXISTS hub_artifact_cas_reference (
    space_id TEXT NOT NULL,
    document_id TEXT NOT NULL,
    checkpoint_id BYTEA NOT NULL CHECK(octet_length(checkpoint_id) = 32),
