//! 🧪️ The preview pane draws the SOLVED assignment when one is cached and the bare cell grid when
//! it is not — and never reads the assignment from the document, which does not hold one.

use super::*;
use crate::editor::grid2d::window::Grid2dWindowConfig;
use crate::schema::inferences::solve_with_clock;

fn layers(document: &Grid2dSnapshot, config: &Grid2dWindowConfig) -> Vec<Value> {
    serde_json::from_str(&layers_json(document, cached_commit(document, config).as_ref())).expect("layers are real json")
}

#[test]
fn the_window_declares_a_canvas_surface_with_a_registered_icon() {
    let window = definition();
    assert_eq!(window.id, WINDOW_KIND_ID);
    assert_eq!(window.surface_kind, SurfaceKind::Canvas2d);
    assert_eq!(window.icon_id, semio_framework_plugin::IconName::Preview);
    assert!(window.utilities.is_empty(), "the preview pane accepts no pointer utility");
}

#[test]
fn an_unsolved_pane_draws_one_outline_per_unmasked_cell() {
    let document = crate::examples::grid2d::pipes::document();
    let rendered = layers(&document, &Grid2dWindowConfig::default());
    assert_eq!(rendered.len(), 35, "the 6×6 grid minus its one masked cell");
    assert!(rendered.iter().all(|layer| layer.get("width").is_some() && layer.get("height").is_some()), "every bounds layer needs explicit extents or it silently draws nothing");
}

#[test]
fn a_solved_vector_pane_draws_one_path_layer_per_connector() {
    let document = crate::examples::grid2d::pipes::document();
    let commit = solve_with_clock(&document, semio_framework_job::logical_now_us).expect("the example solves");
    let config = Grid2dWindowConfig { solve_json: protocol::json::to_json_string(&commit), ..Default::default() };
    let rendered = layers(&document, &config);
    assert!(!rendered.is_empty());
    assert!(rendered.iter().any(|layer| layer.get("segments").is_some()), "a vector tile must reach the canvas as a real path");
    for layer in &rendered {
        if let Some(transform) = layer.get("transform") {
            assert_eq!(transform.as_array().expect("transform is a 6-tuple").len(), 6);
        }
    }
}

/// 🧱️ A solved bitmap board stays inside the pane's whole-surface budget. Drawing all 64 cells at
/// 4×4 pixels each encoded to 87 337 bytes and the host refused the WHOLE surface
/// (`ui.fixed-capacity`) — the solve ran and the pane stayed blank — so a board over budget draws
/// one averaged swatch per cell instead.
#[test]
fn a_solved_bitmap_pane_stays_inside_the_surface_budget() {
    let document = crate::examples::grid2d::terrain::document();
    let commit = solve_with_clock(&document, semio_framework_job::logical_now_us).expect("the example solves");
    let config = Grid2dWindowConfig { solve_json: protocol::json::to_json_string(&commit), ..Default::default() };
    let rendered = layers(&document, &config);
    assert_eq!(rendered.len(), 64, "64 assigned cells, one swatch each — the 1 024-rect form overflows the surface");
    assert!(rendered.iter().all(|layer| layer["color"].as_str().is_some_and(|color| color.starts_with('#'))), "a bounds layer's colour must be a css hex or the host falls back to a hue ramp");
    let distinct: std::collections::BTreeSet<&str> = rendered.iter().filter_map(|layer| layer["color"].as_str()).collect();
    assert!(distinct.len() > 1, "a solved board is not one flat colour: {distinct:?}");
    assert!(layers_json(&document, Some(&commit)).len() < 65_536, "the published surface must fit the host's fixed capacity");
}

/// 🎨️ A small board still draws real pixels: the per-tile ceiling only degrades once the BOARD
/// budget is the binding one.
#[test]
fn a_small_bitmap_board_still_draws_one_rect_per_pixel() {
    let mut document = crate::examples::grid2d::terrain::document();
    document.width = 2;
    document.height = 2;
    document.pinned.retain(|cell| cell.x < 2 && cell.y < 2);
    document.masked.retain(|cell| cell.x < 2 && cell.y < 2);
    let commit = solve_with_clock(&document, semio_framework_job::logical_now_us).expect("the trimmed example solves");
    let config = Grid2dWindowConfig { solve_json: protocol::json::to_json_string(&commit), ..Default::default() };
    assert_eq!(layers(&document, &config).len(), 4 * 16, "4 cells × a 4×4 bitmap each");
}

#[test]
fn a_cached_commit_that_contradicts_falls_back_to_the_bare_grid() {
    let document = crate::examples::grid2d::pipes::document();
    let contradicted = Grid2dInferenceCommit { assignments: Vec::new(), contradiction: true, entropy: Vec::new() };
    let config = Grid2dWindowConfig { solve_json: protocol::json::to_json_string(&contradicted), ..Default::default() };
    assert_eq!(layers(&document, &config).len(), 35);
}

#[test]
fn a_malformed_cache_is_ignored_rather_than_failing_the_render() {
    let document = crate::examples::grid2d::pipes::document();
    let config = Grid2dWindowConfig { solve_json: "not json".into(), ..Default::default() };
    assert!(cached_commit(&document, &config).is_none());
    render(&document, &config, None).expect("the pane still renders");
    assert!(layers(&document, &config).len() > 1, "a malformed cache falls back to the bare grid, not to nothing");
}

/// 🧊️ The cache lives in WINDOW CONFIG and the document can be replaced under it (the navbar
/// example switcher), so a commit that does not belong to the document in front of the pane must be
/// dropped — otherwise the pipes assignment paints over the terrain grid as "unknown tile" boxes.
#[test]
fn a_cache_from_another_document_is_dropped_rather_than_painted() {
    let pipes = crate::examples::grid2d::pipes::document();
    let terrain = crate::examples::grid2d::terrain::document();
    let solved = solve_with_clock(&pipes, semio_framework_job::logical_now_us).expect("pipes solves");
    let config = Grid2dWindowConfig { solve_json: protocol::json::to_json_string(&solved), ..Default::default() };
    assert!(cached_commit(&pipes, &config).is_some(), "its own document keeps the cache");
    assert!(cached_commit(&terrain, &config).is_none(), "a foreign document drops it");
    let painted = layers(&terrain, &config);
    assert!(painted.iter().all(|layer| layer["name"].is_null()), "the fallback grid carries no tile labels: {painted:?}");
}

#[test]
fn the_rendered_surface_is_non_empty_for_every_example() {
    for source in crate::examples::grid2d::sources() {
        let document = <Grid2dSnapshot as store::ArtifactDsl>::parse_dsl(&source.document()).expect("example parses");
        render(&document, &Grid2dWindowConfig::default(), None).unwrap_or_else(|error| panic!("{}: the preview pane must render: {error:?}", source.id()));
        assert!(scene(&document, &Grid2dWindowConfig::default(), None).layers_json.len() > 64, "{}: the canvas carries no layers", source.id());
    }
}

#[test]
fn a_partial_fill_preview_differs_from_empty_and_finished() {
    let document = crate::examples::grid2d::pipes::document();
    let oracle = solve_with_clock(&document, semio_framework_job::logical_now_us).expect("pipes solves");
    let empty = layers_json(&document, None);
    let finished = layers_json(&document, Some(&oracle));
    let mut partial = oracle.clone();
    partial.assignments.truncate((oracle.assignments.len() / 2).max(1));
    assert!(partial.assignments.len() < oracle.assignments.len());
    let mid = layers_json(&document, Some(&partial));
    assert_ne!(mid, empty, "a partial board must not look empty");
    assert_ne!(mid, finished, "a partial board must not look finished");
}

//! 🪣 Edit-mode tool — Fill: the interactive collapse of `s.wfc.grid2d`. A non-mutating framework
//! tool run (`mutating: false`, `ToolRunTraceKind::None`) whose every step advances one preparation
//! unit or one `WfcJob::step`, publishes a partial-assignment payload the preview pane paints, and
//! on completion dispatches `commit-fill` so `Grid2dWindowConfig.solve_json` receives the finished
//! cache. Abort never writes that cache.

use crate::editor::grid2d::modes::edit::windows::preview;
use crate::schema::inferences::{solve_with_job, Grid2dInferenceCommit};
use crate::schema::snapshot::{Grid2dSnapshot, WfcDirection2d};
use semio_framework_job::{InteractiveJob, InteractiveJobCloseStep, Operation, StepContext, StepOutcome};
use semio_framework_ui_locale::LocalizedLabel;
use semio_framework_plugin::ToolDefinition;
use semio_framework_plugin::ToolRunJobPort;
use semio_framework_tool_run::{
    JobKindId, ToolRunCounter, ToolRunCounterDefinition, ToolRunDefinition, ToolRunIdentity, ToolRunProgress, ToolRunRebasePolicy, ToolRunReasonDefinition, ToolRunReconfigurePolicy, ToolRunSettingsReads,
    ToolRunStageDefinition, ToolRunState, ToolRunStepArg, ToolRunStepKind, ToolRunTickWriter, ToolRunTraceKind, ToolRunVerdict, TOOL_RUN_ARG_TOOL_ID, TOOL_RUN_START_ACTION_ID,
};
use semio_s_plugin_wfc_engine as wfc;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::Arc;

//#region 🔖️Constants
pub const TOOL_ID: &str = "fill";
pub const RUN_JOB_KIND: &str = "s.wfc.grid2d.fill.run";
pub const COMMIT_FILL_ACTION_ID: &str = "commit-fill";
pub const PAYLOAD_SCHEMA: &str = include_str!("🧬️schema/🔣️.json");
//#endregion 🔖️Constants

//#region 🔖️Payload
/// 🧩 One collapse or discard the preview keeps on screen after the search moves on.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[serde(rename_all = "camelCase")]
#[value(rename_all = "camelCase")]
pub struct Grid2dFillTraceEvent {
    pub x: u32,
    pub y: u32,
    pub tile_id: String,
    pub discarded: bool,
}

/// 🧩 One cell in a fill tick: `tile_id` is absent while the cell is still open.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[serde(rename_all = "camelCase")]
#[value(rename_all = "camelCase")]
pub struct Grid2dFillCell {
    pub x: u32,
    pub y: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub tile_id: Option<String>,
}

/// 📦 The preview payload every fill tick publishes — partial cell assignments plus terminal flags.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[serde(rename_all = "camelCase")]
#[value(rename_all = "camelCase")]
pub struct Grid2dFillPayload {
    pub assignments: Vec<Grid2dFillCell>,
    pub contradiction: bool,
    pub done: bool,
    #[serde(default)]
    #[value(default)]
    pub trace: Vec<Grid2dFillTraceEvent>,
}

impl Grid2dFillPayload {
    /// 🔢 How many cells already carry a tile.
    pub fn decided_count(&self) -> usize {
        self.assignments.iter().filter(|cell| cell.tile_id.is_some()).count()
    }

    /// 🏁 The finished cache shape the preview pane already paints from `solve_json`.
    pub fn as_commit(&self) -> Grid2dInferenceCommit {
        Grid2dInferenceCommit {
            assignments: self.assignments.iter().filter_map(|cell| cell.tile_id.as_ref().map(|tile| (cell.x, cell.y, tile.clone()))).collect(),
            contradiction: self.contradiction,
            entropy: Vec::new(),
        }
    }

    pub fn encode(&self) -> Vec<u8> {
        serde_json::to_vec(self).unwrap_or_default()
    }

    pub fn decode(bytes: &[u8]) -> Option<Self> {
        serde_json::from_slice(bytes).ok()
    }
}
//#endregion 🔖️Payload

//#region 🔖️Definition
/// 📋 Stitched into the editor manifest by `crate::editor::grid2d::create_grid2d_editor`.
pub fn definition() -> ToolDefinition {
    ToolDefinition {
        run: Some(run_definition()),
        ..semio_framework_plugin::resolve_ready(ToolDefinition::new(TOOL_ID, LocalizedLabel::native("Fill", "Füllen"), "paint-bucket"))
    }
}

/// ▶️ Non-mutating collapse: pause/resume/step/abort are the framework panel's; each tick dirties the preview.
pub fn run_definition() -> ToolRunDefinition {
    ToolRunDefinition {
        mutating: false,
        rebase: ToolRunRebasePolicy::Restart,
        reconfigure: ToolRunReconfigurePolicy::Restart,
        unit: LocalizedLabel::native("steps", "Schritte"),
        stages: FillStage::ALL
            .iter()
            .map(|stage| ToolRunStageDefinition { id: stage.id().into(), label: stage.label() })
            .collect(),
        counters: FillCounter::ALL
            .iter()
            .map(|counter| ToolRunCounterDefinition { id: counter.id().into(), label: counter.label() })
            .collect(),
        reasons: FillReason::ALL
            .iter()
            .map(|reason| ToolRunReasonDefinition { code: reason.code(), id: reason.id().into(), verdict: reason.verdict(), template: reason.template() })
            .collect(),
        trace: ToolRunTraceKind::None,
        run_job: JobKindId::new(RUN_JOB_KIND),
        revalidate_job: None,
        settings: ToolRunSettingsReads::default(),
        windows: vec![preview::WINDOW_KIND_ID.into()],
    }
}

/// 🏃 The fill run of this document instance while it is not terminal.
pub fn live_fill_run(tool_run: Option<&semio_framework_plugin::ToolRunView>) -> Option<&semio_framework_plugin::ToolRunView> {
    tool_run.filter(|run| run.tool_id == TOOL_ID && !run.state.is_terminal())
}

/// 🎬 `toolRunStart` effect that arms this fill tool.
pub fn start_effect() -> semio_framework::kernel::Effect {
    let args = semio_framework::dsl_value!({ TOOL_RUN_ARG_TOOL_ID: TOOL_ID });
    semio_framework::kernel::Effect::DispatchAction {
        req: semio_framework_plugin::RequestId(semio_framework_job::allocate_operation_id().0),
        action: TOOL_RUN_START_ACTION_ID.into(),
        args: Some(args),
        delay_ms: 0,
    }
}

/// 💾 `commit-fill` effect that lands the finished cache in `solve_json`.
pub fn commit_effect(commit: &Grid2dInferenceCommit) -> semio_framework::kernel::Effect {
    let args = semio_framework::dsl_value!({ "solveJson": protocol::json::to_json_string(commit) });
    semio_framework::kernel::Effect::DispatchAction {
        req: semio_framework_plugin::RequestId(semio_framework_job::allocate_operation_id().0),
        action: COMMIT_FILL_ACTION_ID.into(),
        args: Some(args),
        delay_ms: 0,
    }
}
//#endregion 🔖️Definition

//#region 🏷️Stages
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillStage {
    InitializeDomains,
    FindMinimumEntropySlot,
    ChooseCandidate,
    PropagateCompatibilityEdge,
    DetectContradiction,
    BacktrackTrailEntry,
    CommitSlot,
    MaterializeCheckpoint,
    MaterializeCommit,
    Complete,
}

impl FillStage {
    pub const ALL: [Self; 10] = [
        Self::InitializeDomains,
        Self::FindMinimumEntropySlot,
        Self::ChooseCandidate,
        Self::PropagateCompatibilityEdge,
        Self::DetectContradiction,
        Self::BacktrackTrailEntry,
        Self::CommitSlot,
        Self::MaterializeCheckpoint,
        Self::MaterializeCommit,
        Self::Complete,
    ];

    pub fn index(self) -> u16 {
        self as u16
    }

    pub fn id(self) -> &'static str {
        match self {
