        // owner of a non-empty dictionary and must leave through a cold boundary, never a bare drop.
        let before = neural_engine::ColdOwner::new(semio_framework_pack_json::from_json_str::<SequenceHostSnapshot>(&case["before"].to_string()).expect("before fixture"));
        let after = neural_engine::ColdOwner::new(semio_framework_pack_json::from_json_str::<SequenceHostSnapshot>(&case["after"].to_string()).expect("after fixture"));
