//! 🧪️ Committed vector `➕insert-footing` / `⛔dupe`: re-applying the op to the after-snapshot it already produced is refused with `mutation.duplicate-id` (fatal) and leaves the document untouched.
use crate::{En1997Diff, En1997Mutation, En1997Snapshot};
const BEFORE: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕insert-footing/⛔dupe/📸️snapshot/⬅️before/🔣️.json");
const AFTER: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕insert-footing/⛔dupe/📸️snapshot/➡️after/🔣️.json");
const MUTATION: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕insert-footing/⛔dupe/🦠️mutation/🔣️.json");
const DIFF_ABSENT: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕insert-footing/⛔dupe/🔺️diff/🚫️.absent");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕insert-footing/⛔dupe/🎯️outcome/🔣️.json");
fn before() -> En1997Snapshot { semio_framework_pack_json::from_json_str(BEFORE, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("before") }
fn mutation() -> En1997Mutation { semio_framework_pack_json::from_json_str(MUTATION, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("mutation") }
#[test]
fn mutation_is_the_canonical_wire() {
    let _: En1997Mutation = store::os_store::test_support::assert_wire_witness(MUTATION);
}
#[test]
fn refuses_with_the_declared_code() {
    let raised = <En1997Mutation as protocol::Mutation<En1997Snapshot>>::diff(&mutation(), &before());
    let outcome: serde_json::Value = serde_json::from_str(OUTCOME).expect("outcome");
    let raised_codes: Vec<(String, String)> = raised.messages().iter().map(|message| (format!("{:?}", message.level).to_lowercase(), message.code.0.clone())).collect();
    assert_eq!(raised_codes, vec![(outcome["messages"][0]["level"].as_str().expect("level").to_string(), outcome["code"].as_str().expect("code").to_string())]);
    assert_eq!(outcome["status"], "rejected");
    assert_eq!(*raised.diff(), En1997Diff::default());
    assert!(DIFF_ABSENT.is_empty());
}
#[test]
fn leaves_the_document_untouched() {
    let raised = <En1997Mutation as protocol::Mutation<En1997Snapshot>>::diff(&mutation(), &before());
    let after = <En1997Diff as protocol::MutationDiff<En1997Snapshot>>::apply(raised.diff(), &before()).expect("apply");
    assert_eq!(after, before());
    assert_eq!(semio_framework_pack_json::from_json_str::<En1997Snapshot>(AFTER).expect("after"), before());
}

