/// 🎞️ The metabolism run: every iteration is one fuel unit and one tick, the provisional list ends with exactly one
/// `move-node` per moved node carrying its entity, and every node ends with its settled verdict.
#[test]
fn reorganize_run_over_the_metabolism_example_matches_the_fixture() {
    let fixture = fixture();
    let law = &fixture["run"];
    let document = metabolism();
    let layout = layout_graph(&document);
    assert_eq!((layout.graph.nodes.len() as u64, layout.graph.edges.len() as u64), (law["nodes"].as_u64().expect("nodes"), law["edges"].as_u64().expect("edges")));
    let mut job = LayoutRunJob::new(identity(), &layout.graph, LayoutRunConfig::default(), move_encoder(layout.node_ids.clone())).expect("job");
    let recording = layout_run_drive(&mut job, 1).expect("the run completes");
    let stop = serde_json::to_value(job.stop().expect("stopped")).expect("stop");
    let digest = job.positions_digest();
    let positions = job.positions();
    layout_run_close(&mut job);
    let prefix: Vec<String> = recording.upserts.iter().take(24).map(|(key, verdict, reason)| format!("{key}:{}/{}", verdict_id(*verdict), LayoutRunReason::from_code(*reason).expect("reason").id())).collect();
    assert_eq!(stop, law["stop"]);
    assert_eq!(format!("{digest:016x}"), law["positionsDigest"].as_str().expect("digest"), "the metabolism layout is bit-deterministic");
    assert_eq!(recording.progress.as_ref().map(|progress| progress.completed), law["iterations"].as_u64());
    assert_eq!(u64::from(recording.checkpoints), law["checkpoints"].as_u64().expect("checkpoints"));
    assert_eq!(serde_json::to_value(&prefix).expect("prefix"), law["verdictPrefix"]);
    let moved = law["movedNodes"].as_u64().expect("moved") as usize;
    assert_eq!(recording.ops.len(), moved, "finalize publishes exactly one op per moved node");
    let ops: Vec<WiresMutation> = recording.ops.iter().map(|bytes| protocol::OpBinary::decode_op(bytes).expect("move op decodes")).collect();
    let mut expected_entities = BTreeSet::new();
    for op in &ops {
        let WiresMutation::MoveNode(payload) = op else { panic!("only move-node ops are provisional: {op:?}") };
        let index = layout.node_ids.iter().position(|id| *id == payload.node_id).expect("moved node is laid out");
        assert_eq!((payload.new_x, payload.new_y), (positions[index].x, positions[index].y), "the op carries the final position");
        expected_entities.insert(layout_run_entity(&payload.node_id));
    }
    assert_eq!(recording.entity_set(), expected_entities, "the provisional entity set is the moved nodes");
    let mut verdicts: BTreeMap<&str, u64> = BTreeMap::new();
    for (_, record) in recording.trace.as_ref().expect("trace").records() {
        *verdicts.entry(verdict_id(record.verdict)).or_default() += 1;
    }
    assert_eq!(serde_json::to_value(&verdicts).expect("verdicts"), law["finalVerdicts"]);
    assert!(matches!(job.stop(), Some(LayoutRunStop::Converged | LayoutRunStop::IterationLimit)));
    let per_iteration = recording.step_micros.len() as u64;
    assert!(per_iteration >= law["iterations"].as_u64().expect("iterations"), "at least one step per iteration");
}

/// 🔮️ Layout quality on the real document: the run's normalized stress stays within the fixture ratio of the
/// `fdg-sim` Fruchterman-Reingold layout from the same start and improves the committed layout.
#[test]
fn reorganize_layout_quality_matches_the_fdg_sim_oracle() {
    let fixture = fixture();
