        pinned: vec![BitmapPinnedPixel { x: 0, y: 0, color: 2 }],
        ..BitmapSnapshot::default()
    };
    assert_eq!(solve_with_clock(&snapshot, semio_framework_job::logical_now_us).unwrap_err(), "bitmap-inference-unreachable-pin");
}

