const DIFF: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/🚦️change-script-limits/✅apply/🔺️diff/🔣️.json");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/🚦️change-script-limits/✅apply/🎯️outcome/🔣️.json");
fn before() -> Iso16757Snapshot { semio_framework_pack_json::from_json_str(BEFORE, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("before") }
fn mutation() -> Iso16757Mutation { semio_framework_pack_json::from_json_str(MUTATION, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("mutation") }
fn apply(mutation: &Iso16757Mutation, base: &Iso16757Snapshot) -> Iso16757Snapshot {
    let raised = <Iso16757Mutation as protocol::Mutation<Iso16757Snapshot>>::diff(mutation, base);
    assert!(raised.messages().is_empty(), "change-script-limits raised {:?}", raised.messages());
    <Iso16757Diff as protocol::MutationDiff<Iso16757Snapshot>>::apply(raised.diff(), base).expect("apply")
}
#[test]
fn mutation_is_the_canonical_wire() {
    let _: Iso16757Mutation = store::os_store::test_support::assert_wire_witness(MUTATION);
}
#[test]
fn applies_to_committed_after_and_diff() {
    let base = before();
    let raised = <Iso16757Mutation as protocol::Mutation<Iso16757Snapshot>>::diff(&mutation(), &base);
    assert_eq!(*raised.diff(), semio_framework_pack_json::from_json_str::<Iso16757Diff>(DIFF).expect("diff"));
    let after = apply(&mutation(), &base);
    assert_ne!(after, base, "change-script-limits must move the document");
    assert_eq!(after, semio_framework_pack_json::from_json_str::<Iso16757Snapshot>(AFTER).expect("after"));
}
#[test]
fn inverse_restores_before() {
    let base = before();
    let inverse = <Iso16757Mutation as protocol::Mutation<Iso16757Snapshot>>::inverse(&mutation(), &base);
    assert!(!inverse.is_empty(), "change-script-limits changes the document, so its inverse must not be empty");
    let restored = inverse.iter().fold(apply(&mutation(), &base), |snapshot, step| apply(step, &snapshot));
    assert_eq!(restored, base);
}
#[test]
fn declared_outcome_holds() {
    assert_eq!(serde_json::from_str::<serde_json::Value>(OUTCOME).expect("outcome")["status"], "applied");
}

//! 🏛️ ANSI/ASHRAE Standard 140 §5.2 (BESTEST) building-thermal-envelope and fabric-load cases,
//! authored directly against this engine's own typed [`crate::model::Model`].
//!
//! Case 600 is the standard's base case and every other §5.2 case is defined as a delta from it,
//! so this module is shaped the same way: one shared catalogue of ASHRAE 140 materials,
//! constructions, geometry and schedules, then one `case_*` function per case that states only its
//! own delta. The numbers are the standard's own §5.2 tables, handcrafted here — never generated,
//! never scraped.
//!
//! Reference cross-checks: NREL/TP-550-43827 *EnergyPlus Testing with ANSI/ASHRAE Standard 140*
//! carries the reference envelopes; NREL's `BESTEST-GSR` repository carries the same case set as
//! OpenStudio measures. Neither is consumed here — this is an independent authoring of the spec.

use crate::air_exchange::InfiltrationMethod;
use crate::error::{Diagnostics, Error};
use crate::kernel::{SimulationConfig, SimulationEnvironment};
use crate::model::{
    Construction, EntityId, EquipmentGain, Fenestration, GasKind, GasMaterial, GlazingMaterial, IdealLoadsSystem, Infiltration, Material, MechanicalVentilation, Model, OutsideBoundary, ScheduleId, ShadingSurface, Site, Surface, SurfaceClass,
    SurfaceRoughness, Thermostat, Zone,
};
use crate::results::Results;
use crate::schedule::{ConstantSchedule, DailySchedule, ScheduleInterpolation, ScheduleSet};
use crate::site::WeatherData;

// #region 🔖️Registry
/// 🗂️ Every §5.2 case this engine can build, in the standard's own order.
pub const CASES: &[&str] = &["600", "600FF", "610", "620", "630", "640", "650", "900", "900FF", "910", "920", "930", "940", "950"];

/// 🏛️ Build one case's model, or `None` for an id outside [`CASES`].
pub fn model(case: &str) -> Option<Model> {
    let built = match case {
        "600" => case_600(),
        "600FF" => free_float(case_600(), "BESTEST 600FF"),
        "610" => case_610(),
        "620" => case_620(),
        "630" => case_630(),
        "640" => case_640(),
        "650" => case_650(),
        "900" => high_mass(case_600(), "BESTEST 900"),
        "900FF" => free_float(high_mass(case_600(), "BESTEST 900FF"), "BESTEST 900FF"),
        "910" => high_mass(case_610(), "BESTEST 910"),
        "920" => high_mass(case_620(), "BESTEST 920"),
        "930" => high_mass(case_630(), "BESTEST 930"),
        "940" => high_mass(case_640(), "BESTEST 940"),
        "950" => high_mass(case_650(), "BESTEST 950"),
        _ => return None,
    };
    Some(built)
}

/// 🌡️ True for the free-float cases, which carry no HVAC at all and are judged on zone temperature
/// rather than on delivered energy.
pub fn is_free_float(case: &str) -> bool {
    case.ends_with("FF")
}
