//! 📜️ Trinity Rewriting app command — `delete-rule-clause`.

use crate::standards::v1::subsets::any::schema::mutations::text::RewriteRuleMutation;
use crate::standards::v1::subsets::any::schema::mutations::{edit_lhs, edit_rhs, remove_parameter_binding, remove_rule_layout_point};
use crate::standards::v1::subsets::any::schema::{self, Rhs};
use crate::RewritingSnapshot;

/// 🧭️ One addressable rule-clause node in the LHS/RHS semantic graphs (`lhs-where`, `rhs-create-N`,
/// `rhs-merge-N`, `rhs-set-N`, `rhs-delete-N`, `rhs-parameter-N`) — parsed back from its synthetic
/// node id by `parse_clause_ref`.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum RuleClauseRef {
    LhsWhere,
    RhsCreate(usize),
    RhsMerge(usize),
    RhsSet(usize),
    RhsDelete(usize),
    RhsParameter(usize),
}

fn parse_clause_ref(node_id: &str) -> Option<RuleClauseRef> {
    if node_id == "lhs-where" {
        return Some(RuleClauseRef::LhsWhere);
    }
    let (prefix, index) = node_id.rsplit_once('-')?;
    let index: usize = index.parse().ok()?;
    match prefix {
        "rhs-create" => Some(RuleClauseRef::RhsCreate(index)),
        "rhs-merge" => Some(RuleClauseRef::RhsMerge(index)),
        "rhs-set" => Some(RuleClauseRef::RhsSet(index)),
        "rhs-delete" => Some(RuleClauseRef::RhsDelete(index)),
        "rhs-parameter" => Some(RuleClauseRef::RhsParameter(index)),
        _ => None,
    }
}

fn remove_at<T>(items: &mut Vec<T>, index: usize) -> Option<T> {
    (index < items.len()).then(|| items.remove(index))
}

/// 🗑️ The leaves that drop the rule clauses `node_ids` address: ONE `edit-lhs` and/or `edit-rhs` carrying each side without
/// them, a `remove-parameter-binding` per dropped parameter clause that had a binding, and a `remove-rule-layout-point` per
/// dropped clause that had a layout point. Clauses of one list are dropped from the highest index down, so every id names the
/// clause it named in the committed rule; ids that name no clause, and an undecodable rule, drop nothing.
pub(crate) fn delete_rule_clauses(state: &RewritingSnapshot, node_ids: &[String]) -> Vec<RewriteRuleMutation> {
    let (Ok(mut lhs), Ok(mut rhs)) = (semio_framework_pack_json::from_json_str::<schema::Lhs>(&state.lhs_json), semio_framework_pack_json::from_json_str::<Rhs>(&state.rhs_json)) else {
        return Vec::new();
    };
    let mut clauses: Vec<(RuleClauseRef, &String)> = node_ids.iter().filter_map(|id| parse_clause_ref(id).map(|clause| (clause, id))).collect();
    clauses.sort_by(|left, right| right.0.cmp(&left.0));
    clauses.dedup_by(|left, right| left.0 == right.0);
    let (mut lhs_changed, mut rhs_changed, mut removed) = (false, false, Vec::new());
    for (clause, id) in clauses {
        let dropped = match clause {
            RuleClauseRef::LhsWhere => {
                lhs_changed |= lhs.where_clause.take().is_some();
                lhs_changed
            }
            RuleClauseRef::RhsCreate(index) => remove_at(&mut rhs.create, index).is_some(),
            RuleClauseRef::RhsMerge(index) => remove_at(&mut rhs.merge, index).is_some(),
            RuleClauseRef::RhsSet(index) => remove_at(&mut rhs.set, index).is_some(),
            RuleClauseRef::RhsDelete(index) => remove_at(&mut rhs.delete, index).is_some(),
            RuleClauseRef::RhsParameter(index) => match remove_at(&mut rhs.parameters, index) {
                Some(parameter) => {
                    removed.extend(state.parameter_bindings.contains_key(&parameter.name).then(|| remove_parameter_binding(parameter.name)));
                    true
                }
                None => false,
            },
        };
        rhs_changed |= dropped && clause != RuleClauseRef::LhsWhere;
        removed.extend((dropped && state.rule_layout.contains_key(id)).then(|| remove_rule_layout_point(id.clone())));
    }
    let sides = [lhs_changed.then(|| edit_lhs(semio_framework_pack_json::to_json_string(&lhs))), rhs_changed.then(|| edit_rhs(semio_framework_pack_json::to_json_string(&rhs)))];
    sides.into_iter().flatten().chain(removed).collect()
}

//! 📜️ 📜️ Trinity Rewriting app command — `set-parameter`.

use crate::standards::v1::subsets::any::schema::mutations::change_parameter_binding;
use crate::standards::v1::subsets::any::schema::mutations::text::RewriteRuleMutation;
use crate::standards::v1::subsets::any::schema::{ParameterKind, Rhs};
use crate::RewritingSnapshot;
use semio_framework_graph::manifest::PropertyValue;
use semio_framework_plugin::Emit;
use semio_framework_plugin::NoConfigMutation;

/// 🎛️ One rule parameter's bound value, read by its declared kind, as ONE `change-parameter-binding {key, newValue}` — the
/// field-parametric leaf history edits; a value the binding already holds, an unknown name's unparseable number or an empty
/// name moves nothing. The parameters window commits it once per field, on blur or Enter (design §13.2).
pub(crate) fn set_parameter(state: &RewritingSnapshot, name: &str, value: &str) -> Emit<RewriteRuleMutation, NoConfigMutation> {
    if name.is_empty() {
        return Emit::default();
    }
    let Ok(rhs) = semio_framework_pack_json::from_json_str::<Rhs>(&state.rhs_json) else {
        return Emit::default();
    };
    let kind = rhs.parameters.iter().find(|param| param.name == name).map(|param| param.kind.clone());
    let parsed = match kind {
        Some(ParameterKind::Number) => value.parse::<f64>().ok().map(PropertyValue::Number),
        Some(ParameterKind::Boolean) => Some(PropertyValue::Bool(value.eq_ignore_ascii_case("true"))),
        Some(ParameterKind::String) | None => Some(PropertyValue::String(value.to_string())),
    };
    match parsed {
        Some(parsed) if state.parameter_bindings.get(name) != Some(&parsed) => Emit::mutations(vec![change_parameter_binding(name.to_string(), parsed)]),
        _ => Emit::default(),
    }
}

//! 📜️ 📜️ Trinity Rewriting app command — `add-rule-clause-command`.

use crate::standards::v1::subsets::any::schema::mutations::text::RewriteRuleMutation;
use crate::standards::v1::subsets::any::schema::mutations::{change_parameter_binding, edit_lhs, edit_rhs};
use crate::standards::v1::subsets::any::schema::{self, ParameterKind, Rhs};
use crate::RewritingSnapshot;
use semio_framework_graph::manifest::PropertyValue;
use semio_framework_plugin::{Emit, Fault, FaultCode, FaultOrigin, NoConfigMutation};

/// ➕️ The leaves that add one clause of `clause_kind` to the rule: `edit-lhs` for a WHERE clause, `edit-rhs` for every other
/// clause (plus the new parameter's `change-parameter-binding`), so the edit carries no re-printed copy of the untouched side. A
/// request that cannot move the rule is refused by name — a second WHERE clause, an unknown clause kind, or a rule whose own JSON
/// no longer decodes — instead of answering an empty emit that read as an accepted edit (S15).
fn add_rule_clause(state: &RewritingSnapshot, clause_kind: &str) -> Result<Vec<RewriteRuleMutation>, Fault> {
    let invalid = |detail: String| Fault::new(FaultOrigin::App, FaultCode::new("app.command.invalid-args"), detail);
    let undecodable = |side: &str, error: String| Fault::new(FaultOrigin::App, FaultCode::new("trinity.rewriting.rule-undecodable"), format!("the rule's {side} does not decode: {error}"));
    let mut lhs = semio_framework_pack_json::from_json_str::<schema::Lhs>(&state.lhs_json).map_err(|error| undecodable("LHS", error.to_string()))?;
    let mut rhs = semio_framework_pack_json::from_json_str::<Rhs>(&state.rhs_json).map_err(|error| undecodable("RHS", error.to_string()))?;
    let left_var = lhs.pattern.left_var.clone();
    let mut bindings = Vec::new();
    match clause_kind {
        "where" if lhs.where_clause.is_some() => return Err(invalid("the rule already has a WHERE clause".into())),
        "where" => {
            lhs.where_clause = Some(format!("{left_var}.name = 'value'"));
            return Ok(vec![edit_lhs(semio_framework_pack_json::to_json_string(&lhs))]);
        }
        "create" => rhs.create.push(schema::PatternJson { left_var: "n".into(), left_kind: "Piece".into(), edge_var: None, edge_kind: None, right_var: None, right_kind: None }),
        "merge" => rhs.merge.push(schema::PatternJson { left_var: "n".into(), left_kind: "Piece".into(), edge_var: None, edge_kind: None, right_var: None, right_kind: None }),
        "set" => rhs.set.push(schema::AssignmentJson { var: left_var, prop: "label".into(), value: PropertyValue::String(String::new()) }),
        "delete" => rhs.delete.push(left_var),
        "parameter" => {
            let name = format!("param{}", rhs.parameters.len());
            bindings.push(change_parameter_binding(name.clone(), PropertyValue::String(String::new())));
            rhs.parameters.push(schema::ParameterSpec { name, kind: ParameterKind::String, default: PropertyValue::String(String::new()) });
        }
        other => return Err(invalid(format!("unknown rule clause kind '{other}' (where, create, merge, set, delete, parameter)"))),
    }
    Ok(std::iter::once(edit_rhs(semio_framework_pack_json::to_json_string(&rhs))).chain(bindings).collect())
}

/// ➕️ The `addRuleClause` verb: one edit adding the requested clause, or a named refusal.
pub(crate) fn add_rule_clause_command(state: &RewritingSnapshot, kind: &str) -> Result<Emit<RewriteRuleMutation, NoConfigMutation>, Fault> {
    Ok(Emit::mutations(add_rule_clause(state, kind)?))
}

//! 🎛️ Trinity Rewriting app — Parameters window (editable form over the RHS's declared parameters). Every field is a short
//! single-line input that commits once, on blur or Enter (`commit: "blur"`): one edit per changed parameter, never one per
//! keystroke (design §13.2 of ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING).

use crate::editor::rewriting::terminology::TrinityRewritingLabels;
use crate::standards::v1::subsets::any::schema::{self, ParameterKind, Rhs};
use crate::RewritingSnapshot;
use semio_framework_graph::manifest::PropertyValue;
use semio_framework_ui_locale::Label;
use semio_framework_ui_contract::{Buildable, HasBase, HasChildren, InputKind, Trigger};

trait ParameterKindLabel {
    fn kind_label(&self) -> String;
}

impl ParameterKindLabel for schema::ParameterSpec {
    fn kind_label(&self) -> String {
        match self.kind {
            ParameterKind::String => "string".into(),
            ParameterKind::Number => "number".into(),
            ParameterKind::Boolean => "boolean".into(),
        }
    }
}

pub(crate) fn render(state: &RewritingSnapshot, labels: &TrinityRewritingLabels) -> semio_framework_plugin::UiAssemblyResult<semio_framework_plugin::BuiltNode> {
    let Ok(rhs) = semio_framework_pack_json::from_json_str::<Rhs>(&state.rhs_json) else {
        return semio_framework_plugin::built_text_node(Label::data("Invalid RHS")).map_err(|_| semio_framework_plugin::PluginAssemblyError::new("trinity.parameters.invalid", "the fixed invalid-RHS label exceeds its UI bound"));
    };
    let mut children = semio_framework_plugin::UiFixedList::<semio_framework_plugin::BuiltNode>::default();
    for param in &rhs.parameters {
        let value = state.parameter_bindings.get(&param.name).cloned().unwrap_or_else(|| param.default.clone());
        let display = match value {
            PropertyValue::String(text) => text,
            PropertyValue::Number(number) => number.to_string(),
            PropertyValue::Bool(flag) => flag.to_string(),
            _ => String::new(),
        };
        let input_kind = match param.kind {
            ParameterKind::Number => InputKind::Number,
            ParameterKind::Boolean | ParameterKind::String => InputKind::Text,
        };
        let input_id = format!("trinity-rewriting.param.{}.input", param.name);
        let input_value = semio_framework_plugin::UiText::try_from_string(display).map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter value admission failed"))?;
        let placeholder = crate::editor::rewriting::ui_label(param.kind_label())?;
        let args = crate::editor::rewriting::ui_value_map([("name", crate::editor::rewriting::ui_value_text(&param.name)?)])?;
        let (action, args) = crate::editor::rewriting::rewriting_action("setParameter", Some(args))?;
        let commit = semio_framework_plugin::UiText::try_from_str("blur").ok_or_else(|| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter commit admission failed"))?;
        let input = semio_framework_ui_contract::input(input_kind)
            .value(input_value)
            .placeholder(placeholder)
            .commit(commit)
            .try_id(&input_id)
            .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter input id admission failed"))?;
        let input = match args {
            Some(args) => input.try_on_with(Trigger::Commit, action, args),
            None => input.try_on(Trigger::Commit, action),
        }
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter input action admission failed"))?
        .try_build()
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter input admission failed"))?;
        let field_id = format!("trinity-rewriting.param.{}", param.name);
        let field = semio_framework_ui_contract::field(crate::editor::rewriting::ui_label(&param.name)?)
            .try_id(&field_id)
            .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter field id admission failed"))?
            .try_child(input)
            .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter field child admission failed"))?
            .try_build()
            .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter field admission failed"))?;
        children.try_push(field).map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter field list admission failed"))?;
    }
    if children.is_empty() {
        return semio_framework_plugin::built_text_node(Label::data("No parameters declared on RHS.")).map_err(|_| semio_framework_plugin::PluginAssemblyError::new("trinity.parameters.empty", "the fixed empty-parameters label exceeds its UI bound"));
    }
    semio_framework_ui_contract::column()
        .try_id("trinity-rewriting.parameters")
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter column id admission failed"))?
        .try_children(children)
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter column children admission failed"))?
        .try_label(labels.parameters.as_str())
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter column label admission failed"))?
        .try_build()
        .map_err(|_| semio_framework_plugin::PluginAssemblyError::new("ui.fixed-capacity", "parameter column admission failed"))
}

