        match command {
            TrinityRewritingCommand::NodeGraphEdit { .. } => "nodeGraphEdit",
            TrinityRewritingCommand::SetLhsJson { .. } => "setLhsJson",
            TrinityRewritingCommand::SetRhsJson { .. } => "setRhsJson",
