const MUTATION: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-tower-leg/⛔dupe/🦠️mutation/🔣️.json");
const DIFF_ABSENT: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-tower-leg/⛔dupe/🔺️diff/🚫️.absent");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-tower-leg/⛔dupe/🎯️outcome/🔣️.json");
