use crate::{En1993Diff, En1993Mutation, En1993Snapshot};
const BEFORE: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➖️remove-cold-formed-member/✅apply/📸️snapshot/⬅️before/🔣️.json");
