    let fixture: Value = serde_json::from_str(include_str!("../../../../../🚪️lifetime/🏗️construction.json")).unwrap();
    let law = &fixture["constructionFailure"];
    let runtime = crate::plugin_runtime::PluginRuntime::<TestRuntimeApps>::new();
