        old.finish();
        assert_eq!(serde_json::json!(cancellations.active_operation_count() == 1 && !replacement.token.is_cancelled_now()), fixture["deferredFinish"]["replacementPreserved"]);
        replacement.finish();
        assert_eq!(cancellations.active_operation_count(), 0);
    }

