//#region ShellActions
/// 🧵️ One shell turn's state machine, boxed at the turn's definition (ticket 26/09/23 session 14b): a caller's await site holds this
/// pointer instead of the whole turn, which a debug build otherwise copies into its own stack slots at every await site
/// (`dispatch_action`'s poll frame was 841 KB and the live hub gate's first authored edit overflowed a 2 MiB test thread).
#[cfg(not(target_arch = "wasm32"))]
pub type ShellTurn<'a, R> = std::pin::Pin<Box<dyn std::future::Future<Output = R> + Send + 'a>>;
/// 🧵️ See the native [`ShellTurn`]; a browser turn is not `Send`.
#[cfg(target_arch = "wasm32")]
pub type ShellTurn<'a, R> = std::pin::Pin<Box<dyn std::future::Future<Output = R> + 'a>>;

/// 📦️ Moves one turn's body to the heap as a [`ShellTurn`]; `R` comes from the turn's declared output, so `?` inside infers.
#[cfg(not(target_arch = "wasm32"))]
fn shell_turn<'a, R>(turn: impl std::future::Future<Output = R> + Send + 'a) -> ShellTurn<'a, R> {
    Box::pin(turn)
}
/// 📦️ See the native [`shell_turn`].
#[cfg(target_arch = "wasm32")]
fn shell_turn<'a, R>(turn: impl std::future::Future<Output = R> + 'a) -> ShellTurn<'a, R> {
    Box::pin(turn)
}

impl ShellState {
    //#region 🔖️NativeBackboneSync
    /// 🧭️ Parses a local sync-card uri into the `framework/sync` persistence bindings a
    /// document actor opens. `folder://` → the multi-document append-only event log; `file://x.json` → its
    /// parent folder's store (single-blob export demoted per the plan). A `remote://` uri names a hub
    /// document of its own and is read by [`parse_remote_backbone_uri`]; one missing a part is refused.
    fn parse_persistence_binding(uri: &str) -> Result<Vec<PersistenceBinding>, String> {
        if uri.starts_with("remote://") {
            return Err(format!("a remote backbone names host, space and document: {uri}"));
        }
        if let Some(path) = uri.strip_prefix("folder://") {
            return Ok(vec![PersistenceBinding::Folder { path: std::path::PathBuf::from(path) }]);
        }
        if let Some(path) = uri.strip_prefix("file://") {
            let parent = std::path::Path::new(path).parent().map(std::path::Path::to_path_buf).unwrap_or_else(|| std::path::PathBuf::from("."));
            return Ok(vec![PersistenceBinding::Folder { path: parent }]);
        }
        Err(format!("unsupported backbone uri: {uri}"))
    }

    fn mint_sync_binding_generation(&mut self) -> Result<u64, String> {
        let generation = self.next_sync_binding_generation;
        self.next_sync_binding_generation = generation.checked_add(1).ok_or("document-backbone binding generation exhausted")?;
        Ok(generation)
    }

    fn active_sync_owner(&self) -> Option<ShellSyncOwner> {
        self.sync_channel.as_ref().map(shell_sync_channel_owner)
    }

    /// ✂️ Retires the guest's exact generation before stopping the actor. A refusal still
    /// closes the local owner and is returned to the caller; it is never retried or hidden.
    async fn detach_sync_backbone_internal(&mut self) -> Result<(), String> {
        #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.document_execution_target_lease=None;
        let owner = self.active_sync_owner();
        let retirement = if let Some(owner) = owner.as_ref() {
            match self.plugins.iter().find(|entry| entry.plugin_id == owner.plugin_id).cloned() {
                Some(plugin) => plugin.retire_document_backbone(owner.instance_id, owner.binding_generation, &owner.actor_uri).await,
                None => Err("document-backbone plugin owner is missing".into()),
            }
        } else {
            Ok(Vec::new())
        };
        if let (Some(owner), Ok(effects)) = (owner.as_ref(), retirement.as_ref()) {
            if self.active_sync_owner().as_ref().is_some_and(|active| shell_sync_owner_matches(active, owner)) {
                if let Some(channel) = self.sync_channel.as_ref() {
                    let remaining = route_document_backbone_effects(&channel.actor_uri, &channel.cmd_tx, effects.clone())?;
                    if let Some(session) = self.session.as_ref() {
                        self.queue_host_effects(&session.app.controller_id.clone(), remaining);
                    }
                }
            }
        }
        #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.document_execution_target_lease=None;
        if let Some(channel) = self.sync_channel.take() {
            self.hub_documents.remove(&shell_hub_document_key(&channel.document_key));
            let _ = channel.cmd_tx.send(ArtifactActorMsg::Detach);
            self.document_host.close_key(&channel.document_key);
        }
        self.sync_status = None;
        self.sync_bootstrap_progress = None;
        self.sync_reseed = None;
        self.presence_peers.clear();
        self.presence_surface = None;
        self.presence_self = None;
        retirement.map(|_| ())
    }

    /// 📬️ Drains the active document actor's event stream into the plugin store and the sync
    /// badge. Called once per frame-deferred pump on both targets — the render loop already redraws
    /// continuously, so a `try_recv` poll suffices and no `EventLoopProxy` wake is needed.
    /// `RemoteMutations` are force-applied via `apply_mutations` (idempotent by operation id), which also covers
    /// idle frames where the sandboxed store never pumps its `ChannelBackbone` on its own. Returns
    /// whether anything changed. Only a change to the guest's document refreshes the guest's bodies: a
    /// status, bootstrap or conflict change republishes the host-owned Sync panel, and a presence roster
    /// is painted from shell state by the footer on the next frame. Refreshing every guest body per
    /// presence frame (ten per second per peer) held each pump for 3.4–5.6 s in a debug build and froze
    /// the shell while a peer was online (ticket 26/09/23 slice WG8, two-user gate run 15).
    ///
    /// 📇️ ticket §1/§3 — non-blocking identity bootstrap result + directory-stream/command-queue
    /// drain, folded into this same every-frame pump (glue.rs's frame loop already calls this
    /// method once per tick; adding a second call site outside this lane's lease was avoidable).
    ///
    /// 📌️ ticket §C5 item 2 — the auto check-in poll, folded into the same every-frame pump for the
    /// identical reason (no timer wheel exists in this shell; see `auto_checkin_should_fire`'s doc).
    ///
    /// 🎠️ H3-wgpu-native — `apply_mutations` now runs its plugin turn on the
    /// dedicated kernel thread instead of in-process here; `.await` is the only
    /// change this call site needs (`pump_sync_events` was already `async fn`).
    ///
    /// 👥️ ticket §5 — shell-LOCAL roster (deliberately NOT the shared kernel
    /// `ViewModel`, which still has no presence field). Rendered by
    /// `render_presence_bar` in the footer, scoped to `presence_surface`.
    ///
    /// 👥️ This connection's hub-admitted identity (actor + colour), sent once per connection.
    /// The sync actor stamps it onto outbound heartbeats itself; the shell keeps it so its
    /// board overlays leave the local actor out and paint in the hub's own colour.
    ///
    /// 👻️ Ephemeral peer previews (wire v2's uncredited preview lane) have no native
    /// wgpu shell UI yet — same documented-follow-up status as `Presence` above.
    ///
    /// 📮️ Terminal batch dispositions (accepted/transformed/rejected) have no native
    /// wgpu shell surfacing yet — `RemoteMutations`/rollback already keep document
    /// state correct; this event is purely informational until a UI is built for it.
    pub async fn pump_sync_events(&mut self) -> bool {
        use tokio::sync::broadcast::error::TryRecvError;
        #[cfg(not(target_arch = "wasm32"))]
        let shell_io_changed = self.poll_shell_io();
        #[cfg(target_arch = "wasm32")]
        let shell_io_changed = false;
        let directory_changed = self.pump_directory_events().await || shell_io_changed;
        #[cfg(not(target_arch = "wasm32"))]
        let directory_changed = self.poll_time_travel_progress().await || directory_changed;
        let directory_changed = self.drain_progress_history_patches().await || directory_changed;
        let directory_changed = self.publish_peer_time_travel_notes() || directory_changed;
        let directory_changed = self.reattach_remembered_local_folder().await || directory_changed;
        #[cfg(target_arch = "wasm32")]
        let directory_changed = self.flush_host_route_folder().await || directory_changed;
        self.poll_auto_checkin().await;
        let directory_changed = self.advance_document_opening().await || directory_changed;
        let directory_changed = self.advance_sync_reseed().await || directory_changed;
        if let Some(error) = self.sync_terminal_fault.take() {
            Self::debug_log(&format!("[TRACE] wgpu shell retired document-backbone owner after terminal fault: {error}"));
            let _ = self.detach_sync_backbone_internal().await;
            self.sync_card_kind = Some("conflict".into());
            self.relabel_sync_tab();
            return true;
        }
        let (owner, events) = {
            let Some(channel) = self.sync_channel.as_mut() else {
                return directory_changed;
            };
            let mut events: Vec<ArtifactEvent> = Vec::new();
            loop {
                match channel.events.try_recv() {
                    Ok(event) => events.push(event),
                    Err(TryRecvError::Empty) | Err(TryRecvError::Closed) => break,
                    Err(TryRecvError::Lagged(_)) => continue,
                }
            }
            if events.is_empty() {
                return directory_changed;
            }
            (shell_sync_channel_owner(channel), events)
        };
        let instance_id = owner.instance_id;
        let plugin = self.plugins.iter().find(|entry| entry.plugin_id == owner.plugin_id).cloned();
        let mut changed = directory_changed;
        let mut document_changed = false;
        let mut sync_panel_changed = false;
        for event in events {
            match event {
                ArtifactEvent::RemoteMutations { envelopes } => {
                    if let Some(plugin) = plugin.as_ref() {
                        let operations = protocol::encode_envelopes(&envelopes);
                        match plugin.apply_mutations(instance_id, &operations).await {
                            Ok(()) => {
                                changed = true;
                                document_changed = true;
                            }
                            Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell apply_mutations failed: {error}")),
                        }
                    }
                }
                ArtifactEvent::DocumentArchiveReplaced { archive } => {
                    self.sync_bootstrap_progress = None;
                    if let Some(plugin) = plugin.as_ref() {
                        let archive = match protocol::decode_document_archive_bytes(&archive).await {
                            Ok(archive) => archive,
                            Err(error) => {
                                Self::debug_log(&format!("[TRACE] wgpu shell recursive document archive decode failed: {error}"));
                                continue;
                            }
                        };
                        match plugin.load_app_document_archive(instance_id, &archive).await {
                            Ok(()) => {
                                self.refresh_history_snapshot().await;
                                changed = true;
                                document_changed = true;
                            }
                            Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell load_app_document_archive failed: {error}")),
                        }
                    }
                }
                ArtifactEvent::BootstrapProgress { received_bytes, total_bytes, received_chunks, total_chunks } => {
                    self.sync_bootstrap_progress = Some((received_bytes, total_bytes, received_chunks, total_chunks));
                    changed = true;
                    sync_panel_changed = true;
                }
                ArtifactEvent::Status(status) => {
                    if let Some(document_key) = self.sync_channel.as_ref().map(|channel| shell_hub_document_key(&channel.document_key)) {
                        self.publish_hub_document_status(document_key, shell_hub_remote(&status.remote));
                    }
                    self.sync_link = shell_sync_link_after_status(self.sync_link, &status.remote);
                    self.sync_status = Some(status);
                    changed = true;
                    sync_panel_changed = true;
                }
                ArtifactEvent::RebootstrapRequired { control } => {
                    self.sync_reseed = Some(ShellSyncReseed { control, pending: None, retry_at_ms: 0.0 });
                    changed = true;
                    sync_panel_changed = true;
                }
                ArtifactEvent::Presence { peers } => {
                    self.presence_peers = peers;
                    changed = true;
                }
                ArtifactEvent::Conflict(message) => {
                    if let Some((code, text, severity)) = time_travel::history_refusal_notice(&message.code.0, self.active_locale()) {
                        self.show_transient_notice(text, severity, Some(code));
                    }
                    if let Some(terminal) = shell_sync_link_terminal(&message.code.0) {
                        self.sync_link = terminal;
                        self.sync_terminal_fault = Some(message.message);
                    }
                    self.sync_card_kind = Some("conflict".into());
                    changed = true;
                    sync_panel_changed = true;
                }
                ArtifactEvent::Session { actor, color } => {
                    self.presence_self = Some((actor, color));
                    changed = true;
                }
                ArtifactEvent::DocumentBackbone { message } => {
                    let result = match plugin.as_ref() {
                        Some(plugin) => plugin.receive_document_backbone(owner.instance_id, &owner.actor_uri, message).await,
                        None => Err("document-backbone plugin owner is missing".into()),
                    };
                    match result {
                        Ok(effects) if self.active_sync_owner().as_ref().is_some_and(|active| shell_sync_owner_matches(active, &owner)) => {
                            let routed = self.sync_channel.as_ref().ok_or_else(|| "document-backbone owner retired before completion".to_string()).and_then(|channel| route_document_backbone_effects(&channel.actor_uri, &channel.cmd_tx, effects));
                            match routed {
                                Ok(remaining) => {
                                    let controller_id = self.session.as_ref().map(|session| session.app.controller_id.clone()).unwrap_or_default();
                                    self.queue_host_effects(&controller_id, remaining);
                                    changed = true;
                                    document_changed = true;
                                }
                                Err(error) => self.sync_terminal_fault = Some(error),
                            }
                        }
                        Ok(_) => {}
                        Err(error) => self.sync_terminal_fault = Some(error),
                    }
                }
                ArtifactEvent::Preview { .. } => {
                }
                ArtifactEvent::CommandOutcome { outcome: store_sync::sync::CommandAckOutcome::Rejected { code, messages, .. }, .. } => {
                    let (code, text, severity) = command_rejection_notice(code, &messages, self.active_locale());
                    self.show_transient_notice(text, severity, Some(code));
                    changed = true;
                }
                ArtifactEvent::CommandOutcome { outcome: store_sync::sync::CommandAckOutcome::Transformed, .. } => {
                    self.show_transient_notice(shell_chrome_string("conflict.hubTransformed", self.locale_id == "de"), semio_framework::Severity::Info, Some(SYNC_COMMAND_TRANSFORMED_NOTICE_CODE));
                    changed = true;
                }
                ArtifactEvent::CommandOutcome { .. } => {}
            }
            if self.sync_terminal_fault.is_some() {
                break;
            }
        }
        if let Some(error) = self.sync_terminal_fault.take() {
            Self::debug_log(&format!("[TRACE] wgpu shell retired document-backbone owner after terminal fault: {error}"));
            let _ = self.detach_sync_backbone_internal().await;
            self.sync_card_kind = Some("conflict".into());
            changed = true;
            document_changed = true;
        }
        if changed {
            self.relabel_sync_tab();
        }
        if document_changed {
            let _ = self.refresh_ui(UiDirtyScope::Full).await;
        } else if sync_panel_changed {
            let _ = self.republish_shell_panel_document(FRAMEWORK_SYNC_PANEL_TAB_ID);
        }
        changed
    }

    /// 🚦️ Rewrites the live dock's sync leaf label from the CURRENT pill. The label is baked into the dock
    /// when it is (re)built, so without this the footer pill — and its accessible name — kept `Remote:
    /// detached` after the actor reported `Live` until something else rebuilt the dock (measured, run s12c).
    fn relabel_sync_tab(&mut self) {
        let label = shell_sync_pill_text(self.sync_pill(), self.locale_id == "de");
        for anchor in PanelAnchor::ALL {
            if let Some(tab) = self.dock_tabs.tabs_mut(anchor).iter_mut().find(|tab| tab.id == FRAMEWORK_SYNC_PANEL_TAB_ID) {
                tab.label = label.clone();
            }
        }
    }

    /// 👥️ The roster `#s-presence-peers` paints, scoped to the attached surface. A document opened
    /// without a hub binding carries no surface and answers an empty roster — exactly the state
    /// React's footer renders as `No one else is here`, not a reason to omit the pill.
    ///
    /// ⏪️ A peer editing the history wears its time-travel activity (`time_travel::time_travel_peer_presence`).
    fn footer_presence_rows(&self) -> Vec<ui_wgpu::wgpu::PresencePeerRow> {
        let Some(surface) = self.presence_surface.as_deref() else { return Vec::new() };
        let mut rows = presence_peer_rows_for_surface(&self.presence_peers, Some(surface), surface);
        let mut activities = self.peer_time_travel_presence().activities;
        if !activities.is_empty() {
            for row in &mut rows {
                if let Some(index) = activities.iter().position(|(actor, _)| *actor == row.actor) {
                    row.activity = Some(activities.swap_remove(index).1);
                }
            }
        }
        rows
    }

    /// 🚦️ The `#s-sync-status` pill's state for the CURRENT session, the wgpu twin of
    /// `🛠️ShellHelpers/🟦️.tsx`'s `computeSyncPillState`: a non-live remote outranks a pending count,
    /// and "no status observed yet" reads as `Remote(Detached)`.
    ///
    /// Target-neutral because React's footer is: its browser shell paints `Remote: detached` from
    /// `computeSyncPillState(null)` with no backbone attached at all, and a document the browser
    /// host opened local-only never reports a remote, so it resolves to that same state.
    fn sync_pill(&self) -> ShellSyncPill {
        if let Some((received_bytes, total_bytes, received_chunks, total_chunks)) = self.sync_bootstrap_progress {
            return ShellSyncPill::Recovering { received_bytes, total_bytes, received_chunks, total_chunks };
        }
        let Some(status) = self.sync_status.as_ref() else { return ShellSyncPill::Remote(ShellSyncRemote::Detached) };
        if !matches!(status.remote, RemoteState::Live { .. }) {
            return ShellSyncPill::Remote(match &status.remote {
                RemoteState::Live { .. } => ShellSyncRemote::Connected,
                RemoteState::Connecting => ShellSyncRemote::Connecting,
                RemoteState::Backoff { .. } => ShellSyncRemote::Backoff,
                RemoteState::Detached => ShellSyncRemote::Detached,
            });
        }
        if status.pending_mutations > 0 {
            return ShellSyncPill::Pending(status.pending_mutations);
        }
        ShellSyncPill::Persisted
    }

    /// 📶️ This shell's hub projection over the schema's two shell axes and its attached documents. The
    /// session is held exactly while a verified `/auth/sessions/me` authority is: a hub is always
    /// configured here (the connection book keeps the local bootstrap hub), so this shell is never
    /// `none`. The link is what the identity lane last learned: a hub it could not reach while it kept
    /// the cached identity is `unreachable`, a verified authority `reachable`, anything else `verifying`.
    pub(crate) fn hub_projection(&self) -> ShellHubProjectionV1 {
        let session = if self.verified_session_authority.is_some() { HubSessionPresence::SignedIn } else { HubSessionPresence::SignedOut };
        let link = match (self.identity_offline, self.verified_session_authority.is_some()) {
            (true, _) => HubLink::Unreachable,
            (false, true) => HubLink::Reachable,
            (false, false) => HubLink::Verifying,
        };
        let documents = self.hub_documents.iter().map(|(document_key, remote)| ShellHubDocumentV1 { document_key: document_key.clone(), remote: remote.clone() }).collect();
        ShellHubProjectionV1 { session, link, documents }
    }

    pub(crate) fn publish_hub_document_status(&mut self, document_key: impl Into<String>, remote: ShellHubRemoteV1) {
        const HUB_DOCUMENT_CAPACITY: usize = 64;
        let document_key = document_key.into();
        if self.hub_documents.contains_key(&document_key) || self.hub_documents.len() < HUB_DOCUMENT_CAPACITY {
            self.hub_documents.insert(document_key, remote);
        }
    }

    pub(crate) fn retire_hub_document_status(&mut self, document_key: &str) {
        self.hub_documents.remove(document_key);
    }

    fn hub_connection_state(&self) -> HubConnectionState {
        shell_hub_connection_summary_v1(&self.hub_projection()).state
    }

    /// 🎭️ ticket §1 — contract §C0's `user:{userId}#{sessionId}` once identity is minted/restored,
    /// else the pre-identity local default this shell always used (`shell_actor`'s pure decision).
    fn current_shell_actor(&self, instance_id: u32) -> String {
        shell_actor(self.identity.as_ref(), &self.shell_session_id, instance_id)
    }
    //#endregion 🔖️NativeBackboneSync

    //#region 🔖️CheckIn
    /// 🧾️ ticket §C5 — resets the local history projection and re-seeds it from a full
    /// `ProgramBridgeEntry::read_history` snapshot (`replace=true`), called right after a document
    /// attaches (`open_document`/`attach_sync_backbone`'s native branch) so a just-opened document's
    /// own uncommitted-edit count starts from its OWN history, never a leftover projection from
    /// whatever was open before. Best-effort: a read failure just leaves the projection empty (the
    /// same posture every other native exchange call in this file already takes on error — logged, not
    /// propagated, since a stale/absent history must never block opening a document).
    async fn refresh_history_snapshot(&mut self) {
        self.history_cursor = 0;
        self.history_entries.clear();
        self.history_current_checkpoint_id = None;
        self.history_time_travel = None;
        self.last_uncommitted_edit_at_ms = None;
        self.auto_checkin_pending = false;
        self.checkpoint_dispatched = false;
        self.seed_history_snapshot().await;
    }

    /// 🧾️ The seeding half of [`Self::refresh_history_snapshot`]: the program's whole history projection, read through
    /// the native exchange's `ReadHistory` or the browser bridge's `readHistory` alike, so a session start or a restored
    /// archive shows its rows and head on both builds before the next `history_patch` folds in.
    ///
    /// ⚔️ A freshly attached document brings its own open conflicts with it — React seeds the
    /// Conflicts panel on the same session-start/switch edge; the `ReadConflicts` exchange is native-only.
    async fn seed_history_snapshot(&mut self) {
        let Some(session) = self.session.as_ref() else { return };
        let Some(plugin) = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id) else { return };
        match plugin.read_history(session.instance_id).await {
            Ok(patch) => {
                fold_history_patch(&mut self.history_entries, &mut self.history_cursor, &patch, true);
                self.observe_history_time_travel(patch.time_travel.as_ref());
                self.history_current_checkpoint_id = patch.current_checkpoint_id;
            }
            Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell read_history failed: {error}")),
        }
        self.conflicts_seeded = false;
        self.open_conflicts.clear();
        self.selected_conflict_id = None;
        #[cfg(not(target_arch = "wasm32"))]
        self.seed_open_conflicts().await;
    }

    /// 🧾️ ticket §C5 — folds an `InvocationResult.history_patch` (present on every `handleAction`/
    /// `handleCommand` response, per `🌉️ProgramBridge/🎯️targets/🧊️wgpu/🦀️.rs`'s `AppFrame::Invocation` decode)
    /// into the running projection, updates the idle clock, and — the instant a checkpoint THIS shell
    /// itself asked for (`checkpoint_dispatched`) is observed to have actually landed — fires
    /// `TouchArtifact` on the space index (§C5 item 6). Called from both `dispatch_action` and
    /// `dispatch_command` right after their own `program.handle_action`/`handle_command` call.
    ///
    /// 🪐️ `TouchArtifact` on the space index needs the native `ArtifactHost` document-sync
    /// backbone (it opens a second actor for the `s.space` index document). The browser build
    /// links no such host, so the checkpoint still lands and the projection still folds — only
    /// the index touch is skipped, and skipping it is visible in this one place.
    fn observe_invocation_history<'a>(&'a mut self, history_patch: Option<&'a semio_framework::kernel::HistoryPatch>) -> ShellTurn<'a, ()> {
        shell_turn(async move {
            let Some(patch) = history_patch else { return };
            if patch.cursor >= self.history_cursor {
                self.observe_history_time_travel(patch.time_travel.as_ref());
            }
            if !fold_history_patch(&mut self.history_entries, &mut self.history_cursor, patch, false) {
                return;
            }
            let count = uncommitted_edit_count(&self.history_entries);
            if count == 0 {
                self.last_uncommitted_edit_at_ms = None;
                self.auto_checkin_pending = false;
            } else {
                self.last_uncommitted_edit_at_ms = Some(chrome_now_ms() as i64);
            }
            let landed = checkpoint_landed(self.history_current_checkpoint_id.as_deref(), patch.current_checkpoint_id.as_deref(), self.checkpoint_dispatched);
            if patch.current_checkpoint_id.is_some() {
                self.history_current_checkpoint_id = patch.current_checkpoint_id.clone();
            }
            if !landed {
                return;
            }
            self.checkpoint_dispatched = false;
            #[cfg(not(target_arch = "wasm32"))]
            {
                let Some(space_id) = self.open_space_id.clone() else { return };
                let Some(document_id) = self.sync_channel.as_ref().map(|channel| channel.document_id.clone()) else { return };
                self.request_hub_check_in(&space_id, &document_id);
                if document_id != S_SPACE_INDEX_DOCUMENT_ID {
                    self.touch_space_index_artifact(&space_id, &document_id).await;
                }
            }
        })
    }

    /// 📌️ ticket §C5 item 2 — the per-frame auto check-in poll, called from `pump_sync_events` (see
    /// that method's own doc: "folded into the same every-frame pump"). Viewer sessions never arm
    /// (`can_check_in`, item 5's guard) — the SAME predicate the `#s-checkin` affordance itself checks.
    async fn poll_auto_checkin(&mut self) {
        let Some(session) = self.session.as_ref() else { return };
        if !can_check_in(session.app.role) {
            return;
        }
        let count = uncommitted_edit_count(&self.history_entries);
        if count == 0 {
            self.auto_checkin_pending = false;
            self.last_uncommitted_edit_at_ms = None;
            return;
        }
        let now_ms = chrome_now_ms() as i64;
        if auto_checkin_should_fire(count, self.auto_checkin_pending, self.last_uncommitted_edit_at_ms, now_ms, AUTO_CHECKIN_IDLE_MS, AUTO_CHECKIN_EDIT_THRESHOLD) {
            self.auto_checkin_pending = true;
            self.dispatch_checkpoint("auto").await;
        }
    }

    /// 📌️ ticket §C5 items 2/3/4 — fires `commitCheckpoint` through the same action funnel the
    /// History panel's own "Checkpoint" button uses (`history_command` in `🔌️plugin/🦀️.rs`),
    /// with `authors` riding along (`history_command` still hardcodes `authors: Vec::new()` today per
    /// `📓️w3-a-report.md`'s own `sharedFileRequest` — sent anyway so this is ready the moment that
    /// lands). Viewer-guarded (item 5) so a stray call from `checkpoint_before_detach`/`poll_auto_checkin`
    /// can never reach a viewer session even if their own callers' guards were ever relaxed.
    async fn dispatch_checkpoint(&mut self, message: &str) {
        let Some(session) = self.session.clone() else { return };
        if !can_check_in(session.app.role) {
            return;
        }
        self.checkpoint_dispatched = true;
        let authors: Vec<semio_framework::DslValue> = self.identity.as_ref().map(|identity| vec![semio_framework::dsl_value!({ "id": identity.user_id, "name": identity.display_name })]).unwrap_or_default();
        let action = ActionDescriptor { controller_id: session.app.controller_id.clone(), action: "commitCheckpoint".into(), args: crate::action_args_json!({ "message": message, "authors": authors }) };
        if let Err(error) = self.dispatch_action(action).await {
            Self::debug_log(&format!("[TRACE] wgpu shell check-in checkpoint dispatch failed: {error}"));
            self.checkpoint_dispatched = false;
        }
    }

    /// 📌️ ticket §C5 item 4 — checkpoint-on-close: called right before EVERY
    /// `detach_sync_backbone_internal()` call site (this shell keeps exactly one document mounted at a
    /// time, so attaching a different backbone IS closing whatever was open — same posture the React
    /// shell's own report documents). Best-effort (mirrors React's "fire-and-forget, not gated on the
    /// success-detection effect" note) — `dispatch_checkpoint`/`observe_invocation_history` still run
    /// the normal detection+`TouchArtifact` path; this call site just doesn't await or fail the caller
    /// on their outcome, since a failed close-time checkpoint must never block navigating away.
    async fn checkpoint_before_detach(&mut self) {
        let Some(session) = self.session.as_ref() else { return };
        let count = uncommitted_edit_count(&self.history_entries);
        if !should_checkpoint_before_detach(session.app.role, self.sync_channel.is_some(), count) {
            return;
        }
        self.dispatch_checkpoint("auto").await;
    }

    /// 📌️ ticket §C5 item 6 — `TouchArtifact` on the space's `index` document after a successful
    /// checkpoint, mirroring the React shell's `touchSpaceIndexArtifact`. Reuses the CURRENTLY visible
    /// session outright when it already IS this exact space's own index document (avoiding a second
    /// `document_host` actor under the shared, non-space-scoped `"index"` key entirely); otherwise
    /// spawns a FRESH, non-visible `s.space` editor instance + backbone attach for the duration of the
    /// one `touchArtifact` dispatch, then tears both down immediately. Unlike the React shell's cached
    /// background instance (`spaceIndexInstanceRef`), this does not cache across calls: `document_host`
    /// keys its actor registry by the bare document id, not `(spaceId, documentId)`, so a PERSISTENT
    /// background actor under `"index"` risks silently being replaced by a later legitimate
    /// `open_document`/`attach_sync_backbone` call for a DIFFERENT space's index (or vice versa) with
    /// no way for either side to detect the swap — spinning up fresh each time trades a little
    /// efficiency for provable correctness under that shared-key constraint.
    ///
    /// 🐚️ Reuse the live session outright when it's already this exact space's own index document.
    /// Calls `program.handle_command` DIRECTLY rather than `self.dispatch_command` (which would
    /// recurse back into `observe_invocation_history` → `touch_space_index_artifact` — `rustc`
    /// rightly refuses that as unbounded async recursion without `Box::pin`; a direct low-level
    /// call is also the more honest shape here, since `touchArtifact` requests no `Effect`s for
    /// `dispatch_command`'s own effect loop to process).
    ///
    /// 🐚️ `document_host` keys its actor registry by the bare document id ("index", not
    /// space-scoped) — opening a background actor under that key while the MAIN slot is ALSO
    /// showing "index" for a DIFFERENT space would silently sever that live session's own backbone
    /// (`ArtifactHost::open`'s own "idempotent per id" contract). Skip rather than risk it.
    #[cfg(not(target_arch = "wasm32"))]
    async fn touch_space_index_artifact(&mut self, space_id: &str, artifact_id: &str) {
        let now_ms = chrome_now_ms();
        let actor = self.identity.as_ref().map(|identity| identity.user_id.clone()).unwrap_or_else(|| self.shell_session_id.clone());
        let arguments: BTreeMap<String, DslValue> = BTreeMap::from([("id".to_string(), DslValue::String(artifact_id.to_string())), ("nowMs".to_string(), DslValue::float(now_ms)), ("actor".to_string(), DslValue::String(actor.clone()))]);
        if self.sync_channel.as_ref().map(|channel| channel.document_id.as_str()) == Some(S_SPACE_INDEX_DOCUMENT_ID) && self.open_space_id.as_deref() == Some(space_id) {
            let Some(session) = self.session.clone() else { return };
            let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id).cloned() else { return };
            let Some(app) = find_dialect_app(&program, &space_index_dialect(), semio_framework::manifest::AppRole::Editor).cloned() else { return };
            let invocation = semio_framework::manifest::CommandInvocation {
                address: semio_framework::manifest::CommandAddress { owner: semio_framework::manifest::CommandOwnerAddress::App { plugin_id: session.plugin_id.clone(), app_id: app.id.clone() }, command_id: "touchArtifact".into() },
                arguments,
            };
            let command_json = semio_framework_pack_json::to_json_string(&invocation);
            match program.handle_command(session.instance_id, &command_json, &session.view_state).await {
                Ok(result) => self.queue_host_effects(&session.app.controller_id, result.requested_effects),
                Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact (live session) failed: {error}")),
            }
            return;
        }
        if self.sync_channel.as_ref().map(|channel| channel.document_id.as_str()) == Some(S_SPACE_INDEX_DOCUMENT_ID) {
            Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact skipped: main session already holds the shared \"index\" actor for a different space"));
            return;
        }
        let Some(program) = self.plugins.iter().find(|entry| find_dialect_app(entry, &space_index_dialect(), semio_framework::manifest::AppRole::Editor).is_some()).cloned() else { return };
        let Some(app) = find_dialect_app(&program, &space_index_dialect(), semio_framework::manifest::AppRole::Editor).cloned() else { return };
        let instance_id = match program.create_app(&app.id).await {
            Ok(id) => id,
            Err(error) => {
                Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact background instance failed: {error}"));
                return;
            }
        };
        let data_dir = self.identity_env.as_ref().and_then(|env| env.data_dir.as_deref());
        let surface = semio_framework::manifest::surface_app_id(&app.dialect, semio_framework::manifest::AppRole::Editor);
        let bindings = default_persistence_bindings(self.identity.as_ref(), Some(space_id), data_dir, Some(surface.as_str()));
        let actor_uri = format!("actor://{S_SPACE_INDEX_DOCUMENT_ID}");
        if let Err(error) = bind_wgpu_document_socket_surface(&self.document_host, S_SPACE_INDEX_DOCUMENT_ID, S_SPACE_INDEX_DOCUMENT_SCHEMA, &bindings, &program, &app, &app.window_kinds.first().id) {
            Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact document admission failed: {error}"));
            program.destroy_app(instance_id);
            return;
        }
        let channels = self.document_host.open(ArtifactActorConfig { document_id: S_SPACE_INDEX_DOCUMENT_ID.to_string(), schema: S_SPACE_INDEX_DOCUMENT_SCHEMA.to_string(), bindings, watch_external: true, actor: actor.clone() }).await;
        let binding_generation = match self.mint_sync_binding_generation() {
            Ok(generation) => generation,
            Err(error) => {
                Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact binding generation failed: {error}"));
                self.document_host.close_key(&channels.document_key);
                program.destroy_app(instance_id);
                return;
            }
        };
        let binding_effects = match program.bind_document_backbone(instance_id, binding_generation, &actor_uri).await {
            Ok(effects) => effects,
            Err(error) => {
                let _ = program.retire_document_backbone(instance_id, binding_generation, &actor_uri).await;
                Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact document-backbone bind failed: {error}"));
                let _ = channels.cmd_tx.send(ArtifactActorMsg::Detach);
                self.document_host.close_key(&channels.document_key);
                program.destroy_app(instance_id);
                return;
            }
        };
        match route_document_backbone_effects(&actor_uri, &channels.cmd_tx, binding_effects) {
            Ok(remaining) => self.queue_host_effects(&app.controller_id, remaining),
            Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact document-backbone egress failed: {error}")),
        }
        let _ = channels.cmd_tx.send(ArtifactActorMsg::LocalMutations { envelopes: Vec::new() });
        let invocation = semio_framework::manifest::CommandInvocation {
            address: semio_framework::manifest::CommandAddress { owner: semio_framework::manifest::CommandOwnerAddress::App { plugin_id: program.plugin_id.clone(), app_id: app.id.clone() }, command_id: "touchArtifact".into() },
            arguments,
        };
        let command_json = semio_framework_pack_json::to_json_string(&invocation);
        let view_state = ViewModel::new(self.active_locale(), self.active_terminology());
        match program.handle_command(instance_id, &command_json, &view_state).await {
            Ok(result) => match route_document_backbone_effects(&actor_uri, &channels.cmd_tx, result.requested_effects) {
                Ok(remaining) => self.queue_host_effects(&app.controller_id, remaining),
                Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact document-backbone egress failed: {error}")),
            },
            Err(error) => Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact dispatch failed: {error}")),
        }
        if let Err(error) = program.retire_document_backbone(instance_id, binding_generation, &actor_uri).await {
            Self::debug_log(&format!("[TRACE] wgpu shell touchArtifact document-backbone retirement failed: {error}"));
        }
        let _ = channels.cmd_tx.send(ArtifactActorMsg::Detach);
        self.document_host.close_key(&channels.document_key);
        program.destroy_app(instance_id);
    }

    /// 📌️ ticket §C5 item 3 — explicit check-in's message-prompt dialog funnel (`#s-checkin`'s own
    /// dedicated controller, routed alongside `"framework.sync"` in `dispatch_action`): `open` shows
    /// the dialog, `cancel` closes it without dispatching, `submit` dispatches with the typed message
    /// (falling back to `"check-in"` for an empty/whitespace-only draft, matching the React shell's own
    /// `submitCheckin`).
    fn handle_checkin_action<'a>(&'a mut self, action: ActionDescriptor) -> ShellTurn<'a, Result<(), String>> {
        shell_turn(async move {
            match action.action.as_str() {
                "open" => {
                    self.checkin_dialog_draft = Some(String::new());
                    Ok(())
                }
                "cancel" => {
                    self.checkin_dialog_draft = None;
                    Ok(())
                }
                "submit" => {
                    let message = action.args.as_ref().and_then(|args| args.get("message")).and_then(DslValue::as_str).map(str::trim).filter(|value| !value.is_empty()).unwrap_or("check-in").to_string();
                    self.checkin_dialog_draft = None;
                    self.dispatch_checkpoint(&message).await;
                    Ok(())
                }
                _ => Ok(()),
            }
        })
    }

    /// 📌️ Arms one hub Check In of the mounted hub document; a running one for the same document is
    /// kept (its head is whatever the hub acknowledges once it is submitted).
    #[cfg(not(target_arch = "wasm32"))]
    fn request_hub_check_in(&mut self, space_id: &str, document_id: &str) {
        if self.hub_check_in.as_ref().is_some_and(|current| !current.status.as_ref().is_some_and(|status| status.phase.is_terminal()) && current.space_id == space_id && current.document_id == document_id) {
            return;
        }
        let now_ms = Self::directory_now_ms();
        self.hub_check_in = Some(ShellHubCheckInV1 {
            space_id: space_id.to_string(),
            document_id: document_id.to_string(),
            request_id: mint_directory_command_request_id(),
            head: None,
            quiescent_by_ms: now_ms.saturating_add(HUB_CHECK_IN_QUIESCENCE_MS),
            deadline_at_ms: now_ms.saturating_add(HUB_CHECK_IN_DEADLINE_MS),
            next_poll_at_ms: now_ms,
            submitted: false,
            cancel_requested: false,
            cancel_sent: false,
            status: None,
        });
    }

    /// 📌️ Drives the Check In by at most one bounded hub request per frame: waits (bounded) for the
    /// document's sync status to name an acknowledged head, submits it, then polls or cancels to a
    /// terminal status. Answers whether the footer's status changed.
    #[cfg(not(target_arch = "wasm32"))]
    async fn pump_hub_check_in(&mut self) -> bool {
        use semio_framework_os_kernel::os_directory::{DocumentCheckInPhaseV1, DocumentCheckInRefusalV1, DocumentCheckInV1, DOCUMENT_CHECK_IN_SCHEMA_V1};
        let Some(operation) = self.hub_check_in.clone() else { return false };
        if operation.status.as_ref().is_some_and(|status| status.phase.is_terminal()) {
            return false;
        }
        let now_ms = Self::directory_now_ms();
        let local_refusal = |refusal| Some(hub_check_in_local_status(&operation.request_id, DocumentCheckInPhaseV1::Failed, Some(refusal)));
        let Some(client) = self.directory_client.clone() else {
            self.hub_check_in.as_mut().expect("armed check-in").status = local_refusal(DocumentCheckInRefusalV1::AuthorityChanged);
            return true;
        };
        if now_ms >= operation.deadline_at_ms {
            self.hub_check_in.as_mut().expect("armed check-in").status = local_refusal(DocumentCheckInRefusalV1::Unavailable);
            return true;
        }
        let mounted = self.sync_channel.as_ref().is_some_and(|channel| channel.document_id == operation.document_id) && self.open_space_id.as_deref() == Some(operation.space_id.as_str());
        let Some(head) = operation.head.clone() else {
            if !mounted || now_ms >= operation.quiescent_by_ms {
                self.hub_check_in.as_mut().expect("armed check-in").status = local_refusal(DocumentCheckInRefusalV1::Unavailable);
                return true;
            }
            let Some(head) = self.sync_status.as_ref().and_then(|status| status.acknowledged_head.clone()).filter(|head| head.document_id == operation.document_id) else { return false };
            let current = self.hub_check_in.as_mut().expect("armed check-in");
            current.head = Some(head);
            current.status = Some(hub_check_in_local_status(&current.request_id, DocumentCheckInPhaseV1::Accepted, None));
            return true;
        };
        let cancel_due = operation.cancel_requested && !operation.cancel_sent;
        if operation.submitted && !cancel_due && now_ms < operation.next_poll_at_ms {
            return false;
        }
        let context = self.directory_command_ctx();
        let answer = if !operation.submitted {
            let request = DocumentCheckInV1 { schema: DOCUMENT_CHECK_IN_SCHEMA_V1.to_string(), request_id: operation.request_id.clone(), head };
            client.document_check_in(&context, &operation.space_id, &request).await
        } else if cancel_due {
            client.cancel_document_check_in(&context, &operation.space_id, &operation.document_id, &operation.request_id).await
        } else {
            client.document_check_in_status(&context, &operation.space_id, &operation.document_id, &operation.request_id).await
        };
        let Some(current) = self.hub_check_in.as_mut().filter(|current| current.request_id == operation.request_id) else { return false };
        current.next_poll_at_ms = Self::directory_now_ms().saturating_add(HUB_CHECK_IN_POLL_MS);
        current.submitted = true;
        current.cancel_sent |= cancel_due;
        match answer {
            Ok(status) => current.status = Some(status),
            Err(DirectoryClientError::Unauthorized) | Err(DirectoryClientError::Http { status: 403, .. }) => {
                current.status = Some(hub_check_in_local_status(&current.request_id, DocumentCheckInPhaseV1::Failed, Some(DocumentCheckInRefusalV1::AuthorityChanged)))
            }
            Err(DirectoryClientError::Http { status, .. }) if (400..500).contains(&status) => current.status = Some(hub_check_in_local_status(&current.request_id, DocumentCheckInPhaseV1::Failed, Some(DocumentCheckInRefusalV1::Unavailable))),
            Err(_) => {}
        }
        true
    }

    /// 📌️ The footer's hub badge, followed by the current Check In's status while one is shown.
    fn hub_footer_label(&self) -> String {
        let is_de = self.locale_id == "de";
        let hub = shell_hub_connection_text(self.hub_connection_state(), is_de);
        #[cfg(not(target_arch = "wasm32"))]
        if let Some(status) = self.hub_check_in.as_ref().and_then(|operation| operation.status.as_ref()) {
            return format!("{hub} · {}", hub_check_in_status_text(status, is_de));
        }
        hub
    }
    //#endregion 🔖️CheckIn

    /// 🔗️ The sync card's manual attach: parses the card's uri into bindings and opens the
    /// session's own document through the ONE [`Self::open_document`] body, so the card and the
    /// `os.open-artifact` relay cannot drift into two attach sequences (the React shell's
    /// `openDocument` is the TS twin of that body).
    ///
    /// 🌐️ A `remote://` uri names the hub document itself — host, space AND document
    /// ([`parse_remote_backbone_uri`]) — and binds the session app's own canonical surface, so two
    /// shells attaching the same uri open the same hub document (the React shell's C1c fix).
    ///
    /// 🪪️ A folder or file attach addresses the program's OWN document identity — the id its store stamps on every
    /// envelope — so the actor admits the program's edits as its own document's instead of refusing each batch as another
    /// document's (`local.backbone-scope-mismatch`), React's `openSyncTarget`. A program holding no document is told so.
    /// A folder attach is remembered for this device (`os.config.local-folders`) and, natively, the folder's archive is
    /// restored into the program like a fresh load.
    async fn attach_sync_backbone(&mut self, uri: String) -> Result<(), String> {
        let session = self.session.clone().ok_or("session missing")?;
        let (document_id, bindings, surface) = match parse_remote_backbone_uri(&uri) {
            Some(remote) => {
                let surface = semio_framework::manifest::surface_app_id(&session.app.dialect, session.app.role);
                (remote.document_id, vec![PersistenceBinding::Hub { base_url: format!("http://{}", remote.host_port), space_id: remote.space_id, surface: Some(surface.clone()) }], Some(surface))
            }
            None => {
                let Some(identity) = self.sync_program_identity() else {
                    let text = local_folders::local_folder_text(local_folders::LocalFolderText::Unidentified, "", self.active_locale());
                    self.show_transient_notice(text, semio_framework::Severity::Warning, Some(local_folders::SYNC_DOCUMENT_UNIDENTIFIED_CODE));
                    return Ok(());
                };
                #[cfg(target_arch = "wasm32")]
                if !SHELL_DOCUMENT_TRANSPORTS.folder && local_folders::is_host_route_uri(&uri) {
                    return self.attach_host_route_backbone(uri, identity).await;
                }
                (identity.document_id, Self::parse_persistence_binding(&uri)?, None)
            }
        };
        let folder = bindings.iter().find_map(|binding| match binding {
            PersistenceBinding::Folder { path } => Some(path.display().to_string()),
            PersistenceBinding::Hub { .. } => None,
        });
        self.open_document(document_id.clone(), session.app.io.artifact_schema.clone(), bindings, surface, Some(uri)).await?;
        let Some(path) = folder else { return Ok(()) };
        self.ensure_local_folder_bindings();
        self.remember_local_folder(semio_framework_os_config::opening_config::mutations::LocalFolderBinding {
            document_id: document_id.clone(),
            plugin_id: session.plugin_id.clone(),
            app_id: session.app.id.clone(),
            folder: semio_framework_os_config::opening_config::mutations::LocalFolderRef::Path { path: path.clone() },
        });
        #[cfg(not(target_arch = "wasm32"))]
        self.restore_folder_archive(&path, &document_id).await?;
        Ok(())
    }

    /// 📇️ ticket §2/§C6 — opens an explicit document id/schema on the same `framework/sync`
    /// `ArtifactHost` sequence `attach_sync_backbone` uses, but with caller-supplied bindings (task
    /// 2's default-binding computation, or an explicit override) instead of parsing a manual sync-
    /// card uri — independent of `attach_sync_backbone`, which stays the untouched `remote://`
    /// override path. Used by the `os.open-artifact{documentId}` opening relay (§4), by the sync
    /// card's manual attach (`backbone_uri` names what the card shows) and by the identity-driven
    /// space-index auto-bind on the `/spaces/{id}` route (§6). One body on both targets: the only
    /// platform split is [`document_bindings_admitted`], refused before any actor exists.
    ///
    /// 🪢️ A hub document's guest opens on the hub's canonical checkpoint pair ([`seed_hub_document`]) before its
    /// document actor exists, and the actor starts at the same pair ([`Self::install_document_seed`]), so every
    /// mutation it authors names the document it opened and its first Hello asks the hub only for what followed the
    /// pair (ticket 26/09/23: slice WG8 gate run 12 measured the identity-less guest; slice WG10 made the pair the
    /// one seed of every shell).
    async fn open_document(&mut self, document_id: String, schema: String, bindings: Vec<PersistenceBinding>, surface: Option<String>, backbone_uri: Option<String>) -> Result<(), String> {
        let prepared = self.prepare_document_open(document_id, schema, bindings, surface, backbone_uri, None).await?;
        let pair = seed_hub_document(prepared.plugin.clone(), prepared.session.instance_id, prepared.seed.clone()).await?;
        self.install_document_seed(&prepared, pair)?;
        self.finish_document_open(prepared).await?;
        self.refresh_ui(UiDirtyScope::Full).await
    }

    /// 🪢️ Hands the document's actor the canonical pair its guest was seeded from; nothing for a document bound to
    /// no hub.
    fn install_document_seed(&self, prepared: &ShellPreparedDocumentOpen, pair: Option<semio_framework_os_kernel::os_directory::CanonicalCheckpointPairV1>) -> Result<(), String> {
        let (Some(pair), Some(seed)) = (pair, prepared.seed.as_ref()) else { return Ok(()) };
        if !self.document_host.set_document_seed(&ArtifactDocumentKey::hub(seed.scope.space_id.clone(), seed.scope.document_id.clone()), pair) {
            return Err("the canonical checkpoint pair could not be handed to the document actor".into());
        }
        Ok(())
    }

    /// 🧷️ The host half of an open, before the guest holds the document: the mounted document is
    /// checkpointed and retired, the socket surface and the execution target bound.
    ///
    /// 🎠️ H3-wgpu-native — `wasm_runtime()`/`register_host_backbone` retired, see
    /// `detach_sync_backbone_internal`'s note.
    /// 📌️ ticket §C5 item 4 — checkpoint-on-close, same "switch away IS close" posture as
    /// `attach_sync_backbone` above (this shell keeps exactly one document mounted at a time).
    async fn prepare_document_open(
        &mut self,
        document_id: String,
        schema: String,
        bindings: Vec<PersistenceBinding>,
        surface: Option<String>,
        backbone_uri: Option<String>,
        checkpoint: Option<semio_framework_os_kernel::os_directory::DocumentOpenCheckpointV1>,
    ) -> Result<ShellPreparedDocumentOpen, String> {
        document_bindings_admitted(SHELL_DOCUMENT_TRANSPORTS, &bindings)?;
        let session = self.session.clone().ok_or("session missing")?;
        let plugin = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id).cloned().ok_or("plugin missing")?;
        let window_id = self.active_window_id.as_deref().or(session.view_state.window_id.as_deref()).unwrap_or_else(|| session.app.window_kinds.first().id.as_str());
        let window_kind_id = self.live_window_kind_id(&session, window_id).unwrap_or_else(|| session.app.window_kinds.first().id.as_str()).to_string();
        self.checkpoint_before_detach().await;
        self.detach_sync_backbone_internal().await?;
        self.presence_surface = surface;
        bind_wgpu_document_socket_surface(&self.document_host, &document_id, &schema, &bindings, &plugin, &session.app, &window_kind_id)?;
        let seed = self.bind_document_execution_target(&document_id, &schema, &bindings, &plugin, &session.app, &window_kind_id, checkpoint).await?;
        Ok(ShellPreparedDocumentOpen { document_id, schema, bindings, backbone_uri, seed, plugin, session })
    }

    /// 🔗️ Binds the prepared document once the guest holds it: the document actor opens, the guest's
    /// backbone binds to it and the history projection re-seeds. The caller owes the refresh.
    async fn finish_document_open(&mut self, prepared: ShellPreparedDocumentOpen) -> Result<(), String> {
        let ShellPreparedDocumentOpen { document_id, schema, bindings, backbone_uri, plugin, session, .. } = prepared;
        let actor_uri = format!("actor://{document_id}");
        let actor = self.current_shell_actor(session.instance_id);
        let channels = self.document_host.open(ArtifactActorConfig { document_id: document_id.clone(), schema, bindings, watch_external: true, actor }).await;
        let events = self.document_host.subscribe_key(&channels.document_key).await;
        let binding_generation = self.mint_sync_binding_generation()?;
        let binding_effects = match plugin.bind_document_backbone(session.instance_id, binding_generation, &actor_uri).await {
            Ok(effects) => effects,
            Err(error) => {
                let _ = plugin.retire_document_backbone(session.instance_id, binding_generation, &actor_uri).await;
                let _ = channels.cmd_tx.send(ArtifactActorMsg::Detach);
                self.document_host.close_key(&channels.document_key);
                return Err(format!("plugin document-backbone bind: {error}"));
            }
        };
        let cmd_tx = channels.cmd_tx.clone();
        let _ = cmd_tx.send(ArtifactActorMsg::LocalMutations { envelopes: Vec::new() });
        self.sync_link = DocumentLinkStatus::Linked;
        self.sync_backbone_uri = Some(backbone_uri.unwrap_or_else(|| actor_uri.clone()));
        self.sync_channel =
            Some(ShellSyncChannel { document_id, document_key: channels.document_key, actor_uri, instance_id: session.instance_id, plugin_id: session.plugin_id.clone(), binding_generation, cmd_tx, events, connected_at_ms: chrome_now_ms() as i64 });
        let channel = self.sync_channel.as_ref().expect("new sync channel is installed");
        let remaining = match route_document_backbone_effects(&channel.actor_uri, &channel.cmd_tx, binding_effects) {
            Ok(remaining) => remaining,
            Err(error) => {
                let _ = self.detach_sync_backbone_internal().await;
                return Err(error);
            }
        };
        self.queue_host_effects(&session.app.controller_id, remaining);
        if let Some(error) = self.sync_terminal_fault.take() {
            let _ = self.detach_sync_backbone_internal().await;
            return Err(error);
        }
        self.sync_status = Some(ArtifactSyncStatus::default());
        if let Some(document_key) = self.sync_channel.as_ref().map(|channel| shell_hub_document_key(&channel.document_key)) {
            self.publish_hub_document_status(document_key, ShellHubRemoteV1::Detached);
        }
        self.sync_card_kind = None;
        self.refresh_history_snapshot().await;
        Ok(())
    }

    /// 🪪️ A hub document's execution-target lease for the exact scope and the surface this shell requests: its
    /// `checkpoint` is what the document's canonical pair must be ([`ShellHubDocumentSeed`]), and for a kind this
    /// process resolves no codec for (neither linked nor a mounted component's,
    /// [`store_sync::os_store::document_kind_codec`]) it is also the kind identity, bound onto the document host
    /// only when it names the package this shell mounted ([`document_execution_target_admitted`]). A hub
    /// resolution that already read the lease hands its `checkpoint` in, and a kind that resolves a codec then
    /// needs no second read. A document with no hub binding has no seed. Both targets walk this one body.
    #[allow(clippy::too_many_arguments)]
    async fn bind_document_execution_target(
        &mut self,
        document_id: &str,
        schema: &str,
        bindings: &[PersistenceBinding],
        program: &ProgramBridgeEntry,
        app: &AppDefinition,
        window_kind_id: &str,
        checkpoint: Option<semio_framework_os_kernel::os_directory::DocumentOpenCheckpointV1>,
    ) -> Result<Option<ShellHubDocumentSeed>, String> {
        let Some(space_id) = bindings.iter().find_map(|binding| match binding {
            PersistenceBinding::Hub { space_id, .. } => Some(space_id.clone()),
            PersistenceBinding::Folder { .. } => None,
        }) else {
            return Ok(None);
        };
        let client = self.directory_client.clone().ok_or("document open requires a signed-in hub session")?;
        let scope = semio_framework_os_kernel::os_directory::DocumentScope::new(space_id.as_str(), document_id);
        let codec_resolves = store_sync::os_store::document_kind_codec(schema).await.map_err(|error| format!("document codec registry: {error}"))?.is_some();
        let surface_id = wgpu_document_socket_surface(program, app, window_kind_id)?;
        let intent = semio_framework_os_kernel::os_directory::DocumentOpenIntentV1 {
            schema: "semio.hub.document-open-intent/v1".into(),
            version: 1,
            scope: semio_framework_os_kernel::os_directory::DocumentScope::new(space_id.as_str(), document_id),
            requested_surface_id: Some(surface_id.clone()),
            client_instance_id: format!("wgpu-shell-{}", self.shell_session_id),
        };
        let lease = client.document_execution_target_manifest(&self.directory_command_ctx(), &intent).await.map_err(|error| format!("document execution target: {error}"))?;
        let checkpoint = lease.checkpoint.clone();
        document_execution_target_admitted(&lease, &program.plugin_id, program.package_id.as_deref(), program.component_sha256.as_deref(), schema, &surface_id)?;
        #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.document_execution_target_lease=Some(lease.clone());
        if !codec_resolves {
            document_execution_target_admitted(&lease, &program.plugin_id, program.package_id.as_deref(), program.component_sha256.as_deref(), schema, &surface_id)?;
            if !self.document_host.set_document_execution_target_lease(&ArtifactDocumentKey::hub(space_id, document_id), lease) {
                return Err("document execution target is already bound for this document".into());
            }
        }
        Ok(Some(ShellHubDocumentSeed { client, ctx: self.directory_ctx(), scope, checkpoint }))
    }

    /// 📇️ Default bindings for a document opened against the CURRENTLY mounted session's own
    /// dialect/role — `default_persistence_bindings`'s pure decision, fed the live identity/space/
    /// data-dir/surface this shell already holds.
    fn default_bindings_for_current_session(&self) -> (Vec<PersistenceBinding>, Option<String>) {
        let space_id = self.open_space_id.clone();
        let data_dir = self.identity_env.as_ref().and_then(|env| env.data_dir.as_deref());
        let surface = self.session.as_ref().filter(|_| self.identity.is_some() && space_id.is_some()).map(|session| semio_framework::manifest::surface_app_id(&session.app.dialect, session.app.role));
        let bindings = default_persistence_bindings(self.identity.as_ref(), space_id.as_deref(), data_dir, surface.as_deref());
        (bindings, surface)
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn schedule_sync_path_pick(&mut self, pick: impl std::future::Future<Output = Option<String>> + Send + 'static) {
        self.submit_shell_io_future(async move {
            let Some(path) = pick.await else { return ShellIoCompletion::Finished };
            ShellIoCompletion::Actions(vec![ActionDescriptor { controller_id: "framework.sync".into(), action: "setSyncDraft".into(), args: Some(semio_framework::dsl_value!({ "path": path })) }])
        });
    }

    /// 📌️ ticket §C5 item 4 — the one EXPLICIT close (a user-initiated "Detach"), same
    /// checkpoint-before-detach guard as the two switch-triggered closes above.
    fn handle_sync_action<'a>(&'a mut self, action: ActionDescriptor) -> ShellTurn<'a, Result<(), String>> {

        shell_turn(async move {
            match action.action.as_str() {
                "selectFile" => {
                    self.sync_card_kind = Some("file".into());
                    self.sync_card_draft = self.sync_backbone_uri.as_deref().filter(|uri| uri.starts_with("file://")).map(|uri| uri.trim_start_matches("file://").to_string()).unwrap_or_default();
                    #[cfg(not(target_arch = "wasm32"))]
                    self.schedule_sync_path_pick(pick_file_path());
                    #[cfg(target_arch = "wasm32")]
                    if let Some(path) = pick_file_path().await {
                        self.sync_card_draft = path;
                    }
                    Ok(())
                }
                "selectFolder" => {
                    self.sync_card_kind = Some("folder".into());
                    self.sync_card_draft = self.sync_backbone_uri.as_deref().filter(|uri| uri.starts_with("folder://")).map(|uri| uri.trim_start_matches("folder://").to_string()).unwrap_or_default();
                    #[cfg(not(target_arch = "wasm32"))]
                    self.schedule_sync_path_pick(pick_folder());
                    #[cfg(target_arch = "wasm32")]
                    if let Some(path) = pick_folder().await {
                        self.sync_card_draft = path;
                    }
                    Ok(())
                }
                "browse" => match self.sync_card_kind.as_deref() {
                    Some("folder") => {
                        #[cfg(not(target_arch = "wasm32"))]
                        self.schedule_sync_path_pick(pick_folder());
                        #[cfg(target_arch = "wasm32")]
                        if let Some(path) = pick_folder().await {
                            self.sync_card_draft = path;
                        }
                        Ok(())
                    }
                    Some("file") => {
                        #[cfg(not(target_arch = "wasm32"))]
                        self.schedule_sync_path_pick(pick_file_path());
                        #[cfg(target_arch = "wasm32")]
                        if let Some(path) = pick_file_path().await {
                            self.sync_card_draft = path;
                        }
                        Ok(())
                    }
                    _ => Ok(()),
                },
                "setSyncDraft" => {
                    if let Some(path) = action.args.as_ref().and_then(|args| args.get("path").or_else(|| args.get("value"))).and_then(|value| value.as_str()) {
                        self.sync_card_draft = path.to_string();
                    }
                    Ok(())
                }
                "selectRemote" => {
                    self.sync_card_kind = Some("remote".into());
                    self.sync_card_draft = self.sync_backbone_uri.as_deref().filter(|uri| uri.starts_with("remote://")).map(|uri| uri.trim_start_matches("remote://").to_string()).unwrap_or_default();
                    Ok(())
                }
                "attach" => {
                    let path = action.args.as_ref().and_then(|args| args.get("path")).and_then(|value| value.as_str()).unwrap_or(self.sync_card_draft.as_str());
                    if path.trim().is_empty() {
                        return Ok(());
                    }
                    let kind = action.args.as_ref().and_then(|args| args.get("kind")).and_then(|value| value.as_str()).unwrap_or(self.sync_card_kind.as_deref().unwrap_or("file"));
                    let uri = match kind {
                        "folder" => format!("folder://{path}"),
                        "remote" => format!("remote://{path}"),
                        _ => format!("file://{path}"),
                    };
                    self.attach_sync_backbone(uri).await
                }
                "detach" => {
                    #[cfg(target_arch = "wasm32")]
                    if self.detach_host_route_folder().await {
                        return Ok(());
                    }
                    let folder_document = self.sync_backbone_uri.as_deref().filter(|uri| uri.starts_with("folder://") || uri.starts_with("file://")).and_then(|_| self.sync_channel.as_ref()).map(|channel| channel.document_id.clone());
                    self.checkpoint_before_detach().await;
                    self.detach_sync_backbone_internal().await?;
                    self.sync_backbone_uri = None;
                    self.sync_card_kind = None;
                    self.last_envelope_dsl = None;
                    if let Some(document_id) = folder_document {
                        self.ensure_local_folder_bindings();
                        self.forget_local_folder(&document_id);
                    }
                    Ok(())
                }
                local_folders::FOLDER_RECONNECT_ACTION => {
                    self.ensure_local_folder_bindings();
                    let Some(offer) = self.folder_reconnect_offer() else { return Ok(()) };
                    if let Err(error) = self.reattach_local_folder(&offer).await {
                        self.note_dispatch_fault(&error);
                    }
                    Ok(())
                }
                local_folders::FOLDER_FORGET_ACTION => {
                    self.ensure_local_folder_bindings();
                    if let Some(offer) = self.folder_reconnect_offer() {
                        self.forget_local_folder(&offer.document_id);
                    }
                    Ok(())
                }
                _ => Ok(()),
            }

        })

    }

    /** 🪪️ One action a live ENGINE SURFACE derived from raw pointer/wheel input — the world pane's
     * hover, pick, navigation note and camera report, the board's and the map's twins. Identical to
     * [`Self::dispatch_action`] except for the provenance the chrome ledger records, which is what
     * separates a gesture stream from a control press on both renderers. */
    pub async fn dispatch_gesture_action(&mut self, action: ActionDescriptor) -> Result<(), String> {
        self.dispatch_origin = SHELL_DISPATCH_ORIGIN_GESTURE;
        let outcome = self.dispatch_action(action).await;
        self.dispatch_origin = SHELL_DISPATCH_ORIGIN_USER;
        outcome
    }

    /// 🎯️ The chrome ledger's one tap: this fn is the single funnel EVERY input's action crosses, so
    /// recording here is the target's complete answer to "what did that click do"
    /// (`crate::interpreter`'s 🎯️ChromeLedger, diagnostics-gated and bounded).
    ///
    /// 🎬️ Tutorial playback remains shell-local. Recording is armed only after the plugin's shared
    /// retained `recordTutorial` route accepts and commits below.
    ///
    /// 🎬️ Deviation detection + recorder tap — every OTHER real dispatch funnels through here exactly
    /// once, before any of this function's own side effects, and skips itself while the tutorial
    /// player's own history-action replay is mid-flight (`tutorial_flush_pending_document_ops`'s
    /// `TutorialDispatchGuard`).
    ///
    /// 🔁️ An `Effect::DispatchAction` whose id is an APP COMMAND crosses as a command, never as an
    /// action — React's `makeEffectDispatchOne` picks `handleCommand` on exactly this predicate
    /// (`🛠️ShellHelpers/🟦️.tsx`, `isAppCommand`). The guest's re-arm chain is `flowEvalTick`, an
    /// app command with no action route at all, so sending it as an `ActionInvocation` faulted the
    /// whole dispatch and — through `flush_deferred_actions` — the boot
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    ///
    /// 🎨️ Backs `build_settings_theme_ui`'s theme select/reset/delete in the owned build
    /// snapshot and mirrors the value to the present-side bridge consumed by `frame()`.
    ///
    /// 🎨️ React drops the draft on every selection change (`setThemeId` dispatches
    /// `SET_UI_THEME_DRAFT: null` first) — otherwise the previous theme's unsaved
    /// edits would follow the user onto the newly picked one.
    ///
    /// 🎛️ The bottom-middle Commands panel's zero-arg rows: every os command that carries no
    /// argument fires straight through `apply_os_command`, the same entry point the ⌘️K
    /// search's `"os-command:"` redirect uses — so `os.resetDock` is reachable from the dock
    /// panel itself now, matching React's always-fireable command rows.
    ///
    /// ⚙️ The Settings General leaf's layout row — React's `setLayout` + its
    /// `os.setLayout` history note.
    ///
    /// 👁️✏️ The Default Apps leaf's per-(dialect × role) pin — `"none"` clears it, React's
    /// `clearDefault`/`setDefault` pair over one `Select`.
    ///
    /// ⌨️ Arms (or disarms) chord capture for one shortcut row — the next key event becomes
    /// that row's override instead of a shell verb.
    ///
    /// ⌨️ Drops one row's override, which restores its `SHELL_SHORTCUT_ROWS` default —
    /// React's `resetKeybindingOverride`, whose fold is a `delete` on the override map.
    ///
    /// 🎛️ A command row with arguments owns expansion only. The stable key is re-resolved
    /// against the current palette on every click so an old mode/session cannot open a stale form.
    ///
    /// 🎛️ A zero-argument tree row executes through the same resolved-command authority as
    /// staged forms. The opaque owner-qualified key is never parsed into an invocation.
    ///
    /// 📝️ Buffers one staged command argument — React's `STAGE_COMMAND_ARG`, which writes
    /// only to the buffer and dispatches nothing.
    ///
    /// 🎛️ Execute of the staged form — the one place the buffered arguments leave the buffer,
    /// React's `onExecute(expanded, effective)`.
    ///
    /// 🎛️ `apply_os_command` takes the ONE option value every os command
    /// carries (React's own single-`value` shape), so the staged form's
    /// first argument is what it receives.
    ///
    /// 📇️ The per-window Actions pane's own four verbs — React's `SET_ACTION_PANE_EXPANDED`,
    /// `STAGE_ACTION_ARG`, `RESET_ACTION_ARGS` and `onExecute` (`windowActionPaneNode`,
    /// `🛠️ShellHelpers/🟦️.tsx:4221`). Only the last one dispatches anything to the app.
    ///
    /// 🔎️ The per-window Search pane's own two local verbs — the typed line's buffer and the
    /// possibles chevron. React keeps both in the `Search` component's own state.
    ///
    /// 🔀️ One retained Projection Tree row. Both pointer Activate and Enter/Space emit
    /// this exact action, so the camera, selected row, icon, title and AX snapshot advance
    /// through one accepted per-window boundary.
    ///
    /// 💬️ The chat panel's own two verbs — React's composer `setDraft`/`submit`. There is no
    /// clear verb: the feed is live bridge state, not a local buffer a shell may discard.
    /// 🖥️ The two Display leaves' own verbs — React's `DisplayHostApi`
    /// (`📌️ChromePanels/🟦️.tsx`): the save-name box, Save current layout, apply and delete.
    ///
    /// 🖥️ React's `NamedLayoutStore::save` persists on the same call that mutates its
    /// roster — a layout saved and not written would be gone on the next boot.
    ///
    /// 🖥️ React's `NamedLayoutStore::remove` persists the shortened roster too.
    ///
    /// 🖥️ One Display "Windows" row — React drags this payload onto the dock; with no panel
    /// drag lane here the press opens the window directly, carrying the same
    /// `{windowKindId, templateId}` the drag would have.
    ///
    /// ⚔️ The Conflicts leaf's two verbs — React's `onSelect`/`onResolve`.
    ///
    /// 🛍️ The Marketplace leaf's three verbs — React's
    /// `installPlugin`/`reloadPlugin`/`uninstallPlugin`.
    ///
    /// 🔐️ Slice WG6: every `hub*` verb the hub workspace names goes through ONE lane, so
    /// this dispatch carries one arm rather than eighteen and the surface's vocabulary and
    /// the shell's cannot drift apart.
    ///
    /// ⚖️ React's `setMergePolicy` — local authority state, never wire-carried, so it moves
    /// no document and notes no history entry beyond the shell setting itself.
    ///
    /// 🎨️ The eight theme-editor verbs — React's `setThemeColor`/`setThemeSpacing`/
    /// `setThemeFontStack`/`setThemeStroke`/`setThemeRadius`/`setThemeOpacity`/
    /// `setThemeMetric`/`setThemeAppearancePaint`, each a `draftThemePatch` over the SAME
    /// document. The key rides the row's authored args (merged with the committed value by
    /// `merge_committed_args`), where React's closure captured it.
    ///
    /// 💾️ React's `saveTheme(label)`: slug the trimmed name, store the canonical document
    /// under `custom.<slug>`, select it, and drop the draft.
    ///
    /// ⬇️ React's `exportTheme`: `downloadMediaExport(`${id}.theme.dsl`, "text/plain",
    /// serializeUiTheme(theme))` — the same filename, mime and canonical 2-space JSON.
    ///
    /// ⬆️ React's `importTheme`: `requestFileOpen(".theme.dsl,.dsl,text/plain")`, parse,
    /// then save under the parsed label. The picker is user-activation gated, so it parks
    /// for the gesture lane rather than opening from this async funnel.
    ///
    /// ⬆️ The picked file's text, parsed and saved — React's
    /// `saveTheme(parsed.label || parsed.id)`. An invalid file is ignored, exactly as
    /// React's `catch {}` ignores it.
    ///
    /// 📌️ ticket §C5 item 3 — explicit check-in's own dedicated controller (`#s-checkin`'s
    /// open/cancel/submit dialog funnel), same shell-owned-chrome treatment as `framework.sync`
    /// above.
    ///
    /// 🧰️ Intercept the framework `setActiveUtility` View action to update the host-owned active-utility
    /// map before forwarding to the plugin (which reacts by clearing its live-preview scratch). The
    /// authoritative state is the shell map + the `ViewModel.active_utility_id` it injects on render.
    ///
    /// 🧾️ ticket §C5 — fold this dispatch's own `history_patch` into the check-in projection (idle
    /// clock, checkpoint-landed detection + `TouchArtifact`) before anything else touches `self`.
    ///
    /// 🎓️ Advance-by-doing: this action was actually performed (the plugin call above succeeded), so
    /// a tour step whose `advance` targets it moves on now — see `chrome_tour_note_action_performed`.
    ///
    /// 🧾️ ONE host-effect funnel, byte for byte the fold `dispatch_command` performs. This arm used
    /// to be a SECOND, shorter, hand-rolled match ending in `_ => {}`, and every effect it did not
    /// name was dropped WITHOUT A TRACE — not even the funnel's own `effect dropped` line. That is
    /// how `Export Document…` ended: the guest ran it, answered `DownloadMediaExport`, the bridge
    /// handed it back as `requested_effects`, and this silent arm threw it away, so no plugin could
    /// export anything through an ACTION on this renderer while the command path exported fine
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️wgpu-end-to-end-verification-2026-09-14.md` §C).
    /// Only the two effects `queue_host_effects` cannot own stay here — a `Navigate` that must also
    /// RESOLVE the uri, and the replay relay — because both are `async` and that funnel is
    /// deliberately a plain `fn`.
    pub fn dispatch_action<'a>(&'a mut self, mut action: ActionDescriptor) -> ShellTurn<'a, Result<(), String>> {

        shell_turn(async move {
            if let Some(owner) = action.args.as_ref().and_then(|args| args.get("windowId")).and_then(DslValue::as_str).and_then(window_pane_owner).map(str::to_string) {
                scope_action_to_window(&mut action, &owner);
            }
            crate::interpreter::note_dispatched_action(&action, self.dispatch_origin);
            if action.action == semio_framework::START_TUTORIAL_ACTION_ID {
                if let Some(tutorial_id) = action.args.as_ref().and_then(|args| args.get("tutorialId")).and_then(|v| v.as_str()) {
                    self.tutorial_start(tutorial_id);
                }
                return Ok(());
            }
            let record_tutorial_after_acceptance = action.action == semio_framework::RECORD_TUTORIAL_ACTION_ID;
            if !self.chrome_build.tutorial_dispatch_internal {
                self.tutorial_note_real_dispatch(&action);
            }
            if let Some(result) = self.apply_host_panel_selection(&action) {
                return result;
            }
            if !record_tutorial_after_acceptance && action.controller_id != "framework" {
                if let Some(session) = self.action_session(&action).cloned() {
                    if Self::app_owns_command(&session.app, &action.action) {
                        if action.args.as_ref().and_then(|args| args.get("windowId")).and_then(DslValue::as_str) == Some("spawned") {
                            if let Some(id) = session.view_state.window_id.as_deref() { scope_action_to_window(&mut action, id); }
                        }
                        let arguments = action.args.as_ref().and_then(DslValue::as_object).map(|entries| entries.iter().cloned().collect()).unwrap_or_default();
                        return self
                            .dispatch_session_command(semio_framework::manifest::CommandInvocation {
                                address: semio_framework::manifest::CommandAddress { owner: semio_framework::manifest::CommandOwnerAddress::App { plugin_id: session.plugin_id.clone(), app_id: session.app.id.clone() }, command_id: action.action.clone() },
                                arguments,
                            }, session)
                            .await;
                    }
                }
            }
            if action.controller_id == "framework" {
                match action.action.as_str() {
                    "setAppearance" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.appearance_id = value.to_string();
                            self.note_shell_setting_command("os.setAppearance", Some(value)).await?;
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "setDriver" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.driver_id = value.to_string();
                            self.clear_driver_draft();
                            self.note_shell_setting_command("os.setDriver", Some(value)).await?;
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "setDriverField" => {
                        if let (Some(key), Some(value)) = (action.args.as_ref().and_then(|args| args.get("key")).and_then(|value| value.as_str()), action.args.as_ref().and_then(|args| args.get("value")).and_then(|value| value.as_str())) {
                            if self.set_driver_field(key, value) {
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "setDriverSaveLabel" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|value| value.as_str()) {
                            if self.driver_save_label != value {
                                self.driver_save_label = value.to_string();
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "saveDriver" => {
                        let label = self.driver_save_label.trim().to_string();
                        if let Some(id) = custom_ui_driver_id(&label) {
                            let mut driver = self.driver_document();
                            driver.driver_id = id.clone();
                            driver.label = label;
                            self.chrome_build.preferences.custom_drivers.insert(id.clone(), driver);
                            self.driver_id = id;
                            self.driver_save_label.clear();
                            self.clear_driver_draft();
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "deleteDriver" => {
                        if let Some(id) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|value| value.as_str()).filter(|id| id.starts_with("custom.")) {
                            let changed = self.chrome_build.preferences.custom_drivers.remove(id).is_some() || self.driver_id == id || self.driver_draft.is_some();
                            if self.driver_id == id {
                                self.driver_id = "default".into();
                            }
                            self.clear_driver_draft();
                            if changed {
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "setLocale" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let changed = self.locale_id != value;
                            self.locale_id = value.to_string();
                            crate::interpreter::install_ui_engine_locale(self.active_locale());
                            if let Some(status) = self.plugin_fault_status() {
                                self.error = Some(status);
                            }
                            self.trace_resolved_locale("setLocale");
                            self.note_shell_setting_command("os.setLocale", Some(value)).await?;
                            if changed {
                                self.sync_dock_tabs();
                                self.owe_refresh(UiDirtyScope::Full);
                                self.owe_settle();
                            }
                        }
                        return Ok(());
                    }
                    "setTerminology" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let changed = self.terminology_id != value;
                            self.terminology_id = value.to_string();
                            self.note_shell_setting_command("os.setTerminology", Some(value)).await?;
                            if changed {
                                self.sync_dock_tabs();
                                self.owe_refresh(UiDirtyScope::Full);
                                self.owe_settle();
                            }
                        }
                        return Ok(());
                    }
                    "setThemeId" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let changed = self.chrome_build.preferences.theme_id != value || self.theme_draft.is_some();
                            set_active_theme_id(value);
                            self.clear_theme_draft();
                            self.chrome_build.preferences.theme_id = value.to_string();
                            self.note_shell_setting_command("os.setThemeId", Some(value)).await?;
                            if changed {
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "runOsCommand" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let command_id = value.to_string();
                            self.apply_os_command(&command_id, None).await?;
                        }
                        return Ok(());
                    }
                    "setLayout" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.chrome_build.preferences.ui_layout = if value == "tablet" { "tablet".to_string() } else { "desktop".to_string() };
                            self.note_shell_setting_command("os.setLayout", Some(value)).await?;
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "setDefaultApp" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let key = action.args.as_ref().and_then(|args| args.get("row")).and_then(|v| v.as_str()).unwrap_or_default().to_string();
                            if value == DEFAULT_APP_NONE_VALUE {
                                self.default_app_pins.remove(&key);
                            } else {
                                self.default_app_pins.insert(key, value.to_string());
                            }
                        }
                        return Ok(());
                    }
                    "captureKeybinding" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            let already = self.keybinding_capture_control_id.as_deref() == Some(value);
                            self.keybinding_capture_control_id = (!already).then(|| value.to_string());
                        }
                        return Ok(());
                    }
                    "resetKeybinding" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.chrome_build.preferences.keybinding_overrides.remove(value);
                        }
                        return Ok(());
                    }
                    "setCommandExpanded" => {
                        if let Some(key) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|value| value.as_str()) {
                            let live = self.resolved_commands().into_iter().any(|entry| entry.definition.in_palette && !entry.definition.args.is_empty() && command_address_stable_key(&entry.address) == key);
                            if live {
                                self.expanded_command_id = (self.expanded_command_id.as_deref() != Some(key)).then(|| key.to_string());
                            }
                        }
                        return Ok(());
                    }
                    "executeResolvedCommand" => {
                        if let Some(key) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|value| value.as_str()).map(ToOwned::to_owned) {
                            if let Some(entry) = self.resolved_commands().into_iter().find(|entry| entry.definition.in_palette && entry.definition.args.is_empty() && command_address_stable_key(&entry.address) == key) {
                                match &entry.address.owner {
                                    semio_framework::manifest::CommandOwnerAddress::Os => {
                                        self.apply_os_command(&entry.definition.id, None).await?;
                                    }
                                    _ => {
                                        self.dispatch_command(semio_framework::manifest::CommandInvocation { address: entry.address, arguments: Default::default() }).await?;
                                    }
                                }
                            }
                        }
                        return Ok(());
                    }
                    "stageCommandArg" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(command), Some(arg)) = (args.get("command").and_then(Value::as_str), args.get("arg").and_then(Value::as_str)) {
                            let staged = self.staged_command_args.entry(command.to_string()).or_default();
                            let value = staged_arg_value(&args, staged.get(arg));
                            staged.insert(arg.to_string(), value);
                        }
                        return Ok(());
                    }
                    "resetStagedCommand" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.staged_command_args.remove(value);
                        }
                        return Ok(());
                    }
                    "executeStagedCommand" => {
                        if let Some(key) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()).map(ToOwned::to_owned) {
                            let staged = self.staged_command_args.get(&key).cloned().unwrap_or_default();
                            if let Some(entry) = self.resolved_commands().into_iter().find(|entry| entry.definition.in_palette && command_address_stable_key(&entry.address) == key) {
                                let Some(effective) = Self::resolved_execute_args(&entry.definition.args, &staged) else { return Ok(()) };
                                match &entry.address.owner {
                                    semio_framework::manifest::CommandOwnerAddress::Os => {
                                        let command_id = entry.definition.id.clone();
                                        let option = entry.definition.args.first().and_then(|arg| effective.get(&arg.id)).and_then(|value| value.as_str().map(ToOwned::to_owned));
                                        self.apply_os_command(&command_id, option.as_deref()).await?;
                                    }
                                    _ => {
                                        let arguments = effective.into_iter().filter_map(|(id, value)| serde_json::from_value::<DslValue>(value).ok().map(|value| (id, value))).collect();
                                        self.dispatch_command(semio_framework::manifest::CommandInvocation { address: entry.address.clone(), arguments }).await?;
                                    }
                                }
                            }
                            self.staged_command_args.remove(&key);
                            self.expanded_command_id = None;
                        }
                        return Ok(());
                    }
                    "setActionExpanded" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(window_id), Some(action_id)) = (args.get("window").and_then(Value::as_str), args.get("action").and_then(Value::as_str)) {
                            if self.action_panel_expanded.get(window_id).map(String::as_str) == Some(action_id) {
                                self.action_panel_expanded.remove(window_id);
                            } else {
                                self.action_panel_expanded.insert(window_id.to_string(), action_id.to_string());
                            }
                        }
                        return Ok(());
                    }
                    "stageActionArg" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(window_id), Some(action_id), Some(arg_id)) = (args.get("window").and_then(Value::as_str), args.get("action").and_then(Value::as_str), args.get("arg").and_then(Value::as_str)) {
                            let (window_id, action_id, arg_id) = (window_id.to_string(), action_id.to_string(), arg_id.to_string());
                            let value = staged_arg_value(&args, self.staged_map_for(&window_id, &action_id).get(&arg_id));
                            self.stage_arg(&window_id, &action_id, &arg_id, value);
                        }
                        return Ok(());
                    }
                    "resetActionArgs" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(window_id), Some(action_id)) = (args.get("window").and_then(Value::as_str), args.get("action").and_then(Value::as_str)) {
                            let (window_id, action_id) = (window_id.to_string(), action_id.to_string());
                            self.reset_staged_args(&window_id, &action_id);
                        }
                        return Ok(());
                    }
                    "executeStagedAction" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(window_id), Some(action_id)) = (args.get("window").and_then(Value::as_str), args.get("action").and_then(Value::as_str)) {
                            let (window_id, action_id) = (window_id.to_string(), action_id.to_string());
                            self.execute_staged_action(&window_id, &action_id).await?;
                        }
                        return Ok(());
                    }
                    "setEngagementInput" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let Some(window_id) = args.get("window").and_then(Value::as_str) {
                            let value = args.get("value").and_then(Value::as_str).unwrap_or_default().to_string();
                            self.engagement_inputs.insert(window_id.to_string(), value);
                        }
                        return Ok(());
                    }
                    "toggleSearchPossibles" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let Some(window_id) = args.get("window").and_then(Value::as_str) {
                            let open = self.search_possibles_open.get(window_id).copied().unwrap_or(false);
                            self.search_possibles_open.insert(window_id.to_string(), !open);
                        }
                        return Ok(());
                    }
                    "setWorldProjectionTemplate" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        if let (Some(window_id), Some(template_id)) = (args.get("windowId").and_then(Value::as_str), args.get("templateId").and_then(Value::as_str)) {
                            let (window_id, template_id) = (window_id.to_string(), template_id.to_string());
                            self.select_world_projection_template(&window_id, &template_id)?;
                        }
                        return Ok(());
                    }
                    "setLayoutSaveLabel" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.layout_save_label = value.to_string();
                        }
                        return Ok(());
                    }
                    "saveCurrentLayout" => {
                        let label = self.layout_save_label.trim().to_string();
                        if label.is_empty() {
                            return Ok(());
                        }
                        if let Some(layout) = self.current_named_layout(&label) {
                            let id = layout.id.clone();
                            self.user_layouts.retain(|entry| entry.id != id);
                            self.user_layouts.push(layout);
                            self.layout_save_label.clear();
                            self.persist_named_layouts();
                            self.note_shell_setting_command("os.saveNamedLayout", Some(&id)).await?;
                        }
                        return Ok(());
                    }
                    "applyNamedLayout" => {
                        if let Some(layout_id) = action.args.as_ref().and_then(|args| args.get("layoutId")).and_then(|v| v.as_str()).map(ToOwned::to_owned) {
                            if self.apply_named_layout(&layout_id) {
                                self.note_shell_setting_command("os.applyNamedLayout", Some(&layout_id)).await?;
                            }
                        }
                        return Ok(());
                    }
                    "deleteUserLayout" => {
                        if let Some(layout_id) = action.args.as_ref().and_then(|args| args.get("layoutId")).and_then(|v| v.as_str()).map(ToOwned::to_owned) {
                            self.user_layouts.retain(|entry| entry.id != layout_id);
                            self.persist_named_layouts();
                            self.note_shell_setting_command("os.deleteNamedLayout", Some(&layout_id)).await?;
                        }
                        return Ok(());
                    }
                    "openDisplayWindow" => {
                        let window_kind_id = action.args.as_ref().and_then(|args| args.get("windowKindId")).and_then(|v| v.as_str()).map(ToOwned::to_owned);
                        let template_id = action.args.as_ref().and_then(|args| args.get("templateId")).and_then(|v| v.as_str()).map(ToOwned::to_owned);
                        if let Some(window_kind_id) = window_kind_id {
                            self.open_display_window(&window_kind_id, template_id.as_deref());
                        }
                        return Ok(());
                    }
                    "selectConflict" => {
                        if let Some(conflict_id) = action.args.as_ref().and_then(|args| args.get("conflictId")).and_then(|v| v.as_str()) {
                            self.selected_conflict_id = (self.selected_conflict_id.as_deref() != Some(conflict_id)).then(|| conflict_id.to_string());
                        }
                        return Ok(());
                    }
                    "resolveConflict" => {
                        let conflict_id = action.args.as_ref().and_then(|args| args.get("conflictId")).and_then(|v| v.as_str()).map(ToOwned::to_owned);
                        let accept = action.args.as_ref().and_then(|args| args.get("accept")).and_then(DslValue::as_bool).unwrap_or(true);
                        if let Some(conflict_id) = conflict_id {
                            self.resolve_open_conflict(&conflict_id, accept).await;
                        }
                        return Ok(());
                    }
                    "installPlugin" | "reloadPlugin" => {
                        if let Some(plugin_id) = action.args.as_ref().and_then(|args| args.get("pluginId")).and_then(|v| v.as_str()).map(ToOwned::to_owned) {
                            if action.action == "reloadPlugin" {
                                self.uninstall_plugin(&plugin_id);
                            }
                            let _ = self.install_plugin(&plugin_id).await;
                            self.note_shell_setting_command(if action.action == "reloadPlugin" { "os.reloadPlugin" } else { "os.installPlugin" }, Some(&plugin_id)).await?;
                        }
                        return Ok(());
                    }
                    "uninstallPlugin" => {
                        if let Some(plugin_id) = action.args.as_ref().and_then(|args| args.get("pluginId")).and_then(|v| v.as_str()).map(ToOwned::to_owned) {
                            if self.uninstall_plugin(&plugin_id) {
                                self.note_shell_setting_command("os.uninstallPlugin", Some(&plugin_id)).await?;
                            }
                        }
                        return Ok(());
                    }
                    "installExtensionUrl" => {
                        let url = action.args.as_ref().and_then(|args| args.get("url")).and_then(|value| value.as_str()).filter(|url| !url.is_empty()).map(ToOwned::to_owned);
                        let mut request = serde_json::json!({
                            "op": "extension-store-install-url",
                            "prompt": shell_chrome_string("plugins.extension.urlPrompt", self.locale_id == "de")
                        });
                        if let Some(url) = url.as_deref() {
                            request["url"] = serde_json::Value::String(url.to_string());
                        }
                        if self.install_extension_from_store(request).await? {
                            self.note_shell_setting_command("os.installExtensionUrl", url.as_deref()).await?;
                        }
                        return Ok(());
                    }
                    "installExtensionFile" => {
                        if self.install_extension_from_store(serde_json::json!({ "op": "extension-store-install-file" })).await? {
                            self.note_shell_setting_command("os.installExtensionFile", None).await?;
                        }
                        return Ok(());
                    }
                    "setExtensionEnabled" => {
                        let extension_id = action.args.as_ref().and_then(|args| args.get("extensionId")).and_then(|value| value.as_str()).map(ToOwned::to_owned);
                        let enabled = action.args.as_ref().and_then(|args| args.get("enabled")).and_then(DslValue::as_bool).unwrap_or(true);
                        if let Some(extension_id) = extension_id {
                            if self.set_extension_enabled(&extension_id, enabled).await? {
                                self.note_shell_setting_command(if enabled { "os.enableExtension" } else { "os.disableExtension" }, Some(&extension_id)).await?;
                            }
                        }
                        return Ok(());
                    }
                    "uninstallExtension" => {
                        if let Some(extension_id) = action.args.as_ref().and_then(|args| args.get("extensionId")).and_then(|value| value.as_str()).map(ToOwned::to_owned) {
                            if self.uninstall_extension(&extension_id).await? {
                                self.note_shell_setting_command("os.uninstallExtension", Some(&extension_id)).await?;
                            }
                        }
                        return Ok(());
                    }
                    "setChatDraft" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            self.agent_chat_draft = value.to_string();
                        }
                        return Ok(());
                    }
                    "sendChatDraft" => {
                        self.send_agent_chat_draft();
                        return Ok(());
                    }
                    "cancelToolCall" => {
                        if let Some(invocation_id) = action.args.as_ref().and_then(|args| args.get("invocationId")).and_then(|value| value.as_str()).map(ToOwned::to_owned) {
                            self.cancel_agent_tool_call(&invocation_id);
                        }
                        return Ok(());
                    }
                    other if other.starts_with("hub") => {
                        self.handle_hub_workspace_action(&action.action.clone(), action.args.clone()).await;
                        return Ok(());
                    }
                    "setMergePolicy" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            if SHELL_MERGE_POLICY_OPTIONS.iter().any(|(option, _)| *option == value) {
                                self.merge_policy = value.to_string();
                                self.note_shell_setting_command("os.setMergePolicy", Some(value)).await?;
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_GENERAL_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "setThemeColor" | "setThemeSpacing" | "setThemeFontStack" | "setThemeStroke" | "setThemeRadius" | "setThemeOpacity" | "setThemeMetric" | "setThemeAppearancePaint" => {
                        let args = action.args.as_ref().map(dsl_value_as_json).unwrap_or(Value::Null);
                        let verb = action.action.clone();
                        let before = self.theme_document();
                        self.apply_theme_editor_commit(&verb, &args);
                        if self.theme_document() != before {
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "setThemeSaveLabel" => {
                        let value = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()).unwrap_or_default().to_string();
                        if self.theme_save_label != value {
                            self.theme_save_label = value;
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "saveTheme" => {
                        let label = self.theme_save_label.trim().to_string();
                        if let Some(id) = custom_theme_id_for_label(&label) {
                            let mut document = self.theme_document();
                            document.id = id.clone();
                            document.label = label;
                            if let Some(raw) = save_custom_theme_document(&id, &document) {
                                self.chrome_build.preferences.custom_themes.insert(id.clone(), raw);
                                self.chrome_build.preferences.theme_id = id.clone();
                                self.theme_draft = None;
                                self.theme_save_label.clear();
                                self.note_shell_setting_command("os.setThemeId", Some(id.as_str())).await?;
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    "exportTheme" => {
                        let document = self.theme_document();
                        if let Some(text) = document.canonical_json() {
                            download_media_export(&format!("{}.theme.dsl", document.id), "text/plain", &text, None);
                        }
                        return Ok(());
                    }
                    "importTheme" => {
                        #[cfg(target_arch = "wasm32")]
                        {
                            self.pending_theme_import = true;
                        }
                        #[cfg(not(target_arch = "wasm32"))]
                        self.submit_shell_io_future(async move {
                            let opened = request_file_open(SHELL_THEME_IMPORT_ACCEPT, Some("text"), false).await;
                            ShellIoCompletion::Actions(
                                opened.into_iter().take(1).map(|file| ActionDescriptor { controller_id: "framework".into(), action: "applyImportedTheme".into(), args: crate::action_args_json!({ "value": file.contents }) }).collect(),
                            )
                        });
                        return Ok(());
                    }
                    "applyImportedTheme" => {
                        if let Some(text) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            if let Some(document) = ThemeDocument::parse(text) {
                                let label = if document.label.is_empty() { document.id.clone() } else { document.label.clone() };
                                if let Some(id) = custom_theme_id_for_label(&label) {
                                    let saved = ThemeDocument { id: id.clone(), label, ..document };
                                    if let Some(raw) = save_custom_theme_document(&id, &saved) {
                                        self.chrome_build.preferences.custom_themes.insert(id.clone(), raw);
                                        self.chrome_build.preferences.theme_id = id.clone();
                                        self.theme_draft = None;
                                        self.note_shell_setting_command("os.setThemeId", Some(id.as_str())).await?;
                                        self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                                    }
                                }
                            }
                        }
                        return Ok(());
                    }
                    "resetThemeId" => {
                        let changed = self.chrome_build.preferences.theme_id != "semio" || self.theme_draft.is_some();
                        set_active_theme_id("semio");
                        self.clear_theme_draft();
                        self.chrome_build.preferences.theme_id = "semio".to_string();
                        self.note_shell_setting_command("os.resetThemeId", Some("semio")).await?;
                        if changed {
                            self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                        }
                        return Ok(());
                    }
                    "deleteThemeId" => {
                        if let Some(value) = action.args.as_ref().and_then(|args| args.get("value")).and_then(|v| v.as_str()) {
                            delete_custom_theme(value);
                            let removed = self.chrome_build.preferences.custom_themes.remove(value).is_some();
                            let selected = self.chrome_build.preferences.theme_id == value;
                            if selected {
                                self.chrome_build.preferences.theme_id = "semio".to_string();
                            }
                            self.note_shell_setting_command("os.deleteThemeId", Some(value)).await?;
                            if removed || selected {
                                self.republish_shell_panel_document(FRAMEWORK_SETTINGS_THEME_TAB_ID)?;
                            }
                        }
                        return Ok(());
                    }
                    _ => {}
                }
            }
            if action.controller_id == "framework.sync" {
                self.handle_sync_action(action).await?;
                return self.republish_shell_panel_document(FRAMEWORK_SYNC_PANEL_TAB_ID);
            }
            if action.controller_id == "framework.checkin" {
                return self.handle_checkin_action(action).await;
            }
            if action.action == semio_framework::SET_ACTIVE_UTILITY_ACTION_ID {
                if let Some(session) = self.session.clone() {
                    if action.controller_id == session.app.controller_id {
                        if let Some(utility_id) = action.args.as_ref().and_then(|args| args.get("utilityId")).and_then(|value| value.as_str()) {
                            let window_id = action
                                .args
                                .as_ref()
                                .and_then(|args| args.get("windowId"))
                                .and_then(|value| value.as_str())
                                .map(String::from)
                                .or_else(|| self.active_window_id.clone())
                                .unwrap_or_else(|| self.active_utility_bar_window_kind(&session).id.clone());
                            self.apply_set_active_utility(&window_id, utility_id);
                        }
                    }
                }
            }
            let Some(session) = self.action_session(&action).cloned() else {
                return Err("action has no mounted app owner".into());
            };
            let program = self.plugins.iter().find(|p| p.plugin_id == session.plugin_id).ok_or("action program missing")?;
            let live_view_state = self.live_view_state(&session);
            let invocation = self.session_action_invocation(&session, &action, &live_view_state)?;
            let action_json = semio_framework_pack_json::to_json_string(&invocation);
            let mut result = program.handle_action(session.instance_id, &action_json, &live_view_state).await?;
            self.observe_invocation_history(result.history_patch.as_ref()).await;
            self.observe_interaction_output(&result.output);
            if record_tutorial_after_acceptance {
                self.tutorial_start_recording();
            }
            self.chrome_tour_note_action_performed(&action.action);
            let mut queued = Vec::with_capacity(result.requested_effects.len());
            for effect in core::mem::take(&mut result.requested_effects) {
                match effect {
                    semio_framework::kernel::Effect::Navigate { uri } => {
                        self.push_uri(uri.clone());
                        if let Err(error) = self.apply_shell_uri(&uri).await {
                            Self::debug_log(&format!("[TRACE] wgpu shell navigate effect failed: {error}"));
                        }
                    }
                    semio_framework::kernel::Effect::ReplayShellCommand { action_id, args } => {
                        self.handle_replay_shell_command(&action_id, args.as_ref()).await;
                    }
                    other => queued.push(other),
                }
            }
            let scope = result.ui_scope.clone().merged_with(self.host_effect_earned_scope(&queued));
            Self::debug_log(&format!("[TRACE] wgpu-shell dispatch action={} scope={}", action.action, refresh_scope_label(&scope)));
            self.queue_host_effects(&action.controller_id.clone(), queued);
            let operations: Vec<String> = result.mutations.iter().filter_map(|operation| serde_json::to_string(&operation.diff.payload).ok()).collect();
            self.apply_ops_inner(&operations, true, scope, Some(session)).await

        })

    }

    /// 🎛️ Sends one owner-qualified non-OS command through the program command boundary.
    ///
    /// 🪟️ The LIVE view, exactly as `dispatch_action` and React's `makeEffectDispatchOne`
    /// (`resolveViewState(baseSession)`) read it: the session's stored `view_state` carries no
    /// window-instance roster, so a window-addressed command — every `flowEvalTick` the guest
    /// re-arms — was refused with `target window is absent from the exact ViewModel window
    /// instance roster` (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    ///
    /// 🧾️ ticket §C5 — same fold `dispatch_action` performs; a command-boundary edit (e.g. a
    /// plugin-owned command dispatched from the command palette) is just as real an uncommitted
    /// edit as an action-boundary one.
    ///
    /// 🧾️ ONE host-effect funnel for both dispatch paths. This arm used to be a SECOND,
    /// shorter hand-rolled fold, and every effect it did not name was dropped without a trace —
    /// including `InvokeExtension`, so the `flowEvalTick` reply that finally asked for an
    /// extension call went nowhere and the preview chain stopped one hop before its first
    /// evaluate (ticket 26/09/09/PROCEDURAL-3D-END-TO-END). React has the same single funnel:
    /// `makeEffectDispatchOne` hands BOTH `handleAction` and `handleCommand` results to
    /// `applyHostEffects`. Only the two effects `queue_host_effects` cannot own — a `Navigate`
    /// that must also RESOLVE the uri, and the replay relay — stay here, because both are
    /// `async` and that funnel is deliberately a plain `fn`.
    pub fn dispatch_command<'a>(&'a mut self, invocation: semio_framework::manifest::CommandInvocation) -> ShellTurn<'a, Result<(), String>> {
        shell_turn(async move {
            if matches!(invocation.address.owner, semio_framework::manifest::CommandOwnerAddress::Os) {
                return Err("os commands must be dispatched by the shell".into());
            }
            let window_id = invocation.arguments.get("windowId").and_then(DslValue::as_str);
            let session = self.command_session(&invocation.address.owner, window_id).cloned().ok_or("command has no mounted app owner")?;
            self.dispatch_session_command(invocation, session).await
        })
    }

    /// 🧵️ A retained command keeps the exact session selected by its source document.
    fn dispatch_session_command<'a>(&'a mut self, invocation: semio_framework::manifest::CommandInvocation, session: ActiveSession) -> ShellTurn<'a, Result<(), String>> {
        shell_turn(async move {
            let owner_plugin_id = match &invocation.address.owner {
                semio_framework::manifest::CommandOwnerAddress::Plugin { plugin_id } | semio_framework::manifest::CommandOwnerAddress::App { plugin_id, .. } | semio_framework::manifest::CommandOwnerAddress::Mode { plugin_id, .. } => plugin_id,
                semio_framework::manifest::CommandOwnerAddress::Os => return Err("os commands must be dispatched by the shell".into()),
            };
            let program = self.plugins.iter().find(|entry| entry.plugin_id == *owner_plugin_id).cloned().ok_or("command program missing")?;
            let command_json = semio_framework_pack_json::to_json_string(&invocation);
            let live_view_state = self.live_view_state(&session);
            let mut result = program.handle_command(session.instance_id, &command_json, &live_view_state).await?;
            Self::debug_log(&format!("[TRACE] wgpu-shell command {} settled effects={} mutations={}", invocation.address.command_id, result.requested_effects.len(), result.mutations.len()));
            self.observe_invocation_history(result.history_patch.as_ref()).await;
            self.observe_interaction_output(&result.output);
            let mut queued = Vec::with_capacity(result.requested_effects.len());
            for effect in core::mem::take(&mut result.requested_effects) {
                match effect {
                    semio_framework::kernel::Effect::Navigate { uri } => {
                        self.push_uri(uri.clone());
                        self.apply_shell_uri(&uri).await?;
                    }
                    semio_framework::kernel::Effect::ReplayShellCommand { action_id, args } => {
                        self.handle_replay_shell_command(&action_id, args.as_ref()).await;
                    }
                    other => queued.push(other),
                }
            }
            let scope = result.ui_scope.clone().merged_with(self.host_effect_earned_scope(&queued));
            Self::debug_log(&format!("[TRACE] wgpu-shell dispatch command={} scope={}", invocation.address.command_id, refresh_scope_label(&scope)));
            self.queue_host_effects(&session.app.controller_id.clone(), queued);
            let operations: Vec<String> = result.mutations.iter().filter_map(|operation| serde_json::to_string(&operation.diff.payload).ok()).collect();
            self.apply_ops_inner(&operations, true, scope, Some(session)).await
        })
    }

    //#region 🔖️DirectoryAndIdentity
    //#region 📇️DirectoryLane
    /// 📇️ ticket §C6/§3/§4 — dispatches a `ReplayShellCommand`'s `action_id`/`args` onto the directory funnel, the opening
    /// relay or the creation door; an `os.*` command this shell cannot serve is refused out loud ([`Self::refuse_replay`]) —
    /// the local studio catalog (`os.local-catalog.*`) until route B's native half lands, any unknown one as unrouted.
    fn handle_replay_shell_command<'a>(&'a mut self, action_id: &'a str, args: Option<&'a DslValue>) -> ShellTurn<'a, ()> {
        shell_turn(async move {
            let args_json = args.map(dsl_value_as_json);
            if action_id == "os.directory.open-administration" {
                let space_id = args_json.as_ref().and_then(|args| args.get("spaceId")).and_then(Value::as_str).unwrap_or_default().to_string();
                self.open_space_administration(&space_id);
                return;
            }
            if let Some(command) = directory_command_from_action(action_id, args_json.as_ref()) {
                self.dispatch_directory_command(command).await;
                return;
            }
            if action_id == "os.open-artifact" || action_id == "os.open-artifact-with" {
                self.handle_open_artifact_relay(action_id, args_json.as_ref()).await;
                return;
            }
            let refusal = if action_id == "os.create-space-artifact" {
                self.replay_create_space_artifact(args_json.as_ref()).await.err()
            } else if action_id.starts_with("os.local-catalog.") {
                Some(ReplayRefusalReasonV1::LocalCatalogUnavailable)
            } else if action_id.starts_with("os.directory.") {
                Some(ReplayRefusalReasonV1::InvalidRequest)
            } else if action_id.starts_with("os.") {
                Some(ReplayRefusalReasonV1::UnroutedCommand)
            } else {
                None
            };
            if let Some(reason) = refusal {
                self.refuse_replay(reason);
            }
        })
    }

    /// 📣️ Refuses one guest `replayShellCommand` out loud: the shared vocabulary's warning notice in this shell's tongue,
    /// carrying the reason's fault code — React's `refuseReplay`.
    fn refuse_replay(&mut self, reason: ReplayRefusalReasonV1) {
        let code = reason.code();
        self.show_transient_notice(reason.notice_text(&self.locale_id), semio_framework::Severity::Warning, Some(code.as_str()));
    }

    /// 🌱️ `os.create-space-artifact {kindChoice, name}` from the mounted Space index guest onto this shell's ONE creation door —
    /// ShellHost's route: a signed-in identity, the index's own space, a choice the space's ready catalog offers
    /// ([`space_artifact_creation_replay_choice`]); the door then seals the intent under its minted key, submits it and opens the
    /// ready artifact ([`Self::pump_hub_artifact_creation`]). A busy or not-yet-ready door asks the user to try again.
    async fn replay_create_space_artifact(&mut self, args: Option<&Value>) -> Result<(), ReplayRefusalReasonV1> {
        if self.identity.is_none() {
            return Err(ReplayRefusalReasonV1::SignInRequired);
        }
        let index_mounted = self.sync_channel.as_ref().is_some_and(|channel| channel.document_id == S_SPACE_INDEX_DOCUMENT_ID);
        let space_id = self.open_space_id.clone().filter(|space_id| index_mounted && !space_id.is_empty()).ok_or(ReplayRefusalReasonV1::SpaceIndexRequired)?;
        if self.hub_workspace.open_space_id.as_deref() != Some(space_id.as_str()) || self.hub_workspace.creation.catalog.as_ref().is_none_or(|catalog| catalog.space_id != space_id) {
            self.hub_workspace.open_space_id = Some(space_id.clone());
            self.open_hub_artifact_creation(&space_id).await;
        }
        let (kind_id, name) = space_artifact_creation_replay_choice(args, self.hub_workspace.creation.catalog.as_ref(), &space_id).await?;
        let creation = &mut self.hub_workspace.creation;
        creation.kind_id = Some(kind_id);
        creation.name_draft = name;
        if hub_artifact_creation_intent(&self.hub_workspace).is_none() {
            let busy = self.hub_workspace.creation.catalog_phase != HubArtifactCatalogPhase::Ready || self.hub_workspace.creation.operation.as_ref().is_some_and(|operation| !hub_artifact_creation_terminal(operation.phase));
            return Err(if busy { ReplayRefusalReasonV1::RouterNotReady } else { ReplayRefusalReasonV1::InvalidRequest });
        }
        self.begin_hub_artifact_creation();
        self.pump_hub_artifact_creation().await;
        Ok(())
    }

    /// 🏛️ Installs the one retained administration operation for exactly one space, retiring any
    /// predecessor first. Nothing is administrable until the hub's own canonical page has landed.
    pub fn open_space_administration(&mut self, space_id: &str) {
        if space_id.trim().is_empty() || self.identity.is_none() {
            return;
        }
        self.close_space_administration();
        self.space_administration_epoch = self.space_administration_epoch.saturating_add(1);
        self.space_administration = Some(ShellSpaceAdministrationOperationV1::open(self.space_administration_epoch, space_id));
    }

    /// 🧯️ Retires the operation: page, receipt, and capability are erased before anything observes it.
    pub fn close_space_administration(&mut self) {
        if let Some(operation) = self.space_administration.as_mut() {
            operation.terminate(ShellSpaceAdministrationPhaseV1::Cancelled, Some(DirectoryCommandErrorCodeV1::Cancelled));
        }
        self.space_administration = None;
    }

    /// 🎁️ Hands the one-shot invite capability to the caller exactly once, erasing it in the same turn.
    pub fn acknowledge_space_administration_capability(&mut self) -> Option<String> {
        self.space_administration.as_mut().and_then(ShellSpaceAdministrationOperationV1::acknowledge_capability)
    }

    /// 🎬️ Drives exactly one bounded administration turn against the real `DirectoryClient`. Returns
    /// `true` while the operation still has work, so the frame loop can pump it without spinning.
    /// A mutation is never retried: an indeterminate transport settles `Failed`, and only an exact
    /// server receipt advances the operation, always followed by a mandatory page refresh.
    pub async fn pump_space_administration(&mut self) -> bool {
        let Some(client) = self.directory_client.clone() else { return false };
        let epoch = self.space_administration_epoch;
        let Some(turn) = self.space_administration.as_mut().map(ShellSpaceAdministrationOperationV1::turn) else { return false };
        match turn {
            ShellSpaceAdministrationTurnV1::Idle => false,
            ShellSpaceAdministrationTurnV1::Closed => {
                self.space_administration = None;
                false
            }
            ShellSpaceAdministrationTurnV1::FetchPage { cursor } => {
                let space_id = self.space_administration.as_ref().map(|operation| operation.space_id().to_string()).unwrap_or_default();
                let result = client.space_administration_page(&self.directory_command_ctx(), &space_id, cursor.as_deref()).await;
                let Some(operation) = self.space_administration.as_mut().filter(|operation| operation.operation_epoch() == epoch) else { return false };
                match result {
                    Ok(page) => {
                        let canonical = page.canonical_json().to_string();
                        if !operation.apply_page(canonical, page.page().clone()) {
                            operation.terminate(ShellSpaceAdministrationPhaseV1::Failed, Some(DirectoryCommandErrorCodeV1::Invalid));
                        }
                    }
                    Err(error) => operation.fail_page(&error),
                }
                true
            }
            ShellSpaceAdministrationTurnV1::Submit { request } => {
                let result = client.command(&self.directory_command_ctx(), &request).await;
                let Some(operation) = self.space_administration.as_mut().filter(|operation| operation.operation_epoch() == epoch) else { return false };
                match result {
                    Ok(canonical) => {
                        if !operation.apply_receipt(&canonical.receipt) {
                            operation.terminate(ShellSpaceAdministrationPhaseV1::Failed, Some(DirectoryCommandErrorCodeV1::Invalid));
                        }
                    }
                    Err(code) => operation.fail_command(code),
                }
                true
            }
        }
    }

    /// 🪪️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (terra-directory-and-run): builds this shell's
    /// `OperationContext` for one directory request — `cancel` is a `.child()` of `directory_cancel`
    /// (this shell's ONE root, see that field's own doc), so cancelling `directory_cancel` once
    /// transitively cancels every in-flight directory request/stream at once. No deadline yet (see
    /// the packet report's honest gaps).
    fn directory_ctx(&self) -> OperationContext {
        OperationContext { actor: 0, generation: 0, trace: TraceId(0), lane: 0, deadline_ms: None, cancel: self.directory_cancel.child_now(), capability: None }
    }

    /// 🛑️ One command-scoped context: a fresh `directory_cancel` child plus a finite deadline, so a
    /// hung hub can never retain a command turn forever. Cancelling the wait does NOT cancel a
    /// command already past its server linearization point — the operation becomes indeterminate and
    /// keeps its request id for an explicit later resolution, never a silently fresh one.
    fn directory_command_ctx(&self) -> OperationContext {
        let mut context = self.directory_ctx();
        context.deadline_ms = Some(Self::directory_now_ms().saturating_add(DIRECTORY_COMMAND_DEADLINE_MS));
        context
    }

    /// ⏱️ The clock a directory deadline is measured against — necessarily the SAME one the linked
    /// transport compares it to. Native hands the shared `WorkerPool`'s own monotonic millis (what
    /// `NativeDirectoryTransport`'s `HttpPool` reads); the browser door has no pool and the page
    /// answers every hop with `fetch`'s own timing, so `Date.now()` is the only shared reading.
    #[cfg(not(target_arch = "wasm32"))]
    fn directory_now_ms() -> u64 {
        crate::renderer_worker_pool().now_ms()
    }

    #[cfg(target_arch = "wasm32")]
    fn directory_now_ms() -> u64 {
        let millis = chrome_now_ms();
        if millis.is_finite() && millis > 0.0 {
            millis as u64
        } else {
            0
        }
    }

    /// 📇️ ticket §4/§C6 — seals one `os.directory.*` command under a fresh idempotency correlation
    /// and issues it against the hub, dropping it when no identity is signed in at all, else leaving
    /// it queued on a transient failure (the "same offline queueing behaviour as the React side" the
    /// brief asks for — React's worker queues in-memory and flushes on reconnect; this shell's
    /// `directory_commands` + `flush_pending_directory_commands` (called every frame from
    /// `pump_directory_events`) is the native twin of that policy).
    async fn dispatch_directory_command(&mut self, command: DirectoryCommand) {
        if self.identity.is_none() {
            return;
        }
        self.directory_commands.admit_first(DirectoryCommandRequestV1::new(mint_directory_command_request_id(), command));
        self.flush_pending_directory_commands().await;
    }

    /// ♻️ Drives the FIFO in order: a transient fault retains the head and its byte-identical sealed
    /// request and stops the queue; a terminal auth/conflict/validation failure produces a result and
    /// lets the queue proceed, so one forbidden command can never wedge every later one. Every receipt's
    /// events are folded into the hub panel's space rows at once (read-your-writes,
    /// [`crate::space_browser::space_rows_after_events`]), so a space the user just created is listed
    /// whatever the following list query answers.
    async fn flush_pending_directory_commands(&mut self) {
        let Some(client) = self.directory_client.clone() else { return };
        while let Some(request) = self.directory_commands.head().cloned() {
            let outcome = client.command(&self.directory_command_ctx(), &request).await.map(|canonical| canonical.receipt);
            if let (Ok(receipt), Some(identity)) = (&outcome, self.identity.as_ref()) {
                self.hub_workspace.rows = crate::space_browser::space_rows_after_events(&self.hub_workspace.rows, &receipt.events, &identity.user_id);
                self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Ready;
            }
            if !self.directory_commands.settle(outcome) {
                break;
            }
        }
    }

    /// 🪪️ Browser identity bootstrap. The hub session on this target is a same-origin COOKIE, not an
    /// inherited one-shot fd-3 credential, so there is nothing to `restore_claimed`: the shell asks
    /// the SAME `GET /auth/sessions/me` the React shell's `directoryClient.me()` asks, through an
    /// unauthenticated client whose door sends `credentials: "include"`. A refusal parks the retry
    /// floor instead of retrying every frame, and never clears an identity already resolved.
    #[cfg(target_arch = "wasm32")]
    async fn poll_browser_identity(&mut self) -> bool {
        if self.identity.is_some() || self.identity_env.is_none() {
            return false;
        }
        let now_ms = Self::directory_now_ms();
        if now_ms < self.identity_retry_at_ms {
            return false;
        }
        self.identity_retry_at_ms = now_ms.saturating_add(BROWSER_IDENTITY_RETRY_MS);
        let client = std::sync::Arc::new(DirectoryClient::new(shell_directory_transport(), shell_directory_request_base_url()));
        match client.me(&self.directory_ctx()).await {
            Ok(session) => {
                self.identity = Some(Identity { user_id: session.user_id.clone(), email: session.email.clone(), display_name: session.display_name.clone(), hub_base_url: client.base_url().to_string(), issued_at_ms: chrome_now_ms() as i64 });
                self.verified_session_authority = Some(session);
                self.identity_offline = false;
                self.directory_client = Some(client);
                self.project_verified_hub_authority();
                true
            }
            Err(error) => {
                self.identity_offline = true;
                Self::debug_log(&format!("[TRACE] wgpu shell browser identity bootstrap failed: {error}"));
                false
            }
        }
    }

    /// 📇️ The browser's every-frame directory turn — the same three steps the native
    /// `pump_directory_events` takes, minus the two halves whose transports this target has no door
    /// for: the retained Home projection (needs the directory WebSocket) and the document-sync
    /// backbone. Identity, the bounded administration operation and the command FIFO are the SAME
    /// code compiled for both targets.
    ///
    /// 🌉️ Packet W15e: the agent bridge's socket rides the SAME 100 ms slot rather than a timer of
    /// its own — one pump cadence for every out-of-process conversation this shell holds.
    #[cfg(target_arch = "wasm32")]
    pub async fn pump_directory_events(&mut self) -> bool {
        let identity_changed = self.poll_browser_identity().await;
        let administration_changed = self.pump_space_administration().await;
        self.flush_pending_directory_commands().await;
        let creation_changed = self.pump_hub_artifact_creation().await;
        let hub_changed = self.poll_hub_workspace_tasks();
        let bridge_changed = self.pump_agent_bridge();
        identity_changed || administration_changed || creation_changed || hub_changed || bridge_changed
    }

    //#endregion 📇️DirectoryLane

    //#region 🔐️HubWorkspaceLane
    /// 🔐️ The ONE lane every `hub*` verb the hub workspace names runs through (slice WG6). Drafts
    /// are pure state writes; the four verbs that leave the process go through the shell's own
    /// `DirectoryTransport`, so this renderer's sign-in is the same transport its directory client
    /// already uses rather than a second HTTP door.
    ///
    /// 🏠️ Nothing here can ever stop local work: every failure lands in the session's `error` slot
    /// or in the spaces `Stale` phase, and the surface keeps rendering.
    ///
    /// 📋️ `COPY_INVITE_LINK` is deliberately unreachable on this renderer: the surface only paints
    /// that control when `clipboard_available` is set, and the wgpu frame Worker owns no clipboard
    /// door (see this file's own note in the retained editor lane).
    fn handle_hub_workspace_action<'a>(&'a mut self, verb: &'a str, args: Option<DslValue>) -> ShellTurn<'a, ()> {
        shell_turn(async move {
            let value = args.as_ref().and_then(|args| args.get("value")).and_then(DslValue::as_str).unwrap_or_default().to_string();
            let space_id = args.as_ref().and_then(|args| args.get("spaceId")).and_then(DslValue::as_str).unwrap_or_default().to_string();
            let connection_id = args.as_ref().and_then(|args| args.get("connectionId")).and_then(DslValue::as_str).unwrap_or_default().to_string();
            match verb {
                hub_action::SET_EMAIL => self.hub_workspace.email_draft = value,
                hub_action::SET_PASSWORD => self.hub_workspace.password_draft = value,
                hub_action::SET_ADDRESS => self.hub_workspace.address_draft = value,
                hub_action::SET_SEARCH => self.hub_workspace.search_draft = value,
                hub_action::SET_SPACE_NAME => self.hub_workspace.space_name_draft = value,
                hub_action::SET_INVITE_TEXT => self.hub_workspace.invite_draft = value,
                hub_action::DISCARD_INVITE_LINK => self.hub_workspace.invite_capability = None,
                hub_action::CLOSE_WORKSPACE => {
                    self.hub_workspace.open_space_id = None;
                    self.hub_workspace_open = false;
                }
                hub_action::SELECT_CONNECTION => {
                    let next = select_hub_connection(&self.hub_workspace.book, &connection_id);
                    if next.selected_id != self.hub_workspace.book.selected_id {
                        self.hub_workspace.book = next;
                        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::SelectConnection { connection_id });
                        self.clear_hub_session_owner();
                        self.hub_workspace.rows.clear();
                        self.hub_workspace.members.clear();
                        self.hub_workspace.open_space_id = None;
                        self.persist_hub_connection_book();
                    }
                }
                hub_action::ADD_CONNECTION => match parse_hub_origin(&self.hub_workspace.address_draft) {
                    Some(origin) => {
                        let connection = HubConnection { id: hub_connection_id_for_origin(&origin), kind: HubConnectionKind::Remote, label: origin.clone(), last_user_id: None, origin };
                        let connection_id = connection.id.clone();
                        self.hub_workspace.book = upsert_hub_connection(&self.hub_workspace.book, connection);
                        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::SelectConnection { connection_id });
                        self.hub_workspace.address_draft.clear();
                        self.clear_hub_session_owner();
                        self.persist_hub_connection_book();
                    }
                    None => self.hub_workspace.session.error = Some(HubSignInErrorCode::MalformedRequest),
                },
                hub_action::FORGET_CONNECTION => {
                    let selected = self.hub_workspace.book.selected_id.clone();
                    self.hub_workspace.book = remove_hub_connection(&self.hub_workspace.book, &selected);
                    let connection_id = self.hub_workspace.book.selected_id.clone();
                    self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::SelectConnection { connection_id });
                    self.clear_hub_session_owner();
                    self.persist_hub_connection_book();
                }
                hub_action::CANCEL_SIGN_IN => {
                    if let Some(task) = self.hub_sign_in_task.take() {
                        task.cancel();
                    }
                    self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::Failed { code: HubSignInErrorCode::Cancelled, retry_after_seconds: None });
                }
                hub_action::SIGN_IN => self.start_hub_sign_in(),
                hub_action::SIGN_OUT => self.run_hub_sign_out_turn().await,
                hub_action::REFRESH_SPACES => self.start_hub_spaces_reload(),
                hub_action::OPEN_SPACE => {
                    self.hub_workspace.open_space_id = (!space_id.is_empty()).then(|| space_id.clone());
                    self.reload_hub_members(&space_id).await;
                    self.open_hub_artifact_creation(&space_id).await;
                    if !space_id.is_empty() {
                        let uri = format!("/spaces/{space_id}");
                        self.push_uri(uri.clone());
                        let _ = self.apply_shell_uri(&uri).await;
                    }
                }
                hub_action::CREATE_SPACE => {
                    let name = self.hub_workspace.space_name_draft.clone();
                    if let Some(command) = crate::space_browser::create_space_command(&name, DirectorySpaceKind::Studio, DirectorySpaceVisibility::Private) {
                        self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Submitting;
                        self.dispatch_directory_command(command).await;
                        self.hub_workspace.space_name_draft.clear();
                        self.start_hub_spaces_reload();
                    }
                }
                hub_action::CREATE_INVITE => self.run_hub_create_invite_turn(&space_id).await,
                hub_action::REDEEM_INVITE => self.run_hub_redeem_turn().await,
                hub_action::SELECT_ARTIFACT_KIND => {
                    let kind_id = args.as_ref().and_then(|args| args.get("kindId")).and_then(DslValue::as_str).unwrap_or_default();
                    let creation = &mut self.hub_workspace.creation;
                    if creation.catalog.as_ref().is_some_and(|catalog| catalog.kinds.iter().any(|kind| kind.kind_id == kind_id)) {
                        creation.kind_id = Some(kind_id.to_string());
                    }
                }
                hub_action::SET_ARTIFACT_NAME => self.hub_workspace.creation.name_draft = value,
                hub_action::CREATE_ARTIFACT => {
                    self.begin_hub_artifact_creation();
                    self.pump_hub_artifact_creation().await;
                }
                hub_action::CANCEL_ARTIFACT_CREATION => {
                    if let Some(operation) = self.hub_workspace.creation.operation.as_mut().filter(|operation| !hub_artifact_creation_terminal(operation.phase)) {
                        operation.cancel_requested = true;
                    }
                    self.pump_hub_artifact_creation().await;
                }
                hub_action::OPEN_CREATED_ARTIFACT => {
                    self.open_created_hub_artifact().await;
                }
                _ => {}
            }
            let _ = self.refresh_ui(UiDirtyScope::Full).await;
        })
    }

    /// 🌱️ Opens the creation door for `space_id`: a fresh door holding a minted idempotency key, then
    /// the space's selected current catalog. A hub with no ready catalog leaves the door
    /// `Unavailable`, saying so in both languages; local work never waits on it.
    async fn open_hub_artifact_creation(&mut self, space_id: &str) {
        self.hub_workspace.creation = HubArtifactCreationState { next_request_id: mint_directory_command_request_id(), ..HubArtifactCreationState::default() };
        let Some(client) = self.directory_client.clone().filter(|_| !space_id.is_empty()) else { return };
        self.hub_workspace.creation.catalog_phase = HubArtifactCatalogPhase::Loading;
        match client.space_artifact_creation_catalog(&self.directory_command_ctx(), space_id).await {
            Ok(catalog) => {
                self.hub_workspace.creation.catalog = Some(catalog);
                self.hub_workspace.creation.catalog_phase = HubArtifactCatalogPhase::Ready;
            }
            Err(_) => self.hub_workspace.creation.catalog_phase = HubArtifactCatalogPhase::Unavailable,
        }
    }

    /// 📥️ Seals the door's intent under its minted key and mints the next one at once, so no later
    /// click can resubmit this request id as a second creation. The frame pump submits it.
    fn begin_hub_artifact_creation(&mut self) {
        let Some(space_id) = self.hub_workspace.open_space_id.clone() else { return };
        let Some(intent) = hub_artifact_creation_intent(&self.hub_workspace) else { return };
        let now_ms = Self::directory_now_ms();
        let creation = &mut self.hub_workspace.creation;
        creation.next_request_id = mint_directory_command_request_id();
        creation.operation = Some(HubArtifactCreation {
            intent,
            space_id,
            phase: SpaceArtifactCreationPhaseV1::Accepted,
            submitted: false,
            cancel_requested: false,
            cancel_sent: false,
            ready: None,
            opening: HubArtifactOpening::Idle,
            last_answered_at_ms: now_ms,
            polls: 0,
            next_poll_at_ms: now_ms,
        });
    }

    /// 🌱️ Drives the one creation by at most one bounded hub request per frame — its submission, its
    /// cancellation, or a status poll after the shared backoff ([`crate::hub_connection::space_artifact_creation_poll_delay_ms`]) —
    /// and opens the artifact once the receipt is `Ready`. The creation is followed for as long as the hub
    /// answers; only a hub silent past the shared bound makes it `Indeterminate` (the hub may still finish
    /// it), never `Failed` — React's worker follows the same contract (`🌱️creation-polling`). A `409` on the
    /// submission means the catalog generation moved: the door re-reads the catalog instead of
    /// retrying. Answers whether the door changed.
    async fn pump_hub_artifact_creation(&mut self) -> bool {
        let Some(operation) = self.hub_workspace.creation.operation.clone() else { return false };
        if hub_artifact_creation_terminal(operation.phase) {
            if operation.ready.is_some() && operation.opening == HubArtifactOpening::Idle {
                self.open_created_hub_artifact().await;
                return true;
            }
            if operation.opening == HubArtifactOpening::Opening && !self.document_opening.as_ref().is_some_and(ShellDocumentOpening::running) {
                let opened = operation.ready.as_ref().is_some_and(|ready| self.sync_channel.as_ref().is_some_and(|channel| channel.document_id == ready.artifact_id));
                if let Some(current) = self.hub_workspace.creation.operation.as_mut() {
                    current.opening = if opened { HubArtifactOpening::Opened } else { HubArtifactOpening::Failed };
                }
                return true;
            }
            return false;
        }
        let Some(client) = self.directory_client.clone() else { return false };
        let now_ms = Self::directory_now_ms();
        if crate::hub_connection::space_artifact_creation_unreachable(operation.last_answered_at_ms, now_ms) {
            if let Some(current) = self.hub_workspace.creation.operation.as_mut() {
                current.phase = SpaceArtifactCreationPhaseV1::Indeterminate;
            }
            return true;
        }
        let request_id = operation.intent.request_id.as_str();
        let context = self.directory_command_ctx();
        let (receipt, submission, cancellation) = if !operation.submitted {
            (client.create_space_artifact(&context, &operation.space_id, &operation.intent).await, true, false)
        } else if operation.cancel_requested && !operation.cancel_sent {
            (client.cancel_space_artifact_creation(&context, &operation.space_id, request_id).await, false, true)
        } else if now_ms >= operation.next_poll_at_ms {
            (client.space_artifact_creation_status(&context, &operation.space_id, request_id).await, false, false)
        } else {
            return false;
        };
        let mut refresh_catalog = false;
        {
            let Some(current) = self.hub_workspace.creation.operation.as_mut().filter(|current| current.intent.request_id == operation.intent.request_id) else { return false };
            current.submitted = true;
            current.cancel_sent |= cancellation;
            let answered_at_ms = Self::directory_now_ms();
            current.next_poll_at_ms = answered_at_ms.saturating_add(crate::hub_connection::space_artifact_creation_poll_delay_ms(current.polls));
            current.polls = current.polls.saturating_add(1);
            if receipt.is_ok() {
                current.last_answered_at_ms = answered_at_ms;
            }
            match receipt {
                Ok(status) if status.catalog_generation_id == current.intent.expected_catalog_generation_id && status.ready.as_ref().is_none_or(|ready| ready.kind_id == current.intent.kind_id) => {
                    current.phase = status.phase;
                    current.ready = status.ready;
                }
                Ok(_) => current.phase = SpaceArtifactCreationPhaseV1::Failed,
                Err(DirectoryClientError::Http { status: 409, .. }) if submission => {
                    current.phase = SpaceArtifactCreationPhaseV1::Failed;
                    refresh_catalog = true;
                }
                Err(DirectoryClientError::Http { status, .. }) if (400..500).contains(&status) => current.phase = SpaceArtifactCreationPhaseV1::Failed,
                Err(DirectoryClientError::Unauthorized) => current.phase = SpaceArtifactCreationPhaseV1::Failed,
                Err(_) => {}
            }
        }
        if refresh_catalog {
            let space_id = operation.space_id.clone();
            let operation = self.hub_workspace.creation.operation.take();
            self.open_hub_artifact_creation(&space_id).await;
            self.hub_workspace.creation.operation = operation;
        }
        true
    }

    /// 🚪️ Opens a ready artifact through the ordinary document-open relay, bound to its space, with
    /// the dialect and schema the hub's receipt names; the relay resolves and mounts the owning app.
    /// The relay's open is frame-pumped, so the door stays `Opening` until it settles, and is `Opened`
    /// only when this shell's document binding then names the created artifact
    /// ([`Self::pump_hub_artifact_creation`]).
    async fn open_created_hub_artifact(&mut self) {
        let Some((ready, space_id)) = self.hub_workspace.creation.operation.as_ref().and_then(|operation| operation.ready.clone().map(|ready| (ready, operation.space_id.clone()))) else { return };
        if let Some(operation) = self.hub_workspace.creation.operation.as_mut() {
            operation.opening = HubArtifactOpening::Opening;
        }
        let dialect = semio_framework::ArtifactDialect { artifact_kind: ready.parent_dialect.artifact_kind.clone(), standard: ready.parent_dialect.standard.clone(), subset: ready.parent_dialect.subset.clone() };
        let args = serde_json::json!({ "artifactRef": dialect.to_coordinate(), "documentId": ready.artifact_id, "schema": ready.artifact_schema, "spaceId": space_id });
        self.handle_open_artifact_relay("os.open-artifact", Some(&args)).await;
    }

    fn persist_hub_connection_book(&self) {
        prefs_set(HUB_CONNECTION_BOOK_STORAGE_KEY_V1, &serialize_hub_connection_book(&self.hub_workspace.book));
    }

    fn clear_hub_session_owner(&mut self) {
        if let Some(task) = self.hub_sign_in_task.take() {
            task.cancel();
        }
        if let Some(task) = self.hub_spaces_task.take() {
            task.cancel();
        }
        self.directory_client = None;
        #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.identity = None;
        self.verified_session_authority = None;
        self.hub_workspace.display_name = None;
    }

    fn project_verified_hub_authority(&mut self) {
        let Some(authority) = self.verified_session_authority.as_ref() else { return };
        let Some(client) = self.directory_client.as_ref() else { return };
        if client.base_url() != self.hub_workspace.origin() {
            return;
        }
        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::Minted { user_id: authority.user_id.clone(), expires_at_ms: Some(authority.expires_at) });
        self.hub_workspace.display_name = Some(authority.display_name.clone());
    }

    /// 🔐️ Arms one credential sign-in against the SELECTED hub's own origin: the mint, then the `me` read that carries
    /// the deadline the mint answer deliberately omits (AU1 §1.1, AU3 §4.2), run as a [`ShellHubTask`] so the frame keeps
    /// taking input while the hub hashes the password. A second submit while one runs is ignored (the form disables it).
    ///
    /// 🔑️ The password draft is cleared the moment the attempt takes it: the one request that needs it owns it.
    fn start_hub_sign_in(&mut self) {
        if self.hub_sign_in_task.is_some() {
            return;
        }
        let origin = self.hub_workspace.origin().to_string();
        let credential = HubSignInCredential {
            email: self.hub_workspace.email_draft.clone(),
            password: std::mem::take(&mut self.hub_workspace.password_draft),
            device_instance_id: shell_hub_device_instance_id(&self.shell_session_id),
            client_class: if cfg!(target_arch = "wasm32") { HubSignInClientClass::Browser } else { HubSignInClientClass::Native },
        };
        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::Submit);
        let mut ctx = self.directory_ctx();
        ctx.deadline_ms = Some(Self::directory_now_ms().saturating_add(HUB_SIGN_IN_DEADLINE_MS));
        let cancel = ctx.cancel.clone();
        let transport = self.directory_transport.clone();
        self.hub_sign_in_task = Some(ShellHubTask::spawn(cancel, async move {
            let result = match crate::hub_connection::run_hub_sign_in(&transport, &ctx, &origin, &credential).await {
                crate::hub_connection::HubSignInOutcome::Failed { code, retry_after_seconds } => return ShellHubSignInAnswer::Failed { code, retry_after_seconds },
                crate::hub_connection::HubSignInOutcome::Minted(result) => result,
            };
            let Ok(credential) = LocalHubCredential::from_minted_session(&origin, &result.token) else {
                return ShellHubSignInAnswer::Failed { code: HubSignInErrorCode::InvalidResponse, retry_after_seconds: None };
            };
            let credential = std::sync::Arc::new(credential);
            let client = std::sync::Arc::new(DirectoryClient::authenticated(transport, credential.clone()));
            match client.me(&ctx).await {
                Ok(authority) if authority.user_id == result.user_id => ShellHubSignInAnswer::Verified { origin, user_id: result.user_id, credential, client, authority },
                Ok(_) | Err(_) => ShellHubSignInAnswer::Unverified,
            }
        }));
    }

    /// 🔐️ Applies one sign-in answer: a verified session owns the directory client, the socket grants and the book's
    /// last user, then the spaces read starts on its own task; a session verified for a hub no longer selected is
    /// dropped; anything else is the session's localized error.
    fn apply_hub_sign_in(&mut self, answer: ShellHubSignInAnswer) {
        match answer {
            ShellHubSignInAnswer::Failed { code, retry_after_seconds } => {
                self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::Failed { code, retry_after_seconds });
            }
            ShellHubSignInAnswer::Verified { origin, user_id, credential, client, authority } if origin == self.hub_workspace.origin() => {
                self.identity = Some(Identity { user_id: authority.user_id.clone(), email: authority.email.clone(), display_name: authority.display_name.clone(), hub_base_url: origin, issued_at_ms: chrome_now_ms() as i64 });
                self.verified_session_authority = Some(authority);
                self.directory_client = Some(client.clone());
                self.document_host.set_local_hub_credential(credential);
                self.document_host.set_hub_socket_grant_source(client);
                let selected_id = self.hub_workspace.book.selected_id.clone();
                if let Some(connection) = self.hub_workspace.book.connections.iter_mut().find(|connection| connection.id == selected_id) {
                    connection.last_user_id = Some(user_id);
                }
                self.persist_hub_connection_book();
                self.project_verified_hub_authority();
                self.start_hub_spaces_reload();
            }
            ShellHubSignInAnswer::Verified { .. } => {}
            ShellHubSignInAnswer::Unverified => {
                self.clear_hub_session_owner();
                self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::Failed { code: HubSignInErrorCode::InvalidResponse, retry_after_seconds: None });
            }
        }
    }

    /// 🚪️ Sign-out. The in-memory capability is dropped whatever the hub answers, so an unreachable
    /// hub can never trap a human in a session they asked to leave.
    async fn run_hub_sign_out_turn(&mut self) {
        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::SignOut);
        if let Some(client) = self.directory_client.clone() {
            let _ = client.sign_out(&self.directory_command_ctx()).await;
        }
        self.clear_hub_session_owner();
        self.hub_workspace.rows.clear();
        self.hub_workspace.members.clear();
        self.hub_workspace.open_space_id = None;
        self.hub_workspace.session = reduce_hub_session(&self.hub_workspace.session, &HubSessionEvent::SignedOut);
    }

    /// 🎟️ One invitation, issued as a sealed `create-invite` command and read back from that
    /// command's OWN receipt — the only place the one-shot capability ever appears.
    async fn run_hub_create_invite_turn(&mut self, space_id: &str) {
        let Some(command) = crate::space_browser::create_invite_command(space_id, DirectorySpaceRole::Spectator, crate::space_browser::INVITE_TTL_CHOICES_SECS_V1[1]) else { return };
        if self.identity.is_none() || self.directory_client.is_none() {
            return;
        }
        let request = DirectoryCommandRequestV1::new(mint_directory_command_request_id(), command);
        let request_id = request.request_id.clone();
        self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Submitting;
        self.directory_commands.admit_first(request);
        self.flush_pending_directory_commands().await;
        match self.directory_commands.result(&request_id) {
            Some(ShellDirectoryCommandResultV1::Receipt(receipt)) => {
                self.hub_workspace.invite_capability = match &receipt.result {
                    DirectoryCommandResultV1::Invite { invite_token } => Some(invite_token.clone()),
                    DirectoryCommandResultV1::None => None,
                };
                self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Ready;
            }
            Some(ShellDirectoryCommandResultV1::Failed(_)) | None => self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Failed,
        }
    }

    /// 🎟️ Redeems the pasted capability against the selected hub, then reloads the list — a
    /// redemption that changed nothing visible would leave the human guessing.
    async fn run_hub_redeem_turn(&mut self) {
        let Some(token) = crate::space_browser::parse_invite_token(&self.hub_workspace.invite_draft) else {
            self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::InvalidInvite);
            return;
        };
        let Some(client) = self.directory_client.clone() else {
            self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::Unauthorized);
            return;
        };
        match client.redeem_invite(&self.directory_command_ctx(), &token).await {
            Ok(()) => {
                self.hub_workspace.redemption_error = None;
                self.hub_workspace.invite_draft.clear();
                self.start_hub_spaces_reload();
            }
            Err(DirectoryClientError::Unauthorized) => self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::Unauthorized),
            Err(DirectoryClientError::Http { status, .. }) => self.hub_workspace.redemption_error = Some(crate::space_browser::invite_redemption_error_from_status(status)),
            Err(DirectoryClientError::Cancelled | DirectoryClientError::Transport(semio_framework_os_kernel::os_directory::client::TransportError::Cancelled)) => {
                self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::Cancelled)
            }
            Err(DirectoryClientError::Decode(_)) => self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::InvalidInvite),
            Err(_) => self.hub_workspace.redemption_error = Some(crate::space_browser::InviteRedemptionErrorCode::Unreachable),
        }
    }

    /// 🏘️ Reloads the space list through the shell's own directory client. A hub that stops
    /// answering leaves the rows on screen and moves the phase to `Stale` rather than emptying a
    /// list the human was reading.
    /// 🏘️ Arms one spaces read on a [`ShellHubTask`] (a replaced read is cancelled); the list shows `Loading` and keeps
    /// the rows it had, which is the local-first rule the `Stale` phase already defends.
    fn start_hub_spaces_reload(&mut self) {
        if let Some(task) = self.hub_spaces_task.take() {
            task.cancel();
        }
        let Some(client) = self.directory_client.clone() else {
            self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Stale;
            return;
        };
        self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Loading;
        let ctx = self.directory_ctx();
        let cancel = ctx.cancel.clone();
        self.hub_spaces_task = Some(ShellHubTask::spawn(cancel, async move { client.spaces(&ctx).await.map(|entries| crate::space_browser::space_rows(&entries)).map_err(|_| ()) }));
    }

    /// 📬️ Reads the answers of the hub workspace's spawned requests, once each; answers whether the workspace changed.
    fn poll_hub_workspace_tasks(&mut self) -> bool {
        let mut changed = false;
        if let Some(answer) = self.hub_sign_in_task.as_ref().and_then(ShellHubTask::answer) {
            self.hub_sign_in_task = None;
            self.apply_hub_sign_in(answer.unwrap_or(ShellHubSignInAnswer::Failed { code: HubSignInErrorCode::Unreachable, retry_after_seconds: None }));
            changed = true;
        }
        if let Some(answer) = self.hub_spaces_task.as_ref().and_then(ShellHubTask::answer) {
            self.hub_spaces_task = None;
            match answer.and_then(|rows| rows) {
                Ok(rows) => {
                    self.hub_workspace.rows = rows;
                    self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Ready;
                }
                Err(()) => self.hub_workspace.phase = crate::space_browser::SpaceBrowserPhase::Stale,
            }
            changed = true;
        }
        changed
    }

    /// 🔐️ Whether no hub workspace request is in flight.
    pub(crate) fn hub_workspace_settled(&self) -> bool {
        self.hub_sign_in_task.is_none() && self.hub_spaces_task.is_none()
    }

    /// 👥️ The open space's roster, joined with the hub identities this shell's presence lane sees.
    /// A public page carries no roster at all, which is an EMPTY roster and never an error.
    async fn reload_hub_members(&mut self, space_id: &str) {
        if space_id.is_empty() {
            self.hub_workspace.members.clear();
            return;
        }
        let Some(client) = self.directory_client.clone() else { return };
        let Ok(page) = client.space_administration_page(&self.directory_ctx(), space_id, None).await else {
            self.hub_workspace.members.clear();
            return;
        };
        let rows = match page.page() {
            DirectorySpaceAdministrationPageV1::Member { members, .. } | DirectorySpaceAdministrationPageV1::Author { members, .. } => members.rows.clone(),
            DirectorySpaceAdministrationPageV1::Public { .. } => Vec::new(),
        };
        self.hub_workspace.members = crate::space_browser::space_member_presence(&rows, &self.hub_online_user_ids());
    }

    /// 👥️ The hub identities the presence lane currently sees. A peer with no hub identity
    /// contributes nothing, so the roster can never show a member the directory does not know.
    fn hub_online_user_ids(&self) -> Vec<String> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let mut ids: Vec<String> = self.presence_peers.iter().filter_map(|peer| peer.user_id.clone()).collect();
            ids.sort_unstable();
            ids.dedup();
            return ids;
        }
        #[cfg(target_arch = "wasm32")]
        Vec::new()
    }
    //#endregion 🔐️HubWorkspaceLane

    //#region 💡️InferencePort
    /// 📦 Replaces the executable's finite installed owner inventory and retires prior work.
    #[cfg(not(target_arch = "wasm32"))]
    pub fn install_document_services(&mut self, services: Vec<InstalledServiceContributionV1>) {
        self.cancel_inference_port();
        if services.len()>64 || services.iter().enumerate().any(|(index,entry)|services[..index].iter().any(|prior|prior.owner==entry.owner && prior.service_id==entry.service_id)) {self.document_services.clear();return;}
        self.document_services=services;
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn installed_document_http_port(&self, owner:&str, service_id:&str) -> Option<CompiledDocumentHttpPortV1> {
        let mut found=None;
        for plugin in &self.plugins {
            if plugin.plugin_id!=owner {continue;}
            for contribution in &plugin.manifest.topic_contributions {
                if contribution.topic!=DOCUMENT_HTTP_PORT_TOPIC {continue;}
                let declaration=DocumentHttpPortDeclarationV1::from_value(contribution.payload.clone()).ok()?;
                if declaration.service_id!=service_id || declaration.owner!=owner {continue;}
                if found.is_some() {return None;}
                found=Some(CompiledDocumentHttpPortV1::compile(owner,declaration).ok()?);
            }
        }
        found
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn open_service_port(&mut self, owner:&str,service_id:&str,action:&str,payload:DslValue) {
        if self.session.as_ref().map(|session|session.plugin_id.as_str())!=Some(owner) {return;}
        if let Some(runner)=self.inference_port.as_ref().filter(|runner|runner.owner==owner && runner.service_id==service_id) {
            runner.intend(action,payload);
            return;
        }
        self.cancel_inference_port();
        let Some(lease)=self.document_execution_target_lease.as_ref() else {return};
        if lease.package.plugin_id!=owner {return;}
        let Some(space_id)=self.open_space_id.clone() else {return};
        let Some(document_id)=self.sync_channel.as_ref().map(|channel|channel.document_id.clone()) else {return};
        let scope=DocumentScope {space_id,document_id};
        if lease.scope!=scope {return;}
        let mut matches=self.document_services.iter().filter(|entry|entry.owner==owner && entry.service_id==service_id);
        let Some(contribution)=matches.next().copied() else {return};
        if matches.next().is_some() {return;}
        let Some(port)=self.installed_document_http_port(owner,service_id) else {return};
        let Some(client)=self.directory_client.clone().filter(|_|self.identity.is_some()) else {return};
        let mut driver=(contribution.create)(scope.clone(),true);
        if driver.intend(action,payload).is_err() {return;}
        self.inference_port_status=Some(InstalledServiceStatusV1 {owner:owner.into(),service_id:service_id.into(),payload:driver.status()});
        self.inference_port=Some(ShellInferenceRunner::start(crate::renderer_worker_pool(),client,std::sync::Arc::new(port),self.directory_ctx(),contribution,scope,driver));
    }

    /// 🔄️ One bounded drain per frame; the runner never spins and never blocks the render loop.
    #[cfg(not(target_arch = "wasm32"))]
    fn pump_inference_port(&mut self) -> bool {
        let Some(runner) = self.inference_port.clone() else { return false };
        let statuses = runner.drain();
        let Some(latest) = statuses.into_iter().next_back() else { return false };
        let terminal = runner.driver.lock().expect("service driver mutex poisoned").terminal();
        self.inference_port_status = Some(latest);
        if terminal {
            runner.cancel();
            self.inference_port = None;
        }
        true
    }

    /// 🎬 Delivers a scoped action only to the retained installed owner.
    #[cfg(not(target_arch = "wasm32"))]
    pub fn intend_document_service(&mut self,owner:&str,service_id:&str,action:&str,payload:DslValue) {
        if let Some(runner)=self.inference_port.as_ref().filter(|runner|runner.owner==owner && runner.service_id==service_id) {
            runner.intend(action,payload);
        }
    }

    /// 🛑️ Hard terminal: cancels every in-flight call and retires the runner.
    #[cfg(not(target_arch = "wasm32"))]
    fn cancel_inference_port(&mut self) {
        self.inference_port_status=None;
        if let Some(runner) = self.inference_port.take() {
            runner.cancel();
        }
    }
    //#endregion 💡️InferencePort

    /// 📂️ Opens the relay's exact `documentId`/`schema` pair with `spaceId` pinning
    /// `open_space_id` first so default binding computation sees it. An app-only relay is a no-op.
    ///
    /// 🌐️ One body on both targets: resolving the owner of an artifact kind, installing it on demand
    /// (O2's `install_plugin`, whose progress + cancel band the chrome paints), switching the
    /// session to its app and binding that session to its document on the shell's `ArtifactHost`.
    /// A document the host cannot serve is refused out loud (`open-artifact.document-failed`), never
    /// dropped: the caller's `documentId` either binds or explains itself.
    ///
    /// 🎬️ The relay used to open every artifact inside whatever session happened to be mounted, so
    /// a hub that was showing `home` opened a cad document into `home`. The target's own app ref —
    /// or, when the caller has none, the kind's declared owner — decides the session, and the owner
    /// is installed on demand exactly as React's `openArtifactWithAppRef` installs it.
    async fn handle_open_artifact_relay(&mut self, action_id: &str, args: Option<&Value>) {
        let target = match open_artifact_relay_target(action_id, args) {
            Ok(target) => target,
            Err(error) => {
                Self::debug_log(&format!("[TRACE] wgpu shell os.open-artifact relay rejected: {error}"));
                return;
            }
        };
        if self.document_opening.as_ref().is_some_and(ShellDocumentOpening::running) {
            let is_de = self.locale_id == "de";
            self.show_transient_notice(shell_chrome_string("document.open.busy", is_de), semio_framework::Severity::Info, Some("document.open.busy"));
            return;
        }
        if let Some(space_id) = target.space_id.clone() {
            self.open_space_id = Some(space_id);
        }
        #[cfg(not(target_arch = "wasm32"))]
        if self.begin_document_resolution(&target) {
            return;
        }
        let switch = match (&target.plugin_id, &target.app_id) {
            (Some(plugin_id), Some(app_id)) => match self.install_plugin(plugin_id).await {
                Err(error) => {
                    Self::debug_log(&format!("[TRACE] wgpu shell os.open-artifact could not install {plugin_id}: {error}"));
                    None
                }
                Ok(()) => self.plugins.iter().find(|entry| entry.plugin_id == *plugin_id).and_then(|program| program.manifest.apps.iter().find(|app| app.id == *app_id).cloned()).map(|app| (plugin_id.clone(), app)),
            },
            _ => self.resolve_activation_owner_app(&target.dialect, target.role).await,
        };
        let document = match (target.document_id, target.schema) {
            (Some(document_id), Some(schema)) => Some(ShellDocumentOpenTarget { document_id, schema, checkpoint: None }),
            _ => None,
        };
        match switch {
            Some((plugin_id, app)) if !self.session.as_ref().is_some_and(|session| session.plugin_id == plugin_id && session.app.id == app.id) => {
                let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == plugin_id).cloned() else {
                    Self::debug_log(&format!("[TRACE] wgpu shell os.open-artifact could not switch to {plugin_id}: program missing"));
                    return;
                };
                let label = app.label.resolve(self.active_terminology(), self.active_locale()).to_string();
                let app_id = app.id.clone();
                let pending = ShellDetached::spawn(async move { program.create_app(&app_id).await.map(ShellDocumentOpenAnswer::Instantiated) });
                self.document_opening = Some(ShellDocumentOpening::new(label, ShellDocumentOpenPhase::Instantiating, plugin_id, app.id, document, Some(pending)));
            }
            _ => {
                if let Some(document) = document {
                    self.begin_document_seed(document).await;
                }
            }
        }
    }

    /// 🌱️ Starts the document half of an open in the mounted session: the host half is prepared on
    /// this turn, and the guest's genesis load runs detached; [`Self::advance_document_opening`] binds the
    /// document once it answers. A preparation that fails settles the open as failed.
    async fn begin_document_seed(&mut self, document: ShellDocumentOpenTarget) {
        let Some(session) = self.session.clone() else {
            self.fail_document_opening("document open has no mounted session".to_string());
            return;
        };
        let label = session.app.label.resolve(self.active_terminology(), self.active_locale()).to_string();
        let opening = self.document_opening.take();
        let (bindings, surface) = self.default_bindings_for_current_session();
        let prepared = match self.prepare_document_open(document.document_id, document.schema, bindings, surface, None, document.checkpoint).await {
            Ok(prepared) => prepared,
            Err(error) => {
                self.document_opening = opening;
                self.fail_document_opening(error);
                return;
            }
        };
        let seed_cancel = prepared.seed.as_ref().map(|seed| seed.ctx.cancel.clone());
        let pending = ShellDetached::spawn({
            let (plugin, instance_id, seed) = (prepared.plugin.clone(), prepared.session.instance_id, prepared.seed.clone());
            async move { seed_hub_document(plugin, instance_id, seed).await.map(ShellDocumentOpenAnswer::Seeded) }
        });
        let mut opening = opening.unwrap_or_else(|| ShellDocumentOpening::new(label, ShellDocumentOpenPhase::Seeding, session.plugin_id.clone(), session.app.id.clone(), None, None));
        opening.phase = ShellDocumentOpenPhase::Seeding;
        opening.cancel = seed_cancel;
        opening.pending = Some(pending);
        opening.prepared = Some(prepared);
        self.document_opening = Some(opening);
    }

    /// 🧩️ Starts a hub document's open by resolving the component it runs by the SERVING catalog
    /// generation (binding decision of ticket 26/09/23, session 11 13:1x; React resolves the same generation
    /// through the hub's plugin-module routes): the local program only when its content hash is the lease's,
    /// else the verified store entry, else the hub's own execution-target bytes, verified and stored
    /// ([`DirectoryClient::resolve_execution_target_module`]) — all detached, with a cancellable band.
    /// The lease names the plugin and app that open the document, so a relay that names none (the creation
    /// door's, a Space index row's) resolves exactly like one that does. Answers `false` for a relay that names
    /// no hub document, which opens as before.
    #[cfg(not(target_arch = "wasm32"))]
    fn begin_document_resolution(&mut self, target: &OpenArtifactRelayTarget) -> bool {
        let (Some(document_id), Some(schema), Some(space_id), Some(client)) = (target.document_id.clone(), target.schema.clone(), self.open_space_id.clone(), self.directory_client.clone()) else {
            return false;
        };
        let local_app = target.app_id.as_ref().and_then(|app_id| self.plugins.iter().flat_map(|program| program.manifest.apps.iter()).find(|app| app.id == *app_id).cloned());
        let surface_id = local_app.as_ref().map_or_else(|| semio_framework::manifest::surface_app_id(&target.dialect, target.role), |app| semio_framework::manifest::surface_app_id(&app.dialect, app.role));
        let label = local_app.map_or_else(|| target.app_id.clone().unwrap_or_else(|| target.artifact_ref.clone()), |app| app.label.resolve(self.active_terminology(), self.active_locale()).to_string());
        let local_shas: Vec<(String, Option<String>)> = self.plugins.iter().map(|program| (program.plugin_id.clone(), program.component_sha256.clone())).collect();
        let intent = semio_framework_os_kernel::os_directory::DocumentOpenIntentV1 {
            schema: "semio.hub.document-open-intent/v1".into(),
            version: 1,
            scope: semio_framework_os_kernel::os_directory::DocumentScope::new(space_id.as_str(), document_id.as_str()),
            requested_surface_id: Some(surface_id),
            client_instance_id: format!("wgpu-shell-{}", self.shell_session_id),
        };
        let ctx = self.directory_ctx();
        let cancel = ctx.cancel.clone();
        let resolve_step = std::sync::Arc::new(std::sync::atomic::AtomicU8::new(0));
        let reported = resolve_step.clone();
        let expected_plugin = target.plugin_id.clone();
        let pending = ShellDetached::spawn(async move {
            let store = semio_framework_os_kernel::os_directory::client::ExecutionTargetModuleStore::for_user();
            reported.store(document_open_resolve_step_code(semio_framework_os_kernel::os_directory::client::ExecutionTargetModuleStep::Lease), std::sync::atomic::Ordering::Release);
            let lease = client.document_execution_target_lease(&ctx, &intent).await.map_err(|error| format!("document execution target: {error}"))?;
            let plugin_id = lease.package.plugin_id.clone();
            if expected_plugin.as_ref().is_some_and(|expected| *expected != plugin_id) {
                return Err(format!("the hub opens this document with {plugin_id}, not {}", expected_plugin.unwrap_or_default()));
            }
            let local_sha = local_shas.into_iter().find(|(local, _)| *local == plugin_id).and_then(|(_, sha)| sha);
            let resolved = client
                .resolve_execution_target_files(&ctx, &intent, lease, local_sha.as_deref(), &store, |step| reported.store(document_open_resolve_step_code(step), std::sync::atomic::Ordering::Release))
                .await
                .map_err(|error| format!("document execution target: {error}"))?;
            let app_id = resolved.lease.surface.app_id.clone();
            let program = match resolved.files {
                Some(files) => Some(crate::program_bridge::load_resolved_program(&plugin_id, &files.component, &files.descriptor, &resolved.lease.component.sha256).await?),
                None => None,
            };
            Ok(ShellDocumentOpenAnswer::Resolved { plugin_id, app_id, program, checkpoint: resolved.lease.checkpoint.clone() })
        });
        let mut opening = ShellDocumentOpening::new(
            label,
            ShellDocumentOpenPhase::Resolving,
            target.plugin_id.clone().unwrap_or_default(),
            target.app_id.clone().unwrap_or_default(),
            Some(ShellDocumentOpenTarget { document_id, schema, checkpoint: None }),
            Some(pending),
        );
        opening.cancel = Some(cancel);
        opening.resolve_step = resolve_step;
        self.document_opening = Some(opening);
        true
    }

    /// 🧩️ Continues a resolved hub open: a hub-resolved program replaces the local one of its plugin (a local
    /// program no longer mounts a hub document it is not the lease's component for), then the app instance
    /// is created on it; a local program that already is the lease's component seeds the document into the
    /// mounted session when it runs the app already.
    #[cfg(not(target_arch = "wasm32"))]
    async fn continue_resolved_open(&mut self, mut opening: ShellDocumentOpening, resolved: Option<ProgramBridgeEntry>) {
        let fresh = resolved.is_some();
        if let Some(program) = resolved {
            self.plugins.retain(|entry| entry.plugin_id != program.plugin_id);
            self.plugins.push(program);
        }
        let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == opening.plugin_id).cloned() else {
            self.document_opening = Some(opening);
            self.fail_document_opening("the resolved plugin is not mounted".to_string());
            return;
        };
        let Some(app) = program.manifest.apps.iter().find(|app| app.id == opening.app_id).cloned() else {
            let reason = format!("{} declares no app {}", program.plugin_id, opening.app_id);
            self.document_opening = Some(opening);
            self.fail_document_opening(reason);
            return;
        };
        opening.label = app.label.resolve(self.active_terminology(), self.active_locale()).to_string();
        if !fresh && self.session.as_ref().is_some_and(|session| session.plugin_id == program.plugin_id && session.app.id == app.id) {
            let document = opening.document.take();
            self.document_opening = Some(opening);
            if let Some(document) = document {
                self.begin_document_seed(document).await;
            }
            return;
        }
        let app_id = app.id.clone();
        opening.pending = Some(ShellDetached::spawn(async move { program.create_app(&app_id).await.map(ShellDocumentOpenAnswer::Instantiated) }));
        opening.phase = ShellDocumentOpenPhase::Instantiating;
        self.document_opening = Some(opening);
    }

    /// ⏭️ Advances the retained open by the one detached step that answered, if any: an instance mounts
    /// as the session (or is destroyed when the open was cancelled), a seeded document binds, and every
    /// render the open owes goes to the settle lane. Called once per frame from [`Self::pump_sync_events`];
    /// answers whether the open moved.
    async fn advance_document_opening(&mut self) -> bool {
        let Some(answer) = self.document_opening.as_ref().and_then(|opening| opening.pending.as_ref()).and_then(ShellDetached::take) else { return false };
        let Some(mut opening) = self.document_opening.take() else { return false };
        opening.pending = None;
        match answer {
            #[cfg(not(target_arch = "wasm32"))]
            Ok(ShellDocumentOpenAnswer::Resolved { plugin_id, app_id, program, checkpoint }) => {
                if opening.cancel_requested {
                    opening.phase = ShellDocumentOpenPhase::Cancelled;
                    self.document_opening = Some(opening);
                    return true;
                }
                opening.plugin_id = plugin_id;
                opening.app_id = app_id;
                if let Some(document) = opening.document.as_mut() {
                    document.checkpoint = Some(checkpoint);
                }
                self.continue_resolved_open(opening, program).await;
            }
            Ok(ShellDocumentOpenAnswer::Instantiated(instance_id)) => {
                if opening.cancel_requested {
                    if let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == opening.plugin_id) {
                        program.destroy_app(instance_id);
                    }
                    opening.phase = ShellDocumentOpenPhase::Cancelled;
                    self.document_opening = Some(opening);
                    return true;
                }
                let Some(app) = self.plugins.iter().find(|entry| entry.plugin_id == opening.plugin_id).and_then(|program| program.manifest.apps.iter().find(|app| app.id == opening.app_id).cloned()) else {
                    self.document_opening = Some(opening);
                    self.fail_document_opening("the opened app left its plugin".to_string());
                    return true;
                };
                self.install_app_session(&opening.plugin_id, app, instance_id);
                self.owe_refresh(UiDirtyScope::Full);
                self.owe_settle();
                match opening.document.take() {
                    Some(document) => {
                        self.document_opening = Some(opening);
                        self.begin_document_seed(document).await;
                    }
                    None => self.document_opening = None,
                }
            }
            Ok(ShellDocumentOpenAnswer::Seeded(pair)) => {
                let Some(prepared) = opening.prepared.take() else {
                    self.document_opening = Some(opening);
                    self.fail_document_opening("seeded document open lost its prepared owner".to_string());
                    return true;
                };
                if opening.cancel_requested {
                    opening.phase = ShellDocumentOpenPhase::Cancelled;
                    self.document_opening = Some(opening);
                    return true;
                }
                if let Err(error) = self.install_document_seed(&prepared, pair) {
                    self.document_opening = Some(opening);
                    self.fail_document_opening(error);
                    return true;
                }
                match self.finish_document_open(prepared).await {
                    Ok(()) => {
                        self.owe_refresh(UiDirtyScope::Full);
                        self.owe_settle();
                    }
                    Err(error) => {
                        self.document_opening = Some(opening);
                        self.fail_document_opening(error);
                        return true;
                    }
                }
            }
            Err(_) if opening.cancel_requested => {
                opening.phase = ShellDocumentOpenPhase::Cancelled;
                self.document_opening = Some(opening);
            }
            Err(error) => {
                self.document_opening = Some(opening);
                self.fail_document_opening(error);
            }
        }
        true
    }

    /// 🛟️ Drives a rebootstrapping hub document back to Live — the same canonical-pair seed as its first open
    /// ([`seed_hub_document`]): the pair is fetched detached and admitted only as the actor's control's checkpoint, loaded into
    /// the guest, and handed to the actor ([`ArtifactActorMsg::Reseed`]), which then dials at once. A transient failure is asked
    /// again after [`SYNC_RESEED_RETRY_MS`] while the document stays open; closing the document drops the reseed. Answers
    /// whether the guest's document changed.
    async fn advance_sync_reseed(&mut self) -> bool {
        let Some(mut reseed) = self.sync_reseed.take() else { return false };
        let Some(owner) = self.sync_channel.as_ref().map(shell_sync_channel_owner) else { return false };
        match reseed.pending.as_ref().and_then(ShellDetached::take) {
            None if reseed.pending.is_some() => {
                self.sync_reseed = Some(reseed);
                false
            }
            None => {
                if chrome_now_ms() < reseed.retry_at_ms {
                    self.sync_reseed = Some(reseed);
                    return false;
                }
                let Some(client) = self.directory_client.clone() else {
                    reseed.retry_at_ms = chrome_now_ms() + SYNC_RESEED_RETRY_MS;
                    self.sync_reseed = Some(reseed);
                    return false;
                };
                let (ctx, control) = (self.directory_ctx(), reseed.control.clone());
                reseed.pending = Some(ShellDetached::spawn(async move { client.rebootstrap_canonical_checkpoint_pair(&ctx, &control).await.map_err(|error| format!("canonical checkpoint pair: {error}")) }));
                self.sync_reseed = Some(reseed);
                false
            }
            Some(Err(error)) => {
                Self::debug_log(&format!("[TRACE] wgpu shell rebootstrap reseed refused: {error}"));
                reseed.pending = None;
                reseed.retry_at_ms = chrome_now_ms() + SYNC_RESEED_RETRY_MS;
                self.sync_reseed = Some(reseed);
                false
            }
            Some(Ok(pair)) => {
                let Some(plugin) = self.plugins.iter().find(|entry| entry.plugin_id == owner.plugin_id).cloned() else { return false };
                if let Err(error) = plugin.load_app_document_pack(owner.instance_id, &pair.pack_bytes, &pair.spr_bytes).await {
                    Self::debug_log(&format!("[TRACE] wgpu shell rebootstrap reseed load failed: {error}"));
                    reseed.pending = None;
                    reseed.retry_at_ms = chrome_now_ms() + SYNC_RESEED_RETRY_MS;
                    self.sync_reseed = Some(reseed);
                    return false;
                }
                let message = ArtifactActorMsg::Reseed { pack: pair.pack_bytes, spr: pair.spr_bytes, baseline: pair.baseline_frontier };
                if let Some(channel) = self.sync_channel.as_ref() {
                    let _ = channel.cmd_tx.send(message);
                }
                self.owe_refresh(UiDirtyScope::Full);
                true
            }
        }
    }

    /// 🧯️ Settles the open as failed, out loud: its band keeps the reason and the notice names it.
    fn fail_document_opening(&mut self, error: String) {
        Self::debug_log(&format!("[TRACE] wgpu shell os.open-artifact relay failed: {error}"));
        let is_de = self.locale_id == "de";
        self.show_transient_notice(shell_chrome_string("open-artifact.document-failed", is_de), semio_framework::Severity::Warning, Some("open-artifact.document-failed"));
        if let Some(opening) = self.document_opening.as_mut() {
            opening.phase = ShellDocumentOpenPhase::Failed(error);
            opening.pending = None;
            opening.prepared = None;
        }
    }

    /// 🛑️ Cancels the open in flight, or clears a settled record. The phase moves only when the step in
    /// flight answers: an instance created after the cancel is destroyed, a seeded document never binds.
    pub fn cancel_document_opening(&mut self) {
        if self.document_opening.as_ref().is_some_and(|opening| !opening.running()) {
            self.document_opening = None;
            return;
        }
        if let Some(opening) = self.document_opening.as_mut() {
            opening.cancel_requested = true;
            if let Some(cancel) = opening.cancel.as_ref() {
                cancel.cancel_now();
            }
        }
    }

    /// 📔️ Live directory WS events reach the mounted Space index through `foldDirectoryEvents`
    /// (browser parity), so its membership stays projected. Home is never folded: its projection's
    /// only writer is the sealed page lane, which the same events wake through `home.wake` below.
    #[cfg(not(target_arch = "wasm32"))]
    fn dispatch_fold_directory_events(&mut self, events: &[semio_framework_os_kernel::os_directory::DirectoryEvent]) {
        let Some(session) = self.session.clone().filter(|session| session.app.dialect == space_index_dialect()) else { return };
        let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id).cloned() else { return };
        let events_json = semio_framework_pack_json::to_json_string(&events.to_vec());
        let live_view_state = self.live_view_state(&session);
        let window_kind_id = session.app.window_kinds.first().id.clone();
        let window_instance_id = live_view_state.window_id.clone().unwrap_or_else(|| window_kind_id.clone());
        let mode_id = live_view_state.active_mode_id.clone().unwrap_or_else(|| session.app.default_mode_id.clone());
        let invocation = semio_framework::manifest::ActionInvocation {
            address: semio_framework::manifest::ActionAddress { plugin_id: session.plugin_id.clone(), app_id: session.app.id.clone(), mode_id, window_kind_id, window_instance_id, action_id: "foldDirectoryEvents".into() },
            arguments: BTreeMap::from([("eventsJson".into(), DslValue::String(events_json))]),
        };
        let action_json = semio_framework_pack_json::to_json_string(&invocation);
        let pool = crate::renderer_worker_pool();
        let instance_id = session.instance_id;
        let _ = ShellPoolFuture::spawn(pool, Lane::Io, async move {
            let _ = program.handle_action(instance_id, &action_json, &live_view_state).await;
        });
    }

    /// 🏠️ Begins one bounded canonical-page fetch owned by the retained Home bootstrap epoch.
    #[cfg(not(target_arch = "wasm32"))]
    fn start_directory_event_page_fetch(&mut self) {
        if self.identity_offline {
            return;
        }
        let Some(client) = self.directory_client.clone() else { return };
        let pool = crate::renderer_worker_pool();
        let now_ms = pool.now_ms();
        let Some((epoch, after)) = self
            .directory_home
            .as_ref()
            .and_then(|home| (!home.closed && home.page_task.is_none() && home.home_task.is_none() && home.stream.is_none() && now_ms >= home.retry_at_ms).then_some((home.bootstrap.bootstrap_epoch(), home.bootstrap.after())))
        else {
            return;
        };
        let mut context = self.directory_ctx();
        context.deadline_ms = Some(now_ms.saturating_add(5_000));
        let cancel = context.cancel.clone();
        let (tx, rx) = std::sync::mpsc::channel();
        let task = ShellPoolFuture::spawn(pool, Lane::Io, async move {
            let result = client.event_page(&context, after).await;
            let _ = tx.send((epoch, result));
        });
        if let Some(home) = self.directory_home.as_mut().filter(|home| home.bootstrap.bootstrap_epoch() == epoch && !home.closed) {
            home.page_cancel = Some(cancel);
            home.page_rx = Some(rx);
            home.page_task = Some(task);
        } else {
            cancel.cancel_now();
            task.cancel();
        }
    }

    /// 🧾️ Invokes the stored Home instance and accepts only its terminal Config publication receipt.
    #[cfg(not(target_arch = "wasm32"))]
    fn start_directory_home_publication(&mut self, page: CanonicalDirectoryEventPageV1) -> Result<(), String> {
        let canonical_json = page.canonical_json().to_string();
        let session_identity = self.identity.as_ref().map(|identity| ViewSessionIdentity { user_id: identity.user_id.clone(), display_name: identity.display_name.clone() });
        let (epoch, instance_id, program, app, view_state, expected) = {
            let home = self.directory_home.as_mut().ok_or("retained Home projection is unavailable")?;
            let expected = home.bootstrap.present(page).map_err(|error| error.to_string())?;
            let mut view_state = self.session.as_ref().filter(|session| home.is_instance(&session.plugin_id, session.instance_id)).map(|session| session.view_state.clone()).unwrap_or_else(|| home.view_state.clone());
            view_state.session_identity = session_identity;
            let program = self.plugins.iter().find(|entry| entry.plugin_id == home.plugin_id).cloned().ok_or("retained Home program is unavailable")?;
            (home.bootstrap.bootstrap_epoch(), home.instance_id, program, home.app.clone(), view_state, expected)
        };
        let window_kind_id = app.window_kinds.first().id.clone();
        let window_instance_id = view_state.window_id.clone().unwrap_or_else(|| window_kind_id.clone());
        let invocation = semio_framework::manifest::ActionInvocation {
            address: semio_framework::manifest::ActionAddress {
                plugin_id: program.plugin_id.clone(),
                app_id: app.id.clone(),
                mode_id: view_state.active_mode_id.clone().unwrap_or_else(|| app.default_mode_id.clone()),
                window_kind_id,
                window_instance_id,
                action_id: "applyDirectoryEventPage".into(),
            },
            arguments: BTreeMap::from([("pageJson".into(), DslValue::String(canonical_json))]),
        };
        let action_json = semio_framework_pack_json::to_json_string(&invocation);
        let (tx, rx) = std::sync::mpsc::channel();
        let expected_for_task = expected.clone();
        let pool = crate::renderer_worker_pool();
        let task = ShellPoolFuture::spawn(pool, Lane::Io, async move {
            let outcome = match program.handle_action(instance_id, &action_json, &view_state).await {
                Err(error) => ShellDirectoryHomePublicationOutcome::Rejected(error),
                Ok(result) => match terminal_directory_home_ack(&result, epoch) {
                    Ok(actual) if actual == expected_for_task => ShellDirectoryHomePublicationOutcome::Published(actual),
                    Ok(_) => ShellDirectoryHomePublicationOutcome::Terminal("retained Home directory acknowledgement does not match the pending page".into()),
                    Err(error) => ShellDirectoryHomePublicationOutcome::Terminal(error),
                },
            };
            let _ = tx.send((epoch, instance_id, expected_for_task, outcome));
        });
        let home = self.directory_home.as_mut().ok_or("retained Home projection retired before publication admission")?;
        if home.bootstrap.bootstrap_epoch() != epoch || home.instance_id != instance_id || home.closed {
            task.cancel();
            return Err("retained Home projection changed before publication admission".into());
        }
        home.home_rx = Some(rx);
        home.home_task = Some(task);
        Ok(())
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn poll_directory_page_result(&mut self) -> Option<ShellDirectoryPageResult> {
        let home = self.directory_home.as_mut()?;
        let result = match home.page_rx.as_ref()?.try_recv() {
            Ok(result) => Some(result),
            Err(std::sync::mpsc::TryRecvError::Empty) => None,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => Some((home.bootstrap.bootstrap_epoch(), Err(DirectoryClientError::Transport(TransportError::Io("directory page task disconnected".into()))))),
        }?;
        home.page_rx.take();
        home.page_cancel.take();
        home.page_task.take();
        Some(result)
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn poll_directory_home_publication(&mut self) -> Option<ShellDirectoryHomePublicationResult> {
        let home = self.directory_home.as_mut()?;
        let result = match home.home_rx.as_ref()?.try_recv() {
            Ok(result) => Some(result),
            Err(std::sync::mpsc::TryRecvError::Empty) => None,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => Some((
                home.bootstrap.bootstrap_epoch(),
                home.instance_id,
                DirectoryEventPageAckV1 { bootstrap_epoch: home.bootstrap.bootstrap_epoch(), session_binding_sha256: String::new(), authorization_generation: 0, through_seq_inclusive: home.bootstrap.after(), receipt_sha256: String::new() },
                ShellDirectoryHomePublicationOutcome::Terminal("retained Home publication task disconnected".into()),
            )),
        }?;
        home.home_rx.take();
        home.home_task.take();
        Some(result)
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn open_acknowledged_directory_stream(&mut self, since: u64) -> Result<(), String> {
        let client = self.directory_client.clone().ok_or("directory client is unavailable")?;
        let stream = client.stream_acknowledged(since).map_err(|error| error.to_string())?;
        let context = self.directory_ctx();
        let runner = ShellDirectoryRunner::start(crate::renderer_worker_pool(), stream, context);
        let home = self.directory_home.as_mut().ok_or("retained Home projection is unavailable")?;
        if home.closed || home.stream.is_some() {
            runner.cancel();
            return Err("retained Home stream admission raced with retirement".into());
        }
        home.stream = Some(runner);
        Ok(())
    }

    /// 🪪️ Starts deadline-aware identity bootstrap as a retained-waker I/O-lane future. Each pool
    /// turn polls once; the HTTP boundary itself is admitted on `Lane::Io`, and the UI only polls
    /// this result channel. No worker waits for the network future and no local executor is built.
    #[cfg(not(target_arch = "wasm32"))]
    fn bootstrap_identity(&mut self) {
        let Some(env) = resolve_identity_env() else { return };
        self.identity_env = Some(env.clone());
        let (tx, rx) = std::sync::mpsc::channel::<Result<IdentityOutcome, String>>();
        let transport = self.directory_transport.clone();
        let pool = crate::renderer_worker_pool();
        let mut ctx = self.directory_ctx();
        ctx.deadline_ms = Some(pool.now_ms().saturating_add(5_000));
        self.identity_bootstrap_task = Some(ShellPoolFuture::spawn(pool, Lane::Io, async move {
            let outcome = restore_claimed(&ctx, transport, "native").await.map_err(|error| error.to_string());
            let _ = tx.send(outcome);
        }));
        self.identity_bootstrap_rx = Some(rx);
    }

    /// 🪪️ Drains `identity_bootstrap_rx` and starts a fresh zero-frontier retained-Home epoch.
    #[cfg(not(target_arch = "wasm32"))]
    fn poll_identity_bootstrap(&mut self) {
        let Some(rx) = self.identity_bootstrap_rx.as_ref() else { return };
        match rx.try_recv() {
            Ok(Ok(outcome)) => {
                self.identity_bootstrap_task.take();
                self.identity_offline = outcome.status == IdentityStatus::Offline;
                self.identity = Some(outcome.identity.clone());
                self.verified_session_authority = Some(outcome.authority);
                let client = std::sync::Arc::new(DirectoryClient::authenticated(self.directory_transport.clone(), outcome.credential.clone()));
                self.document_host.set_local_hub_credential(outcome.credential);
                self.document_host.set_hub_socket_grant_source(client.clone());
                self.directory_client = Some(client);
                self.project_verified_hub_authority();
                if let Some(home) = self.directory_home.as_mut() {
                    if let Err(error) = home.begin_epoch(0) {
                        home.close();
                        self.error = Some(error.to_string());
                    }
                }
                self.identity_bootstrap_rx = None;
            }
            Ok(Err(error)) => {
                self.identity_bootstrap_task.take();
                Self::debug_log(&format!("[TRACE] wgpu shell identity bootstrap failed: {error}"));
                self.identity_bootstrap_rx = None;
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.identity_bootstrap_task.take();
                self.identity_bootstrap_rx = None;
            }
        }
    }

    /// 📡️ Advances the finite fetch → terminal Home receipt → exact ACK → acknowledged-live owner.
    ///
    /// 🌉️ Packet W15e: the agent bridge's socket rides the SAME frame pump as the directory lane.
    ///
    /// 🏛️ One bounded administration turn per frame: the retained operation never spins, because
    /// `pump_space_administration` answers `false` the moment it reaches `Idle` or a terminal phase.
    #[cfg(not(target_arch = "wasm32"))]
    async fn pump_directory_events(&mut self) -> bool {
        self.poll_identity_bootstrap();
        let inference_changed = self.pump_inference_port();
        let bridge_changed = self.pump_agent_bridge();
        let mut changed = self.pump_space_administration().await || inference_changed || bridge_changed;
        changed |= self.pump_hub_artifact_creation().await;
        changed |= self.pump_hub_check_in().await;
        self.pump_agent_bridge_offer_scope().await;
        changed |= self.poll_hub_workspace_tasks();
        let runner = self.directory_home.as_ref().and_then(|home| home.stream.clone());
        if let Some(runner) = runner {
            if runner.take_terminal() {
                if let Some(home) = self.directory_home.as_mut() {
                    let _ = home.begin_epoch(0);
                }
                self.directory_client = None;
                #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.identity = None;
                self.verified_session_authority = None;
                self.bootstrap_identity();
                changed = true;
            }
            let mut dirty = false;
            let mut rebootstrap = false;
            let mut live_events: Vec<semio_framework_os_kernel::os_directory::DirectoryEvent> = Vec::new();
            for message in runner.drain() {
                match message {
                    DirectoryStreamMessage::Event { event } => {
                        live_events.push(event.as_ref().clone());
                        dirty = true;
                    }
                    DirectoryStreamMessage::Heartbeat { .. } => dirty = true,
                    DirectoryStreamMessage::Connection { .. } | DirectoryStreamMessage::Presence { .. } => {}
                    DirectoryStreamMessage::RebootstrapRequired { .. } | DirectoryStreamMessage::AccessChanged { .. } => rebootstrap = true,
                }
            }
            if !live_events.is_empty() {
                self.dispatch_fold_directory_events(&live_events);
                changed = true;
            }
            if dirty || rebootstrap {
                if let Some(home) = self.directory_home.as_mut() {
                    match home.wake(rebootstrap) {
                        Ok(Some(_)) => changed = true,
                        Ok(None) => {}
                        Err(error) => {
                            home.close();
                            self.error = Some(error.to_string());
                        }
                    }
                }
            }
        }

        if let Some((epoch, result)) = self.poll_directory_page_result() {
            let current = self.directory_home.as_ref().is_some_and(|home| !home.closed && home.bootstrap.bootstrap_epoch() == epoch);
            if current {
                match result {
                    Ok(page) => {
                        if let Err(error) = self.start_directory_home_publication(page) {
                            if let Some(home) = self.directory_home.as_mut() {
                                home.close();
                            }
                            self.error = Some(error);
                        }
                    }
                    Err(DirectoryClientError::Unauthorized) => {
                        if let Some(home) = self.directory_home.as_mut() {
                            let _ = home.begin_epoch(0);
                        }
                        self.directory_client = None;
                        #[cfg(not(target_arch="wasm32"))]
        self.cancel_inference_port();
        self.identity = None;
                        self.verified_session_authority = None;
                        self.bootstrap_identity();
                    }
                    Err(DirectoryClientError::Transport(TransportError::Io(_) | TransportError::DeadlineExceeded | TransportError::BudgetExhausted) | DirectoryClientError::Http { status: 500..=599, .. }) => {
                        if let Some(home) = self.directory_home.as_mut() {
                            home.retry_at_ms = crate::renderer_worker_pool().now_ms().saturating_add(DirectoryHomeProjection::RETRY_DELAY_MS);
                        }
                    }
                    Err(DirectoryClientError::Cancelled | DirectoryClientError::Transport(TransportError::Cancelled)) => {}
                    Err(_) => {
                        if let Some(home) = self.directory_home.as_mut() {
                            home.close();
                        }
                        self.error = Some("directory event-page response was terminally rejected".into());
                    }
                }
                changed = true;
            }
        }

        if let Some((epoch, instance_id, expected, outcome)) = self.poll_directory_home_publication() {
            let current = self.directory_home.as_ref().is_some_and(|home| !home.closed && home.bootstrap.bootstrap_epoch() == epoch && home.instance_id == instance_id);
            if current {
                match outcome {
                    ShellDirectoryHomePublicationOutcome::Published(acknowledgement) => {
                        let transition = self.directory_home.as_mut().expect("checked retained Home").bootstrap.acknowledge(&acknowledgement).map_err(|error| error.to_string());
                        match transition {
                            Ok(DirectoryBootstrapTransition::Fetch { .. }) => {}
                            Ok(DirectoryBootstrapTransition::Live { since }) => {
                                if let Err(error) = self.open_acknowledged_directory_stream(since) {
                                    if let Some(home) = self.directory_home.as_mut() {
                                        home.close();
                                    }
                                    self.error = Some(error);
                                }
                            }
                            Err(error) => {
                                if let Some(home) = self.directory_home.as_mut() {
                                    home.close();
                                }
                                self.error = Some(error);
                            }
                        }
                    }
                    ShellDirectoryHomePublicationOutcome::Rejected(error) => {
                        if let Some(home) = self.directory_home.as_mut() {
                            if error.contains("directory-event-page-rebootstrap-required") {
                                let _ = home.begin_epoch(0);
                            } else if home.retry(crate::renderer_worker_pool().now_ms(), &expected.receipt_sha256).is_err() {
                                home.close();
                                self.error = Some("retained Home directory rejection no longer matches the pending page".into());
                            }
                        }
                    }
                    ShellDirectoryHomePublicationOutcome::Terminal(error) => {
                        if let Some(home) = self.directory_home.as_mut() {
                            home.close();
                        }
                        self.error = Some(error);
                    }
                }
                changed = true;
            }
        }

        self.start_directory_event_page_fetch();
        self.flush_pending_directory_commands().await;
        changed
    }
    //#endregion 🔖️DirectoryAndIdentity

    /// 🐢️ `scope` is what the dispatch that produced these mutations declared it dirtied, unioned
    /// with what applying its own effects dirtied — [`UiDirtyScope::Full`] for every host-owned
    /// caller that speaks for no guest.
    pub fn apply_mutations<'a>(&'a mut self, operations: &'a [String], scope: UiDirtyScope) -> ShellTurn<'a, Result<(), String>> {
        shell_turn(async move {
            self.apply_ops_inner(operations, true, scope, self.session.clone()).await
        })
    }

    /// 🔗️ Document sync now flows through the `framework/sync` `ArtifactHost` actor + the
    /// program store's `ChannelBackbone` (see `attach_sync_backbone`), not a CRUD envelope
    /// write on every `setDocument` — the old `shell_backbone_write` mirror is deleted.
    ///
    /// 🪟️ `setPanel` names no body of its own and `panel_json` feeds EVERY section, so
    /// the widest scope is the only honest one — the same widening React's
    /// `hostEffectRefreshScopeV1` performs for the `setPanel`/`loadDocument` effects.
    ///
    /// 🗑️ The `downloadMediaExport`/`requestFileOpen` MUTATION arms lived here — two CRUD-era
    /// document operations no producer in the repo emits (`grep -rn '"requestFileOpen"'`
    /// answered this shell and nothing else). They were the only reader this renderer had
    /// for either journey, so `Export Document…` and `Import Document…` looked wired and
    /// reached nobody; both are now real `Effect` arms of the ONE host-effect funnel
    /// (`queue_host_effects`), which every dispatch path feeds
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    ///
    /// 🐢️ A `setDocument` is the widest dirt there is: every body that reads the artifact is stale,
    /// whatever the dispatch declared. The generation3d editor's own `setActiveExample` is the
    /// measured case — it replaces the whole fixture through artifact mutations and declares
    /// `UiDirtyScope::None` (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
    /// `📓️wgpu-dirty-scope-refresh-2026-09-14.md` §3.4) — so a shell that honours the scope must
    /// widen here or an example switch would leave every window painting the previous document.
    async fn apply_ops_inner(&mut self, operations: &[String], allow_navigate: bool, scope: UiDirtyScope, owner: Option<ActiveSession>) -> Result<(), String> {
        let mut pending: Vec<String> = operations.to_vec();
        let mut view_state = owner.as_ref().map(|s| s.view_state.clone());
        let mut document_changed = false;
        let mut panel_rewritten = false;
        let mut navigate_uri: Option<String> = None;
        while !pending.is_empty() {
            let batch = std::mem::take(&mut pending);
            for operation_json in batch {
                let operation: Value = serde_json::from_str(&operation_json).unwrap_or(Value::Null);
                if operation.get("operation").and_then(|v| v.as_str()) == Some("setDocument") {
                    document_changed = true;
                }
                if operation.get("operation").and_then(|v| v.as_str()) == Some("setPanel") {
                    panel_rewritten = true;
                    if let Some(panel) = operation.get("panel") {
                        if let Some(mut vs) = view_state.take() {
                            vs.panel_json = Some(panel.to_string());
                            view_state = Some(vs);
                        }
                    }
                }
                if operation.get("operation").and_then(|v| v.as_str()) == Some("requestFileSave") {
                    #[cfg(not(target_arch = "wasm32"))]
                    if let (Some(filename), Some(data), Some(space_id)) = (operation.get("filename").and_then(|v| v.as_str()), operation.get("data").and_then(|v| v.as_str()), operation.get("spaceId").and_then(|v| v.as_str())) {
                        if let Some(session) = owner.clone() {
                            let (filename, data, space_id) = (filename.to_string(), data.to_string(), space_id.to_string());
                            self.submit_shell_io_future(async move {
                                let Some(path) = request_file_save(&filename).await else { return ShellIoCompletion::Finished };
                                use std::fs as system_fs;
                                if system_fs::write(&path, data.as_bytes()).is_err() {
                                    return ShellIoCompletion::Finished;
                                }
                                ShellIoCompletion::Actions(vec![ActionDescriptor {
                                    controller_id: session.app.controller_id,
                                    action: "bindSpaceFile".into(),
                                    args: crate::action_args_json!({ "spaceId": space_id, "filePath": path.display().to_string() }),
                                }])
                            });
                        }
                    }
                }
                if operation.get("operation").and_then(|v| v.as_str()) == Some("requestFolderPick") {
                    #[cfg(not(target_arch = "wasm32"))]
                    if let Some(import_action) = operation.get("importAction").and_then(|v| v.as_str()) {
                        if let Some(session) = owner.clone() {
                            let import_action = import_action.to_string();
                            let mut args = operation.get("args").cloned().unwrap_or_else(|| serde_json::json!({}));
                            self.submit_shell_io_future(async move {
                                let Some(folder_path) = pick_folder().await else { return ShellIoCompletion::Finished };
                                if let Some(obj) = args.as_object_mut() {
                                    obj.insert("folderPath".into(), serde_json::json!(folder_path));
                                }
                                ShellIoCompletion::Actions(vec![ActionDescriptor { controller_id: session.app.controller_id, action: import_action, args: Some(semio_framework::DslValue::from(args)) }])
                            });
                        }
                    }
                }
                if operation.get("operation").and_then(|v| v.as_str()) == Some("spawnProgram") {
                    if let (Some(plugin_id), Some(session)) = (operation.get("pluginId").and_then(|v| v.as_str()), &self.session) {
                        self.spawn_plugin(plugin_id, session.view_state.clone()).await?;
                    }
                }
                if operation.get("operation").and_then(|v| v.as_str()) == Some("navigate") {
                    if let Some(uri) = operation.get("uri").and_then(|v| v.as_str()) {
                        navigate_uri = Some(uri.to_string());
                    }
                }
            }
        }
        if allow_navigate {
            if let Some(uri) = navigate_uri.take() {
                self.push_uri(uri.clone());
                self.apply_shell_uri(&uri).await?;
                if document_changed {
                    self.sync_session_chrome();
                }
                return Ok(());
            }
        }
        let scope = if panel_rewritten || document_changed { UiDirtyScope::Full } else { scope };
        if let (Some(owner), Some(vs)) = (owner.as_ref(), view_state) {
            if let Some(session) = self.session.as_mut().filter(|session| Self::same_session(session, owner)) {
                session.view_state = vs;
                self.sync_session_chrome();
            } else if let Some(session) = self.spawned_session.as_mut().filter(|session| Self::same_session(session, owner)) {
                session.view_state = vs;
            } else {
                return Err("mutation owner is no longer mounted".into());
            }
            self.refresh_ui(scope).await?;
        } else if document_changed {
            self.sync_session_chrome();
            self.refresh_ui(scope).await?;
        } else {
            self.owe_refresh(scope);
        }
        Ok(())
    }

    /// 🏠️🧳️ Generic replacement for the old `switch_to_s_app` — switches to either the host plugin's
    /// landing or host app by id (both resolved via `host_config()`, never a specific app's identity).
    ///
    /// 🎬️ The host plugin is resident on every healthy boot, so this is a one-scan no-op then. It is
    /// not decoration: `mountPluginHandles` skips a plugin whose module load faulted, and a boot
    /// that lost the HOST plugin that way used to answer `host program missing` for every later
    /// switch with no way back. One lazy install is the way back, on both targets.
    async fn switch_to_managed_app(&mut self, app_id: &str, view_state: Option<ViewModel>) -> Result<(), String> {
        let cfg = self.host_config().ok_or("host config missing")?;
        self.install_plugin(&cfg.plugin_id).await?;
        let semio_s_plugin_space = self.plugins.iter().find(|program| program.plugin_id == cfg.plugin_id).ok_or("host program missing")?;
        let app = semio_s_plugin_space.manifest.apps.iter().find(|candidate| candidate.id == app_id).ok_or("host app missing")?.clone();
        if let Some(session) = &self.session {
            if session.plugin_id == semio_s_plugin_space.plugin_id && session.app.id == app_id {
                if let Some(next_view_state) = view_state {
                    if let Some(mut current) = self.session.take() {
                        current.view_state = next_view_state;
                        self.session = Some(current);
                        self.refresh_ui(UiDirtyScope::Full).await?;
                    }
                }
                return Ok(());
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        if app_id == cfg.landing_app_id {
            if let Some(home) = self.directory_home.as_mut().filter(|home| home.plugin_id == semio_s_plugin_space.plugin_id && home.app.id == app_id) {
                if let Some(next_view_state) = view_state {
                    home.view_state = next_view_state;
                }
                let session = home.active_session();
                self.active_window_id = Some(session.app.window_kinds.first().id.clone());
                self.open_space_id = None;
                self.session = Some(session);
                return self.refresh_ui(UiDirtyScope::Full).await;
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        if let (Some(home), Some(current)) = (self.directory_home.as_mut(), self.session.as_ref()) {
            if home.is_instance(&current.plugin_id, current.instance_id) {
                home.view_state = current.view_state.clone();
            }
        }
        let instance_id = semio_s_plugin_space.create_app(&app.id).await?;
        let panel_state = self.default_host_panel_state()?;
        let default_view_state = ViewModel {
            active_mode_id: Some(app.default_mode_id.clone()),
            active_window_kind_id: Some(app.window_kinds.first().id.clone()),
            active_utility_id: None,
            panel_json: Some(Self::panel_json(&panel_state)?),
            extension_input_json: None,
            session_identity: None,
            locale: self.active_locale(),
            terminology: self.active_terminology(),
            window_id: None,
            focused_window_id: Some(app.window_kinds.first().id.clone()),
            window_instances: Vec::new(),
            active_tool_id: None,
            active_utility_by_window_id: HashMap::new(),
            tool_run_trace_cursor_by_window_id: HashMap::new(),
            tree_windows: Vec::new(),
            tree_viewport_rows: None,
        };
        let next_view_state = view_state.unwrap_or(default_view_state);
        self.active_window_id = Some(app.window_kinds.first().id.clone());
        if app_id == cfg.landing_app_id {
            self.open_space_id = None;
        }
        self.session = Some(ActiveSession { plugin_id: semio_s_plugin_space.plugin_id.clone(), instance_id, app, view_state: next_view_state });
        self.refresh_ui(UiDirtyScope::Full).await
    }

    /// 👁️✏️ Opens the sibling surface of the OPEN document's dialect — the wgpu twin of React's
    /// `switchToSessionRole` (`🧱️elements/🏛️ShellHost/🟦️.tsx`). A role the dialect does not declare,
    /// and the role already mounted, are both no-operations: `role_switch_target` answers `None` and
    /// nothing is created, retired or refreshed.
    pub(crate) async fn switch_to_session_role(&mut self, requested: semio_framework::manifest::AppRole) -> Result<(), String> {
        let Some(session) = self.session.clone() else {
            return Ok(());
        };
        let Some(program) = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id).cloned() else {
            return Ok(());
        };
        let Some(target) = role_switch_target(&program.manifest.apps, &session.app.dialect, session.app.role, requested).cloned() else {
            return Ok(());
        };
        self.run_session_app_switch(&program, target).await
    }

    /// 🔀️ The ORDERED in-place session switch — `create → seal → retire → publish → seed → refresh`.
    /// The successor instance exists before the predecessor is retired, so no render ever observes
    /// two live instances of one plugin and no switch leaks a `create_app`. Twin of
    /// `runSessionAppSwitchV1` (`🧱️elements/🏛️ShellHost/🔀️surface-switch/🟦️.ts`), whose `switch`
    /// fixture rows pin both the order and the `created − retired === 0` invariant. "Seal" is this
    /// target's own shape of React's close ladder: every retained surface document of the outgoing
    /// app is driven to terminal before its instance goes, because the resident aggregate is a fixed
    /// process-wide permit and a leaked root refuses every later surface with `Capacity`.
    async fn run_session_app_switch(&mut self, program: &ProgramBridgeEntry, app: AppDefinition) -> Result<(), String> {
        let Some(previous) = self.session.clone() else {
            return Ok(());
        };
        let instance_id = program.create_app(&app.id).await?;
        Self::debug_log(&format!("[TRACE] shell session switch {}", serde_json::json!({ "step": "create", "plugin": program.plugin_id, "from": previous.app.id, "to": app.id, "instance": instance_id })));
        self.retire_documents_outside(&[], true)?;
        self.retire_documents_outside(&[], false)?;
        Self::debug_log(&format!("[TRACE] shell session switch {}", serde_json::json!({ "step": "seal", "instance": previous.instance_id })));
        program.destroy_app(previous.instance_id);
        Self::debug_log(&format!("[TRACE] shell session switch {}", serde_json::json!({ "step": "retire", "instance": previous.instance_id })));
        let landing_window_id = app.window_kinds.first().id.clone();
        let view_state = ViewModel {
            active_mode_id: Some(app.default_mode_id.clone()),
            active_window_kind_id: Some(landing_window_id.clone()),
            active_utility_id: None,
            panel_json: None,
            extension_input_json: None,
            session_identity: None,
            locale: self.active_locale(),
            terminology: self.active_terminology(),
            window_id: None,
            focused_window_id: Some(landing_window_id.clone()),
            window_instances: Vec::new(),
            active_tool_id: None,
            active_utility_by_window_id: HashMap::new(),
            tool_run_trace_cursor_by_window_id: HashMap::new(),
            tree_windows: Vec::new(),
            tree_viewport_rows: None,
        };
        self.layout_override = None;
        self.active_window_id = Some(landing_window_id);
        self.session = Some(ActiveSession { plugin_id: previous.plugin_id.clone(), instance_id, app, view_state });
        self.sync_session_chrome();
        self.sync_dock();
        self.push_contributions().await?;
        self.announce_session_example().await?;
        Self::debug_log(&format!("[TRACE] shell session switch {}", serde_json::json!({ "step": "publish", "app": self.session.as_ref().map(|session| session.app.id.clone()) })));
        self.refresh_ui(UiDirtyScope::Full).await?;
        Self::debug_log(&format!(
            "[TRACE] shell session switch {}",
            serde_json::json!({ "step": "refresh", "app": self.session.as_ref().map(|session| session.app.id.clone()), "role": self.session.as_ref().map(|session| session.app.role.as_str()) })
        ));
        Ok(())
    }

    /// 🔁️ Steps the active mode one place along the app's declared order, wrapping — what the
    /// `mod+alt+→`/`mod+alt+←` chords fire. Reuses the very same body as clicking a
    /// `playground.navbar.modes.<id>` button, so keyboard and pointer cannot diverge.
    pub(crate) async fn apply_mode_step(&mut self, step: i32) -> Result<(), String> {
        let Some(session) = self.session.as_ref() else {
            return Ok(());
        };
        let mode_ids: Vec<String> = session.app.modes.iter().map(|mode| mode.id.clone()).collect();
        let Some(next) = step_mode_id(&mode_ids, session.view_state.active_mode_id.as_deref(), step) else {
            return Ok(());
        };
        self.apply_navbar_mode(&next).await
    }

    /// 🎛️ The ONE body behind a mode change, whether a navbar button or a chord asked for it.
    pub(crate) async fn apply_navbar_mode(&mut self, mode_id: &str) -> Result<(), String> {
        if let Some(session) = self.session.as_mut() {
            session.view_state.active_mode_id = Some(mode_id.to_string());
            if let Some(layout) = semio_framework::resolve_layout_for_mode(&session.app, mode_id) {
                self.layout_override = Some(layout);
                self.sync_dock();
                self.active_window_id = self.dock.active_window_id.clone();
            }
        }
        self.refresh_ui(UiDirtyScope::Full).await
    }

    fn validate_extension_record(record: &ShellExtensionStoreRecord) -> Result<(), String> {
        if record.extension_id.is_empty() || record.directory_name.is_empty() || record.version.is_empty() || record.extends_host.is_empty() || record.module_url.is_empty() || record.package_hash.is_empty() {
            return Err("extension store returned an incomplete record".into());
        }
        Ok(())
    }

    fn project_extension_record(&mut self, record: ShellExtensionStoreRecord) -> Result<usize, String> {
        Self::validate_extension_record(&record)?;
        if let Some(index) = self.extensions.iter().position(|entry| entry.record.extension_id == record.extension_id) {
            self.extensions[index].record = record;
            return Ok(index);
        }
        if self.extensions.len() >= SHELL_EXTENSION_LEDGER_CAPACITY {
            return Err("extension projection capacity exceeded".into());
        }
        self.extensions.push(ShellExtensionProjection { record, enabled: true, load_status: ShellExtensionLoadStatus::Available, program: None });
        Ok(self.extensions.len() - 1)
    }

    #[cfg(target_arch = "wasm32")]
    async fn load_extension_record(&mut self, record: ShellExtensionStoreRecord) -> Result<(), String> {
        let index = self.project_extension_record(record.clone())?;
        let record_json = serde_json::to_string(&record).map_err(|error| error.to_string())?;
        match crate::program_bridge::install_js_extension(&record_json, &record.extension_id, &record.version).await {
            Ok(program) => {
                let enabled = self.extensions[index].enabled;
                self.plugins.retain(|entry| entry.plugin_id != record.extension_id);
                if enabled {
                    self.plugins.push(program.clone());
                }
                self.extensions[index].program = Some(program);
                self.extensions[index].load_status = ShellExtensionLoadStatus::Loaded;
                Ok(())
            }
            Err(error) => {
                self.extensions[index].program = None;
                self.extensions[index].load_status = ShellExtensionLoadStatus::Failed(error.clone());
                Err(error)
            }
        }
    }

    #[cfg(target_arch = "wasm32")]
    async fn extension_store_answer(request: serde_json::Value) -> Result<serde_json::Value, String> {
        let answer = host_io_call(&request.to_string(), None).await?;
        let decoded: serde_json::Value = serde_json::from_str(&answer).map_err(|error| format!("extension store answer: {error}"))?;
        if let Some(error) = decoded.get("error").and_then(|value| value.as_str()) {
            return Err(error.to_string());
        }
        Ok(decoded)
    }

    #[cfg(target_arch = "wasm32")]
    async fn refresh_extension_store(&mut self) -> Result<(), String> {
        let answer = Self::extension_store_answer(serde_json::json!({ "op": "extension-store-list" })).await?;
        let records: Vec<ShellExtensionStoreRecord> = serde_json::from_value(answer.get("extensions").cloned().ok_or("extension store list missing extensions")?).map_err(|error| error.to_string())?;
        if records.len() > SHELL_EXTENSION_LEDGER_CAPACITY {
            return Err("extension store list exceeds projection capacity".into());
        }
        let retired: Vec<String> = self.extensions.iter().filter(|entry| !records.iter().any(|record| record.extension_id == entry.record.extension_id)).map(|entry| entry.record.extension_id.clone()).collect();
        self.plugins.retain(|entry| !retired.contains(&entry.plugin_id));
        self.extensions.retain(|entry| !retired.contains(&entry.record.extension_id));
        for record in records {
            let _ = self.load_extension_record(record).await;
        }
        Ok(())
    }

    async fn install_extension_from_store(&mut self, request: serde_json::Value) -> Result<bool, String> {
        #[cfg(target_arch = "wasm32")]
        {
            let answer = Self::extension_store_answer(request).await?;
            if answer.get("cancelled").and_then(serde_json::Value::as_bool) == Some(true) {
                return Ok(false);
            }
            let record: ShellExtensionStoreRecord = serde_json::from_value(answer.get("extension").cloned().ok_or("extension store install missing extension")?).map_err(|error| error.to_string())?;
            let load = self.load_extension_record(record).await;
            self.push_contributions().await?;
            self.refresh_ui(UiDirtyScope::Full).await?;
            load.map(|_| true)
        }
        #[cfg(not(target_arch = "wasm32"))]
        {
            let _ = request;
            Err("native extension installation is unavailable".into())
        }
    }

    pub(crate) fn set_extension_enabled<'a>(&'a mut self, extension_id: &'a str, enabled: bool) -> ShellTurn<'a, Result<bool, String>> {

        shell_turn(async move {
            let Some(index) = self.extensions.iter().position(|entry| entry.record.extension_id == extension_id) else { return Ok(false) };
            let program = self.extensions[index].program.clone();
            self.extensions[index].enabled = enabled;
            self.plugins.retain(|entry| entry.plugin_id != extension_id);
            if enabled {
                if let Some(program) = program {
                    self.plugins.push(program);
                }
            }
            self.push_contributions().await?;
            self.refresh_ui(UiDirtyScope::Full).await?;
            Ok(true)

        })

    }

    pub(crate) async fn uninstall_extension(&mut self, extension_id: &str) -> Result<bool, String> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let _ = extension_id;
            return Err("native extension uninstallation is unavailable".into());
        }
        #[cfg(target_arch = "wasm32")]
        {
            let Some(index) = self.extensions.iter().position(|entry| entry.record.extension_id == extension_id) else { return Ok(false) };
            let record = self.extensions[index].record.clone();
            self.plugins.retain(|entry| entry.plugin_id != extension_id);
            self.push_contributions().await?;
            self.refresh_ui(UiDirtyScope::Full).await?;
            if let Err(error) = crate::program_bridge::retire_js_extension(extension_id).await {
                let recovery = self.load_extension_record(record.clone()).await;
                self.push_contributions().await?;
                self.refresh_ui(UiDirtyScope::Full).await?;
                if let Err(recovery) = recovery {
                    return Err(format!("{error}; recovery failed: {recovery}"));
                }
                return Err(error);
            }
            if let Err(error) = Self::extension_store_answer(serde_json::json!({ "op": "extension-store-uninstall", "extensionId": extension_id })).await {
                let recovery = self.load_extension_record(record).await;
                self.push_contributions().await?;
                self.refresh_ui(UiDirtyScope::Full).await?;
                if let Err(recovery) = recovery {
                    return Err(format!("{error}; recovery failed: {recovery}"));
                }
                return Err(error);
            }
            self.extensions.remove(index);
            self.refresh_ui(UiDirtyScope::Full).await?;
            Ok(true)
        }
    }

    /// 🎯️ Refuses an install this target could never complete, BEFORE any install record is minted —
    /// native needs a resident program to read the `<modules_root>/<plugin_id>/<file>.wasm` root back
    /// off, the browser needs the frame Worker's own module door. A refusal here is not a phase: there
    /// is nothing in flight to report, and chrome must not show a cancellable install that never began.
    #[cfg(not(target_arch = "wasm32"))]
    fn plugin_install_precondition(&self) -> Result<(), String> {
        plugin_modules_root_of(&self.plugins).map(|_| ()).ok_or_else(|| "plugin modules root is unavailable".to_string())
    }

    /// 🎯️ Browser twin of the native precondition — see that method's own doc.
    #[cfg(target_arch = "wasm32")]
    fn plugin_install_precondition(&self) -> Result<(), String> {
        crate::program_bridge::js_plugin_install_door_available().then_some(()).ok_or_else(|| "this isolate installs no semioWgpuInstallPlugin door".to_string())
    }

    /// 📦️ The one step that differs per target: hand back a `ProgramBridgeEntry` for `plugin_id`.
    /// Native re-reads the runtime manifest `load_wasm_plugins` publishes (instantiating nothing —
    /// `from_wasm` compiles at `create_app`); the browser asks the frame Worker's own module loader for
    /// the SAME `pluginHandleForBridge` handle the boot plan's eager mount produces, because the wasm
    /// renderer cannot fetch a module itself.
    #[cfg(not(target_arch = "wasm32"))]
    async fn acquire_plugin_program(&mut self, plugin_id: &str) -> Result<ProgramBridgeEntry, String> {
        let modules_root = plugin_modules_root_of(&self.plugins).ok_or_else(|| "plugin modules root is unavailable".to_string())?;
        let plugin_filter = self.plugin_filter.clone();
        let entries = crate::program_bridge::load_wasm_plugins(&plugin_filter, &modules_root).await?;
        entries.into_iter().find(|entry| entry.plugin_id == plugin_id).ok_or_else(|| format!("native runtime manifest declares no module for {plugin_id}"))
    }

    /// 📦️ Browser twin of the native acquisition — see that method's own doc.
    #[cfg(target_arch = "wasm32")]
    async fn acquire_plugin_program(&mut self, plugin_id: &str) -> Result<ProgramBridgeEntry, String> {
        crate::program_bridge::install_js_plugin(plugin_id).await
    }

    /// 🎬️ Makes `plugin_id` resident, the wgpu twin of React's `installPlugin`
    /// (`🏛️ShellHost/🟦️.tsx`), on BOTH targets. A hub session lists every registered plugin in its
    /// session but instantiates none of them eagerly on native — `ProgramBridgeEntry::from_wasm`
    /// compiles nothing until `create_app` — so a native miss means the manifest this shell booted
    /// from predates the module, which one re-read fixes. In the browser the boot plan DOES eager-mount
    /// the variant's plugins, so a miss means the owner was outside that plan or its mount faulted and
    /// was skipped (`mountPluginHandles`'s per-plugin isolation); either way the frame Worker can still
    /// load one more module on demand. Already-resident is the common case and costs one scan.
    ///
    /// ⏱️ Progress and cancellation ride [`ShellState::plugin_install`]: the phase advances
    /// `Resolving` → `Loading` → cleared, and every step boundary checks the retained `CancelToken`, so
    /// [`Self::cancel_plugin_install`] stops the install before it commits an entry rather than after.
    /// One install at a time — a second request for the SAME plugin while one runs is refused rather
    /// than racing a second acquisition against the first one's commit.
    pub async fn install_plugin(&mut self, plugin_id: &str) -> Result<(), String> {
        if self.plugins.iter().any(|entry| entry.plugin_id == plugin_id) {
            return Ok(());
        }
        if self.plugin_install.is_some() {
            return Err(format!("plugin install already in flight, {plugin_id} not admitted"));
        }
        self.plugin_install_precondition()?;
        let cancel = CancelToken::root_now();
        self.plugin_install = Some(ShellPluginInstall { plugin_id: plugin_id.to_string(), phase: ShellPluginInstallPhase::Resolving, cancel: cancel.clone() });
        if let Some(install) = self.plugin_install.as_mut() {
            install.phase = ShellPluginInstallPhase::Loading;
        }
        let loaded = self.acquire_plugin_program(plugin_id).await;
        let settled = match loaded {
            _ if cancel.is_cancelled_now() => Err(ShellPluginInstallPhase::Cancelled),
            Err(error) => Err(ShellPluginInstallPhase::Failed(error)),
            Ok(entry) => Ok(entry),
        };
        match settled {
            Ok(entry) => {
                if !self.plugins.iter().any(|resident| resident.plugin_id == plugin_id) {
                    self.plugins.push(entry);
                }
                self.plugin_install = None;
                Ok(())
            }
            Err(phase) => {
                let message = match &phase {
                    ShellPluginInstallPhase::Cancelled => format!("plugin install cancelled: {plugin_id}"),
                    ShellPluginInstallPhase::Failed(error) => error.clone(),
                    _ => format!("plugin install refused: {plugin_id}"),
                };
                if let Some(install) = self.plugin_install.as_mut() {
                    install.phase = phase;
                }
                Self::debug_log(&format!("[TRACE] wgpu shell plugin install failed: {message}"));
                Err(message)
            }
        }
    }

    /// 🛑️ Cancels the retained lazy install. The phase does NOT move here: only the install's own next
    /// step boundary may report `Cancelled`, so an install that already committed is never misreported
    /// as having been stopped. Clearing a settled `Failed`/`Cancelled` record is the same call. In the
    /// browser the frame Worker's own request is withdrawn too, so a cancel during a long module fetch
    /// settles the awaited promise now instead of at the end of the fetch.
    pub fn cancel_plugin_install(&mut self) {
        let settled = matches!(self.plugin_install.as_ref().map(|install| &install.phase), Some(ShellPluginInstallPhase::Failed(_)) | Some(ShellPluginInstallPhase::Cancelled));
        if settled {
            self.plugin_install = None;
            return;
        }
        if let Some(install) = self.plugin_install.as_ref() {
            install.cancel.cancel_now();
            #[cfg(target_arch = "wasm32")]
            crate::program_bridge::cancel_js_plugin_install(&install.plugin_id);
        }
    }

    /// 🎬️ The plugin that opens `dialect`, from the catalog's declared `on-artifact-kind:` rows — the
    /// wgpu twin of React's `artifactKindActivationOwner` lookup, and the only resolution that works
    /// before the owner's manifest is resident. Returns the owner and its app for `role` once that
    /// owner is installed, so the relay below can hand both straight to [`Self::switch_to_app`].
    /// Both targets: the table is generated into this crate and the install is [`Self::install_plugin`],
    /// which O2 made target-neutral.
    async fn resolve_activation_owner_app(&mut self, dialect: &semio_framework::ArtifactDialect, role: semio_framework::manifest::AppRole) -> Option<(String, AppDefinition)> {
        let owner = crate::program_bridge::resolve_artifact_kind_activation_owner(&dialect.artifact_kind)?;
        if let Err(error) = self.install_plugin(owner).await {
            Self::debug_log(&format!("[TRACE] wgpu shell os.open-artifact could not install {owner}: {error}"));
            return None;
        }
        let program = self.plugins.iter().find(|entry| entry.plugin_id == owner)?;
        let app = find_dialect_app(program, dialect, role).or_else(|| find_dialect_app(program, dialect, semio_framework::manifest::AppRole::Editor))?;
        Some((owner.to_string(), app.clone()))
    }

    /// 📇️ ticket §6 — generic app switch by definition (not the host's landing/host app via
    /// `host_config()`), used for the `s.space` artifact-index route below. Kept as a close sibling of
    /// `switch_to_managed_app` (CLAUDE.md: repeated code stays close together) rather than a forced
    /// shared abstraction that would blur the two call shapes (this one has no workflow-panel state).
    /// Both targets — the lazy install it opens with is [`Self::install_plugin`]; only the retained
    /// Home hand-back below is native, because `directory_home` is a native-only projection.
    async fn switch_to_app(&mut self, plugin_id: &str, app: AppDefinition) -> Result<(), String> {
        self.install_plugin(plugin_id).await?;
        let program = self.plugins.iter().find(|entry| entry.plugin_id == plugin_id).cloned().ok_or("program missing")?;
        if let Some(session) = &self.session {
            if session.plugin_id == plugin_id && session.app.id == app.id {
                return Ok(());
            }
        }
        let instance_id = program.create_app(&app.id).await?;
        self.install_app_session(plugin_id, app, instance_id);
        self.refresh_ui(UiDirtyScope::Full).await
    }

    /// 🪪️ Mounts `instance_id` of `app` as this shell's session: the retained Home hands back its view
    /// state first, then the session and its first window become current. The synchronous tail of
    /// [`Self::switch_to_app`], shared with the frame-pumped open ([`Self::advance_document_opening`]),
    /// which renders on the settle lane instead of inline.
    fn install_app_session(&mut self, plugin_id: &str, app: AppDefinition, instance_id: u32) {
        #[cfg(not(target_arch = "wasm32"))]
        if let (Some(home), Some(current)) = (self.directory_home.as_mut(), self.session.as_ref()) {
            if home.is_instance(&current.plugin_id, current.instance_id) {
                home.view_state = current.view_state.clone();
            }
        }
        let view_state = ViewModel {
            active_mode_id: Some(app.default_mode_id.clone()),
            active_window_kind_id: Some(app.window_kinds.first().id.clone()),
            active_utility_id: None,
            panel_json: None,
            extension_input_json: None,
            session_identity: None,
            locale: self.active_locale(),
            terminology: self.active_terminology(),
            window_id: None,
            focused_window_id: Some(app.window_kinds.first().id.clone()),
            window_instances: Vec::new(),
            active_tool_id: None,
            active_utility_by_window_id: HashMap::new(),
            tool_run_trace_cursor_by_window_id: HashMap::new(),
            tree_windows: Vec::new(),
            tree_viewport_rows: None,
        };
        self.active_window_id = Some(app.window_kinds.first().id.clone());
        self.session = Some(ActiveSession { plugin_id: plugin_id.to_string(), instance_id, app, view_state });
    }

    /// 📇️ ticket §5/§6 — "/spaces/{id}/studio" keeps the pre-existing studio behaviour (the ONLY
    /// behaviour this route had before this lane); a bare "/spaces/{id}" now opens the `s.space`
    /// artifact-index app instead, mirroring the React shell's `applyShellUri` (`📓️w2-c-report.md`).
    ///
    /// 🧭️ Pin before the async switch so a concurrent chrome sync cannot boot the demo example over
    /// an explicit `/spaces/:id` route.
    ///
    /// 🎠️ H3-wgpu-native — `load_app_document_pack` is now async.
    fn apply_shell_uri<'a>(&'a mut self, uri: &'a str) -> ShellTurn<'a, Result<(), String>> {

        shell_turn(async move {
            let path = uri.split('?').next().unwrap_or(uri);
            if path.trim_end_matches('/') == "/hub" {
                self.hub_workspace_open = true;
                self.project_verified_hub_authority();
                if self.hub_workspace.session.phase == HubSessionPhase::SignedIn {
                    self.start_hub_spaces_reload();
                }
                return self.refresh_ui(UiDirtyScope::Full).await;
            }
            let Some(cfg) = self.host_config() else {
                return Ok(());
            };
            let raw = path.strip_prefix("/spaces/").map(|value| value.trim_end_matches('/').to_string()).filter(|value| !value.is_empty());
            if raw.is_none() {
                self.open_space_id = None;
                if self.session.as_ref().map(|session| session.app.id.as_str()) != Some(cfg.landing_app_id) {
                    self.switch_to_managed_app(cfg.landing_app_id, None).await?;
                }
                return Ok(());
            }
            let raw = raw.expect("space route");
            let space_route = match raw.split_once('/') {
                Some((id, "studio")) => (id.to_string(), true),
                _ => (raw.clone(), false),
            };
            let space_id = space_route.0;
            if !space_route.1 {
                self.open_space_id = Some(space_id.clone());
                let host_program = self.plugins.iter().find(|program| program.plugin_id == cfg.plugin_id).cloned();
                let space_app = host_program
                    .as_ref()
                    .and_then(|program| find_dialect_app(program, &space_index_dialect(), semio_framework::manifest::AppRole::Editor).or_else(|| find_dialect_app(program, &space_index_dialect(), semio_framework::manifest::AppRole::Viewer)))
                    .cloned();
                let Some(space_app) = space_app else {
                    Self::debug_log(&format!("[TRACE] wgpu shell apply_shell_uri: no app registered for dialect s.space.space@1/* — s.space (lane 1-E) not loaded yet"));
                    return Ok(());
                };
                self.switch_to_app(cfg.plugin_id, space_app).await?;
                let (bindings, surface) = self.default_bindings_for_current_session();
                return self.open_document(S_SPACE_INDEX_DOCUMENT_ID.to_string(), S_SPACE_INDEX_DOCUMENT_SCHEMA.to_string(), bindings, surface, None).await;
            }
            let studio_changed = self.open_space_id.as_deref() != Some(space_id.as_str());
            self.open_space_id = Some(space_id.clone());
            self.switch_to_managed_app(cfg.host_app_id, None).await?;
            if !studio_changed {
                return Ok(());
            }
            let session = self.session.clone().ok_or("space session missing")?;
            let program = self.plugins.iter().find(|entry| entry.plugin_id == session.plugin_id).ok_or("space program missing")?;
            let action = ActionDescriptor { controller_id: session.app.controller_id.clone(), action: "openSpace".into(), args: crate::action_args_json!({ "spaceId": space_id }) };
            let action_json = serde_json::to_string(&action).map_err(|err| err.to_string())?;
            let result = program.handle_action(session.instance_id, &action_json, &session.view_state).await?;
            for effect in &result.requested_effects {
                if let semio_framework::kernel::Effect::LoadDocument { pack, spr } = effect {
                    program.load_app_document_pack(session.instance_id, pack, spr).await?;
                }
            }
            self.sync_session_chrome();
            self.refresh_ui(UiDirtyScope::Full).await

        })

    }

    pub async fn apply_pending_shell_uri(&mut self) -> Result<(), String> {
        let uri = self.shell_uri();
        self.apply_shell_uri(&uri).await
    }

    async fn spawn_plugin(&mut self, plugin_id: &str, mut view_state: ViewModel) -> Result<(), String> {
        let workflows = self.build_space_workflows();
        let Some(workflow) = workflows.iter().find(|entry| entry.plugin_id == plugin_id).cloned() else {
            return Ok(());
        };
        let bridge = self.plugins.iter().find(|entry| entry.plugin_id == workflow.plugin_id).ok_or("spawn program missing")?;
        let instance_id = bridge.create_app(&workflow.app_id).await?;
        let mut panel = Self::panel_state_from_view(&view_state)?.unwrap_or(self.default_host_panel_state()?);
        let spawned_id = format!("{}-{}", bridge.plugin_id, instance_id);
        panel.spawned_apps.push(SpawnedAppEntry { id: spawned_id.clone(), plugin_id: bridge.plugin_id.clone(), instance_id, app_id: workflow.app_id.clone(), label: workflow.label.clone(), breadcrumb: workflow.breadcrumb.clone() });
        panel.active_spawned_id = Some(spawned_id);
        view_state.panel_json = Some(Self::panel_json(&panel)?);
        if let Some(session) = self.session.as_mut() {
            session.view_state = view_state;
        }
        Ok(())
    }
}
//#endregion ShellActions

//#region ShellInput
impl ShellChromeBuildState {
    fn content_has_focus(&self, window_id: &str) -> bool {
        self.content_focus_node(window_id).is_some()
    }

    /// 🎯️ WHICH retained node holds focus in `window_id` — React's `surfaceActiveRoot`. A chrome verb
    /// that must address the focused content node (a panel-level Copy, an inspector commit) reads this
    /// instead of re-deriving focus from the tree.
    fn content_focus_node(&self, window_id: &str) -> Option<ui_wgpu::wgpu::NodeId> {
        self.content_focus.get(window_id).and_then(Option::as_ref).map(|focus| focus.node)
    }

    fn note_content_focus_commands(&mut self, commands: &[ui_wgpu::wgpu::UiCommand]) {
        for command in commands {
            if let ui_wgpu::wgpu::UiCommand::FocusChanged { window_id, node } = command {
                ShellState::debug_log(&format!("[TRACE] wgpu-shell content focus window={window_id} node={node:?}"));
                let focus = node.and_then(|node| crate::interpreter::retained_node_focus_identity(window_id, node).map(|(key, kind)| RetainedContentFocus { node, key, kind }));
                if focus.is_some() {
                    if let Some(previous) = self.focused_retained_surface.replace(window_id.clone()).filter(|previous| previous != window_id) {
                        self.content_focus.insert(previous, None);
                    }
                } else if self.focused_retained_surface.as_deref() == Some(window_id.as_str()) {
                    self.focused_retained_surface = None;
                }
                self.content_focus.insert(window_id.clone(), focus);
            }
        }
    }

    fn clear_content_focus(&mut self, surface: &str) {
        self.content_focus.remove(surface);
        if self.focused_retained_surface.as_deref() == Some(surface) {
            self.focused_retained_surface = None;
        }
    }

    fn clear_sibling_pane_focus(&mut self, surface: &str) {
        let owner = window_pane_owner(surface).unwrap_or(surface);
        for sibling in [owner.to_string(), window_measures_surface_id(owner), window_actions_surface_id(owner), window_search_surface_id(owner), window_projection_surface_id(owner)] {
            if sibling != surface {
                self.clear_content_focus(&sibling);
            }
        }
    }
}

/// ⌨️ Maps a chrome-level `ui_wgpu::wgpu::KeyAction` (+ modifiers) to the `ui_wgpu::wgpu::UiEvent` the retained
/// content engine's `events::EventRouter::dispatch` expects — mirrors that fn's `UiEvent::KeyDown`
/// key-string vocabulary exactly (`"ArrowLeft"`/`"Backspace"`/`"c"`+ctrl for copy/etc., see
/// `ui_wgpu`'s `🔖️EditRouting`/`🔖️UiCommand` regions). A `Char` held with Ctrl/Cmd routes as
/// `KeyDown` (so `c`/`x`/`v` clipboard chords reach `route_edit_key` instead of being literally
/// inserted as text). A focused Select owns printable typeahead and the Space press as `KeyDown`;
/// editable controls keep plain characters as `TextInput`.
fn ui_event_from_key_action(action: &ui_wgpu::wgpu::KeyAction, modifiers: &PointerModifiers, focused_select: bool) -> Option<ui_wgpu::wgpu::UiEvent> {
    let event_modifiers = ui_wgpu::wgpu::EventModifiers { shift: modifiers.shift, ctrl: modifiers.ctrl, alt: modifiers.alt, meta: modifiers.meta };
    match action {
        ui_wgpu::wgpu::KeyAction::Char(ch) => {
            if modifiers.ctrl_or_meta() || focused_select {
                Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: ch.clone(), modifiers: event_modifiers })
            } else {
                Some(ui_wgpu::wgpu::UiEvent::TextInput { text: ch.clone() })
            }
        }
        ui_wgpu::wgpu::KeyAction::Backspace => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Backspace".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Delete => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Delete".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Enter => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Enter".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Escape => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Escape".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::ArrowLeft => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "ArrowLeft".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::ArrowRight => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "ArrowRight".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::ArrowUp => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "ArrowUp".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::ArrowDown => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "ArrowDown".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Home => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Home".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::End => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "End".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::PageUp => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "PageUp".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::PageDown => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "PageDown".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Function(number) => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: format!("F{number}"), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Tab => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: "Tab".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Space(true) if focused_select => Some(ui_wgpu::wgpu::UiEvent::KeyDown { key: " ".into(), modifiers: event_modifiers }),
        ui_wgpu::wgpu::KeyAction::Space(_) => None,
    }
}

impl ShellState {
    fn retained_keyboard_focus(&self) -> Option<(String, ui_wgpu::wgpu::NodeId)> {
        let surface = self.chrome_build.focused_retained_surface.as_ref()?;
        let owner = window_pane_owner(surface).unwrap_or(surface);
        if !self.retained_surface_is_panel(surface) && self.active_window_id.as_deref() != Some(owner) {
            return None;
        }
        let focus = self.chrome_build.content_focus.get(surface)?.as_ref()?;
        crate::interpreter::retained_node_has_visible_focus(surface, focus.node, &focus.key, focus.kind).then(|| (surface.clone(), focus.node))
    }

    pub(crate) fn retained_select_owns_keyboard(&self) -> bool {
        self.retained_keyboard_focus().is_some_and(|(surface, node)| crate::interpreter::retained_node_is_select(&surface, node))
    }
}

fn tree_drag_handle_item_id(control_id: &str) -> Option<&str> {
    control_id.strip_prefix("tree.drag.sort.").or_else(|| control_id.strip_prefix("tree.drag.transfer."))
}

fn tree_hit_item_id(control_id: &str) -> Option<&str> {
    control_id.strip_prefix("tree.label.").or_else(|| tree_drag_handle_item_id(control_id))
}

/// 🌳️ Whether this frame painted a fold chevron for `item_id` — the row has children.
fn tree_row_has_chevron(input: &InputState<ActionDescriptor>, item_id: &str) -> bool {
    let chevron = format!("tree.chevron.{item_id}");
    input.hits().iter().chain(input.staged_hits().iter()).any(|hit| hit.control_id.as_deref() == Some(chevron.as_str()))
}

//#region 🫥️HostWindowBlur
/// 🫥️ Whether the host window lost the system focus since the shell last looked (native winit `Focused(false)`, the browser
/// page's `window` blur through the `semioWgpuHostWindowBlur` door). A worker cell, so a law's thread owns its own.
static HOST_WINDOW_BLUR_PENDING: crate::interpreter::WorkerCell<bool> = crate::interpreter::WorkerCell::new(Default::default);

/// 🫥️ The host window lost the system focus: every open text-editor typing run ends at once (`blur`, design §13.2 of ticket
/// 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING), and the shell's next drain blurs the focused pane for its program
/// ([`ShellState::arm_host_window_blur`]) — what React's pane `onBlur` does when the page loses focus.
pub fn note_host_window_blur() {
    crate::engine_canvas::end_every_text_editor_typing(crate::engine_canvas::TextEditorTypingEnd::Blur);
    *HOST_WINDOW_BLUR_PENDING.borrow_mut() = true;
}

/// 🫥️ Whether a host window blur waits for the shell's drain.
fn host_window_blur_pending() -> bool {
    *HOST_WINDOW_BLUR_PENDING.borrow()
}

/// 🫥️ The browser frame Worker's window-blur door (`host-window-blur`): the page's `window` lost focus.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen(js_name = semioWgpuHostWindowBlur)]
pub fn semio_wgpu_host_window_blur() {
    note_host_window_blur();
}
//#endregion 🫥️HostWindowBlur

/// 📨️ `hostEvent{windowId, kind}` on `controller_id`: the window fact the program answers by ending an open gesture there —
/// the wgpu twin of React's `windowHostEventHandlersV1` (a pane that loses the activation is blurred, a cancelled pointer
/// sequence loses its capture).
pub(crate) fn window_host_event_action(controller_id: &str, window_id: &str, kind: &str) -> ActionDescriptor {
    ActionDescriptor { controller_id: controller_id.to_string(), action: semio_framework::HOST_EVENT_ACTION_ID.into(), args: crate::action_args_json!({ "windowId": window_id, "kind": kind }) }
}

/// 🌳️ Retained controls whose complete pointer gesture belongs to `EventRouter`.
fn retained_router_owns_pointer(kind: HitKind) -> bool {
    matches!(kind, HitKind::Button | HitKind::Input | HitKind::Select | HitKind::Toggle | HitKind::Slider | HitKind::NumberStepper | HitKind::Ring | HitKind::IconSelect | HitKind::TreeItem | HitKind::TreeDragHandle | HitKind::ComponentScene)
}

impl ShellState {
    /// 🛑️ Retires a cancelled pointer sequence without a click, drop, or release commit.
    pub fn handle_pointer_cancel(&mut self, input: &mut InputState<ActionDescriptor>) {
        self.handle_pointer_cancel_for(ui_render::PointerId(1), input);
    }

    pub fn handle_pointer_cancel_for(&mut self, pointer_id: ui_render::PointerId, input: &mut InputState<ActionDescriptor>) {
        let retained_cancelled = crate::interpreter::retained_pointer_capture_window(pointer_id);
        if let Some(window_id) = retained_cancelled.as_ref() {
            crate::interpreter::dispatch_ui_pointer_event(&window_id, pointer_id, ui_wgpu::wgpu::UiEvent::PointerCancel, input);
        }
        let (pointer_x, pointer_y) = (input.pointer_x, input.pointer_y);
        let cancelled_scenes = crate::interpreter::cancel_scene_pointer(pointer_id, input);
        let scene_cancelled = !cancelled_scenes.is_empty();
        let mut capture_lost: Vec<&str> = retained_cancelled.iter().map(String::as_str).chain(cancelled_scenes.iter().map(|cancelled| cancelled.window_id.as_str())).collect();
        capture_lost.sort_unstable();
        capture_lost.dedup();
        if let Some(controller_id) = self.shell_command_controller_id() {
            for window_id in capture_lost {
                self.deferred_actions.push(window_host_event_action(&controller_id, window_id, semio_framework::HOST_EVENT_KIND_CAPTURE_LOST));
            }
        }
        for cancelled in cancelled_scenes {
            match cancelled.kind {
                ui_wgpu::wgpu::SurfaceKind::World3d => {
                    if let Some(state) = self.world3d_states.get_mut(&cancelled.host_id) {
                        infinite_world::world::world3d_cancel_relocate_drag(state);
                    }
                }
                ui_wgpu::wgpu::SurfaceKind::NodeGraph => {
                    crate::engine_canvas::node_graph_pointer_cancel_into(&cancelled.host_id);
                }
                ui_wgpu::wgpu::SurfaceKind::Board2d => {
                    crate::engine_canvas::puzzle_board_pointer_cancel_into(&cancelled.host_id, input);
                }
                ui_wgpu::wgpu::SurfaceKind::TiledMap => {
                    if let Some(surface) = self.tiled_map_states.get(&cancelled.host_id).filter(|surface| surface.window_id == cancelled.window_id) {
                        if let Err(fault) = crate::scenes::tiled_map_pointer_cancel_into(&cancelled.host_id, &surface.controller_id, surface.bounds, pointer_x, pointer_y, &mut *input) {
                            input.record_action_fault(fault);
                        }
                    }
                }
                _ => {}
            }
        }
        let canvas_cancelled = crate::scenes::cancel_canvas_pointer_gesture_for(pointer_id, input);
        let transfer_cancelled = crate::scenes::cancel_scene_list_transfer_for_pointer(pointer_id);
        let chrome_cancelled = self.chrome_pointer_owner == Some(pointer_id);
        if chrome_cancelled {
            self.chrome_pointer_owner = None;
            self.dock_tab_drag = None;
            self.dock_drag = None;
            self.pending_dock_drag = None;
            self.tree_drag = None;
            self.pending_tree_drag = None;
            self.pending_chrome_release = None;
            self.right_click = RightClickState::default();
        }
        if retained_cancelled.is_some() || scene_cancelled || canvas_cancelled || transfer_cancelled || chrome_cancelled {
            input.pointer_down = false;
            input.hovered_id = None;
            input.drag = Default::default();
        }
    }

    /// 🖱️ One chrome pointer button, dispatched and RETURNED — the chain it armed converges on the
    /// frame loop's settle lane ([`Self::settle_pump_step`]), never inside this turn.
    ///
    /// 🩸️ This used to end in `flush_deferred_actions`, whose `settle_ui_chain` runs up to
    /// `SHELL_SETTLE_ROUNDS` whole-shell refresh passes to a fixed point. The renderer lends its ONE
    /// interaction state to a dispatch for the length of the dispatch's future, so a gesture whose
    /// chain re-solved the graph held that state for the whole convergence and no later input was
    /// dispatched at all. Measured on 6118 (`📓️wgpu-generate-add-port-fit-2026-09-14.md`): a stray
    /// port drag rewired the graph, one pointer move then held `dispatch-event` for **8 515 ms**
    /// across 6 refresh passes, and the `F` the user pressed 1.1 s later reached
    /// `fit_node_graph_camera` **7 632 ms** after the key went down.
    pub async fn handle_pointer_button(&mut self, x: f32, y: f32, down: bool, button: i16, input: &mut InputState<ActionDescriptor>, theme: &Theme) -> Result<(), String> {
        self.handle_pointer_button_for(ui_render::PointerId(1), x, y, down, button, input, theme).await
    }

    /// 📑️ React's tab label is a `<button onClick={() => onSelectTab(tab.id)}>`: the select
    /// lands on RELEASE over the same label, and it is addressed by window ID, never by the
    /// stack path the chip happens to be painted at — the mobile flat stack renders every tab
    /// at the root path.
    ///
    /// 🖱️ A cross-surface transfer must deliver the semantic release to the CURRENT
    /// destination and also retire EventRouter capture on the SOURCE. The destination
    /// runs first and consumes the generation-owned transfer; the second up is outside
    /// the captured source's geometry, so it can only clear its pressed/capture state —
    /// it cannot emit a second drop or source click.
    ///
    /// 📋️ Alt + secondary press on a text editor is the completions gesture, not a menu —
    /// React's own `onContextMenu` takes that branch first (`✏️TextEditor/🟦️.tsx:413`).
    ///
    /// 🌫️ Pressing the mode canvas where no chrome and no window body answers is React's
    /// `handleCanvasBackgroundPointerDown` on `[data-slot="mode-body"]` itself
    /// (`🖱️ui/🧱️elements/🎨️Canvas/🟦️.tsx:1461-1471`): the mode keeps its layout and loses its focus.
    ///
    /// 🎯️ A retained window body owns its own targets end to end: the node's declared action
    /// fires through `dispatch_action`, a focusable control is routed into that body's
    /// `events::EventRouter`, and none of the chrome id conventions below can claim it.
    ///
    /// 🌫️ A resize gutter is canvas BACKGROUND as far as focus goes: React's
    /// `handleCanvasBackgroundPointerDown` deactivates on any `data-slot="resizable-panel"`
    /// press (`🖱️ui/🧱️elements/🎨️Canvas/🟦️.tsx:1461-1471`) and still starts the resize.
    ///
    /// 🎬️ Only the tab's grip chip starts a drag, exactly like React's `DragHandle`
    /// `onPointerDown` (`🖱️ui/🧱️elements/🎨️Canvas/🟦️.tsx:1101`); the label beside it selects
    /// on release and never travels.
    pub async fn handle_pointer_button_for(&mut self, pointer_id: ui_render::PointerId, x: f32, y: f32, down: bool, button: i16, input: &mut InputState<ActionDescriptor>, theme: &Theme) -> Result<(), String> {
        Self::debug_log(&format!(
            "[TRACE] wgpu-shell pointer button x={x} y={y} down={down} button={button} targets={} staged={} gen={} hit={:?}",
            input.hits().len(),
            input.staged_hits().len(),
            input.hit_generation(),
            input.hit_at(x, y).map(|target| (target.kind, target.control_id.clone(), target.event.as_ref().map(|descriptor| descriptor.action.clone())))
        ));
        if !down && self.chrome_pointer_owner.is_some_and(|owner| owner != pointer_id) {
            return Ok(());
        }
        input.pointer_x = x;
        input.pointer_y = y;
        input.pointer_down = down;
        input.pointer_button = button;
        if !down {
            if self.chrome_pointer_owner == Some(pointer_id) {
                self.chrome_pointer_owner = None;
            }
            let retained_canvas_drag = crate::interpreter::active_retained_drag_sessions().into_iter().map(|(_, _, _, drag_data)| drag_data).find(|drag_data| drag_data.contains_key(crate::scenes::CANVAS_CATALOGUE_DRAG_MIME));
            if let Some((tab_id, from_anchor)) = self.dock_tab_drag.take() {
                self.finish_dock_tab_drag(&tab_id, from_anchor, x, y, theme);
            }
            let dock_drop_result = if self.dock_drag.is_some() {
                self.finish_dock_drag(x, y, input).await
            } else {
                self.pending_dock_drag = None;
                Ok(())
            };
            if let Some(control_id) = self.pending_chrome_release.take() {
                let same_control = input.hit_at(x, y).and_then(|hit| hit.control_id.as_deref()) == Some(control_id.as_str());
                if let Some((kind, index)) = ShellPaletteKind::row_index(&control_id) {
                    if same_control && button == 0 {
                        match kind {
                            ShellPaletteKind::Search => self.activate_search_item(index).await?,
                            ShellPaletteKind::Find => self.activate_find_item(index).await?,
                        }
                        input.blur_input();
                        self.accessibility_focused_control_id = None;
                    }
                    crate::scenes::cancel_scene_list_transfer();
                    return dock_drop_result;
                }
                if ShellPaletteKind::from_close_id(&control_id).is_some() {
                    if same_control && button == 0 {
                        self.close_command_palette(input);
                    }
                    crate::scenes::cancel_scene_list_transfer();
                    return dock_drop_result;
                }
                if let Some(window_id) = dock_tab_select_window_id(&control_id).filter(|_| same_control) {
                    if self.dock.activate_window(window_id) {
                        self.active_window_id = Some(window_id.to_string());
                    }
                }
            }
            if self.tree_drag.is_some() {
                self.finish_tree_drag(x, y, input).await?;
            } else if let Some((item_id, _)) = self.pending_tree_drag.take() {
                if let Some(hit) = input.hit_at(x, y) {
                    if hit.control_id.as_deref().and_then(|id| id.strip_prefix("tree.label.")) == Some(item_id.as_str()) {
                        if tree_row_has_chevron(input, &item_id) {
                            self.toggle_immediate_tree_item(&item_id);
                        }
                        self.dispatch_tree_selection(&item_id);
                        if let Some(action) = hit.event.clone() {
                            self.dispatch_action(action).await?;
                        }
                    }
                }
            }
            let canvas_drop_accepted = retained_canvas_drag.as_ref().is_some_and(|drag_data| self.finish_canvas2d_catalogue_drop(x, y, drag_data, input));
            if input.drag.active {
                let drag_target = input.drag.target_id.clone();
                self.dispatch_widget_drag_values(input).await?;
                input.end_drag();
                if drag_target.as_deref().is_some_and(|id| id.starts_with("dock.split.") || id.starts_with("dock.corner.")) {
                    self.persist_dock_layout();
                    if let Some(controller_id) = self.shell_command_controller_id() {
                        let note = Self::note_shell_command_action(&controller_id, "shell.windowResize", shell_chrome_string("command.resizeWindow", self.locale_id == "de"), None);
                        self.dispatch_action(note).await?;
                    }
                }
            }
            let captured_release = crate::interpreter::retained_pointer_capture_window(pointer_id).and_then(|window_id| self.retained_window_body_rect(&window_id).map(|body| (window_id, body)));
            let retained_release = input
                .hit_at(x, y)
                .cloned()
                .and_then(|hit| self.retained_hit_window(&hit).map(|(window_id, body)| (window_id, body, hit.kind, hit.event)))
                .or_else(|| captured_release.clone().map(|(window_id, body)| (window_id, body, HitKind::ComponentScene, None)));
            if canvas_drop_accepted {
                if let Some((captured_window, captured_body)) = captured_release {
                    self.route_retained_pointer_press(&captured_window, captured_body, captured_body.x - 1.0, captured_body.y - 1.0, false, button, HitKind::ComponentScene, None, pointer_id, input).await?;
                }
            } else if let Some((window_id, body, kind, action)) = retained_release {
                let released_window = window_id.clone();
                self.route_retained_pointer_press(&window_id, body, x, y, false, button, kind, action, pointer_id, input).await?;
                if let Some((captured_window, captured_body)) = captured_release.filter(|(captured_window, _)| captured_window != &released_window) {
                    self.route_retained_pointer_press(&captured_window, captured_body, x, y, false, button, HitKind::ComponentScene, None, pointer_id, input).await?;
                }
            }
            crate::scenes::cancel_scene_list_transfer();
            return dock_drop_result;
        }
        if button == 2 {
            let hit = input.hit_at(x, y).cloned();
            if input.modifiers.alt && self.claim_text_editor_alt_completions(x, y) {
                self.right_click = RightClickState { pending: true, x, y };
                return Ok(());
            }
            if let Some((window_id, body)) = hit.as_ref().and_then(|hit| self.retained_canvas2d_hit_window(hit, x, y)) {
                let scene_hit = hit.as_ref().expect("the retained Canvas2d owner was resolved from this hit");
                self.route_retained_pointer_press(&window_id, body, x, y, true, button, scene_hit.kind, scene_hit.event.clone(), pointer_id, input).await?;
            }
            self.open_context_menu(x, y, hit).await;
            self.right_click = RightClickState { pending: true, x, y };
            return Ok(());
        }
        if self.dismiss_overlays(x, y, input) {
            return Ok(());
        }
        if input.hit_at(x, y).is_none() && self.presented_input_geometry.dock_canvas_bounds.contains(x, y) {
            self.deactivate_active_window();
        }
        if let Some(hit) = input.hit_at(x, y).cloned() {
            if let Some((window_id, body)) = self.retained_hit_window(&hit) {
                self.begin_window_template_drag_from_hit(pointer_id, &hit, x, y);
                self.route_retained_pointer_press(&window_id, body, x, y, true, button, hit.kind, hit.event.clone(), pointer_id, input).await?;
                return Ok(());
            }
            if hit.kind == HitKind::PanelResize {
                if !self.claim_chrome_pointer(pointer_id) {
                    return Ok(());
                }
                if let Some(id) = hit.control_id.as_deref() {
                    if let Some(window_id) = id.strip_prefix("shell.measures.resize.") {
                        self.measures_resize_window_id = Some(window_id.to_string());
                        self.measures_resize_origin_width = *self.measures_width.get(window_id).unwrap_or(&Theme::default().window_measures_default_width);
                        input.begin_drag(x, y, button, hit.control_id.clone(), Some(DragAxis::Horizontal), Some(hit.kind));
                        return Ok(());
                    }
                }
                let body = self.body_rect(theme);
                let anchor = hit.control_id.as_deref().and_then(panel_resize_anchor).map(|(anchor, _)| anchor).unwrap_or(PanelAnchor::TopLeft);
                self.panel_resize_origin_width = floating_panel_width(self.anchor_state(anchor).size, body, theme);
                input.begin_drag(x, y, button, hit.control_id.clone(), Some(DragAxis::Horizontal), Some(hit.kind));
                return Ok(());
            }
            if matches!(hit.kind, HitKind::DockSplit | HitKind::DockJoinCorner) {
                if !self.claim_chrome_pointer(pointer_id) {
                    return Ok(());
                }
                self.deactivate_active_window();
                if let Some(id) = hit.control_id.as_deref() {
                    if let Some(rest) = id.strip_prefix("dock.corner.r/") {
                        if let Some((row_part, col_part)) = rest.split_once("/c/") {
                            if let Some((row_path_str, row_index_str)) = row_part.rsplit_once('/') {
                                if let Some((col_path_str, col_index_str)) = col_part.rsplit_once('/') {
                                    let row_path = parse_path(row_path_str);
                                    let col_path = parse_path(col_path_str);
                                    self.split_resize_path = Some(row_path.clone());
                                    self.split_resize_index = row_index_str.parse().unwrap_or(0);
                                    self.split_resize_secondary_path = Some(col_path.clone());
                                    self.split_resize_secondary_index = col_index_str.parse().unwrap_or(0);
                                    self.split_resize_origin = self.dock.begin_split_drag(&row_path);
                                    self.split_resize_secondary_origin = self.dock.begin_split_drag(&col_path);
                                    let geometry = &self.presented_input_geometry;
                                    self.split_resize_axis_total = self.dock.split_axis_extent(&row_path, geometry.dock_canvas_bounds, geometry.dock_axis_separator).unwrap_or(geometry.dock_canvas_bounds.w);
                                    self.split_resize_secondary_axis_total = self.dock.split_axis_extent(&col_path, geometry.dock_canvas_bounds, geometry.dock_axis_separator).unwrap_or(geometry.dock_canvas_bounds.h);
                                    input.begin_drag(x, y, button, Some(id.to_string()), Some(DragAxis::Both), Some(hit.kind));
                                    return Ok(());
                                }
                            }
                        }
                    }
                    if let Some(rest) = id.strip_prefix("dock.split.") {
                        if let Some((path_str, index_str)) = rest.rsplit_once('.') {
                            let path = parse_path(path_str);
                            let index: usize = index_str.parse().unwrap_or(0);
                            self.split_resize_path = Some(path.clone());
                            self.split_resize_index = index;
                            self.split_resize_origin = self.dock.begin_split_drag(&path);
                            let geometry = &self.presented_input_geometry;
                            self.split_resize_axis_total = self.dock.split_axis_extent(&path, geometry.dock_canvas_bounds, geometry.dock_axis_separator).unwrap_or_else(|| match hit.drag_axis {
                                Some(DragAxis::Vertical) => geometry.dock_canvas_bounds.h,
                                _ => geometry.dock_canvas_bounds.w,
                            });
                            input.begin_drag(x, y, button, Some(id.to_string()), hit.drag_axis, Some(hit.kind));
                            return Ok(());
                        }
                    }
                }
            }
            if self.begin_window_template_drag_from_hit(pointer_id, &hit, x, y) {
                return Ok(());
            }
            if let Some((item_id, drag_data)) = hit.control_id.as_deref().and_then(tree_hit_item_id).zip(hit.drag_data.clone()) {
                if !self.claim_chrome_pointer(pointer_id) {
                    return Ok(());
                }
                self.tree_drag_origin = (x, y);
                self.pending_tree_drag = Some((item_id.to_string(), drag_data));
                return Ok(());
            }
            if button == 0 && hit.control_id.as_deref().is_some_and(|id| ShellPaletteKind::row_index(id).is_some() || ShellPaletteKind::from_close_id(id).is_some()) {
                if !self.claim_chrome_pointer(pointer_id) {
                    return Ok(());
                }
                self.pending_chrome_release = hit.control_id.clone();
                return Ok(());
            }
            if self.handle_shell_hit(&hit, input).await? {
                if let Some(kind) = hit.control_id.as_deref().and_then(ShellPaletteKind::from_input_id) {
                    self.set_palette_query(kind, self.palette_query(kind).to_string(), input);
                } else if hit.control_id.as_deref().is_some_and(|id| matches!(id, "ui.search.toggle" | "ui.find.toggle")) {
                    if let Some(kind) = match self.overlay_state {
                        OverlayState::Search => Some(ShellPaletteKind::Search),
                        OverlayState::Find => Some(ShellPaletteKind::Find),
                        _ => None,
                    } {
                        self.set_palette_query(kind, self.palette_query(kind).to_string(), input);
                    } else {
                        input.blur_input();
                        self.accessibility_focused_control_id = None;
                    }
                } else if ShellPaletteKind::row_index(hit.control_id.as_deref().unwrap_or_default()).is_some() {
                    input.blur_input();
                    self.accessibility_focused_control_id = None;
                }
                return Ok(());
            }
            if let Some(id) = hit.control_id.as_deref() {
                if let Some(window_id) = dock_tab_select_window_id(id) {
                    if !self.claim_chrome_pointer(pointer_id) {
                        return Ok(());
                    }
                    self.pending_chrome_release = hit.control_id.clone();
                    return Ok(());
                }
                if let Some(rest) = id.strip_prefix("dock.tab.").and_then(|rest| rest.strip_suffix(".drag")) {
                    if let Some((path_str_value, window_id)) = rest.split_once('.') {
                        let path = parse_path(path_str_value);
                        let tab_index = self.dock.tab_index(&path, window_id).unwrap_or(0);
                        let window_kind_id = self.dock.window_kind_id(window_id).unwrap_or(window_id).to_string();
                        let template_id = self.dock.window_template_id(window_id).map(str::to_string);
                        let ghost_label =
                            self.session.as_ref().and_then(|s| s.app.window_kinds.iter().find(|k| k.id == window_kind_id).map(|k| k.label.resolve(self.active_terminology(), self.active_locale()).to_string())).unwrap_or_else(|| window_id.to_string());
                        self.begin_pending_dock_drag(pointer_id, DockDragPayload { kind: DockDragKind::Tab, window_id: window_id.to_string(), window_kind_id, template_id, source_path: path, tab_index, ghost_label }, x, y);
                        return Ok(());
                    }
                }
                if let Some(path_str_value) = id.strip_prefix("dock.stack.") {
                    let path = parse_path(path_str_value);
                    let windows = self.dock.stack_windows_at_path(&path).unwrap_or_default();
                    let active = windows.iter().find(|wid| self.active_window_id.as_deref() == Some(wid.as_str())).or_else(|| windows.first()).cloned().unwrap_or_default();
                    if !active.is_empty() {
                        let tab_index = self.dock.tab_index(&path, &active).unwrap_or(0);
                        let window_kind_id = self.dock.window_kind_id(&active).unwrap_or(&active).to_string();
                        let ghost_label =
                            self.session.as_ref().and_then(|s| s.app.window_kinds.iter().find(|k| k.id == window_kind_id).map(|k| k.label.resolve(self.active_terminology(), self.active_locale()).to_string())).unwrap_or_else(|| active.clone());
                        self.begin_pending_dock_drag(pointer_id, DockDragPayload { kind: DockDragKind::Stack, window_id: active, window_kind_id, template_id: None, source_path: path, tab_index, ghost_label }, x, y);
                        return Ok(());
                    }
                }
            }
            if hit.kind == HitKind::PanelTab {
                if let Some((tab_id, anchor)) = hit.control_id.as_deref().and_then(|id| Some((id.to_string(), self.panel_tab_anchor(id)?))) {
                    if !self.claim_chrome_pointer(pointer_id) {
                        return Ok(());
                    }
                    self.dock_tab_drag = Some((tab_id, anchor));
                    input.begin_drag(x, y, button, hit.control_id.clone(), Some(DragAxis::Both), Some(hit.kind));
                }
            }
            if hit.kind == HitKind::Slider {
                if let Some(id) = hit.control_id.clone() {
                    if !self.claim_chrome_pointer(pointer_id) {
                        return Ok(());
                    }
                    input.begin_drag(x, y, button, Some(id), hit.drag_axis, Some(hit.kind));
                    return Ok(());
                }
            }
            if hit.kind == HitKind::Select || hit.kind == HitKind::Toggle || hit.kind == HitKind::DropdownItem {
                return Ok(());
            }
            if let Some(id) = hit.control_id.as_deref() {
                if id.contains(".vfs.") && !id.contains(".chevron.") {
                    if let Some((surface_id, row_id)) = id.rsplit_once(".vfs.") {
                        let additive = input.modifiers.meta || input.modifiers.ctrl;
                        let shift = input.modifiers.shift;
                        let ordered = vec![row_id.to_string()];
                        let ids = vfs_selection_for_click(surface_id, row_id, &ordered, shift, additive);
                        self.dispatch_action(ActionDescriptor {
                            controller_id: self.session.as_ref().map(|s| s.app.controller_id.clone()).unwrap_or_default(),
                            action: "selectRows".into(),
                            args: crate::action_args_json!({ "surfaceId": surface_id, "ids": ids }),
                        })
                        .await?;
                        return Ok(());
                    }
                }
            }
            if let Some(action) = hit.event.clone() {
                self.dispatch_action(action).await?;
            } else if hit.kind == HitKind::Input {
                if let Some(id) = hit.control_id {
                    let seed = ShellPaletteKind::from_input_id(&id).map(|kind| self.palette_query(kind).to_string()).or_else(|| self.widget_maps.input_metas.get(&id).map(|meta| meta.value.clone())).unwrap_or_default();
                    input.focus_input_owned(id, seed);
                }
            }
        }
        self.drain_gesture_bound_work().await;
        self.owe_settle();
        Ok(())
    }

    pub fn handle_pointer_move(&mut self, x: f32, y: f32, down: bool, input: &mut InputState<ActionDescriptor>, theme: &Theme) {
        self.handle_pointer_move_for(ui_render::PointerId(1), x, y, down, input, theme);
    }

    /// 🖱️ The two ghost-preview syncs take `&mut self` (`sync_world3d_catalogue_drop_preview` walks
    /// `world3d_states`), so the drag's own payload is snapshotted first and the `&mut self.tree_drag`
    /// borrow is re-taken afterwards — the previous shape held both at once and did not compile.
    ///
    /// 📱️ Below React's breakpoint a tab cannot travel at all — the dock context hands
    /// `startTabDrag: mobile ? noopDrag : startTabDrag` (`🖱️ui/🧱️elements/🎨️Canvas/🟦️.tsx:1852`),
    /// because a mobile mode is ONE flat stack with nothing to drop into.
    ///
    /// 🩸️ Promotion used to REMOVE the dragged window from the committed tree here; it is now a
    /// pure state transition and the removal lives in `DockState::render_view`'s derivation.
    ///
    /// ↔ `delta_factor` from React's `PanelResizeHandle`: an outer (canvas-facing) handle
    /// grows the panel with the pointer, an inner one against it, and a centred
    /// middle-column panel grows from both edges at once, hence the doubled step.
    pub fn handle_pointer_move_for(&mut self, pointer_id: ui_render::PointerId, x: f32, y: f32, down: bool, input: &mut InputState<ActionDescriptor>, theme: &Theme) {
        if self.chrome_pointer_owner.is_some_and(|owner| owner != pointer_id) {
            return;
        }
        input.pointer_x = x;
        input.pointer_y = y;
        input.pointer_down = down;
        self.presence_pointer = Some((x, y));
        input.update_hover(x, y);
        if let Some((kind, index)) = input.hovered_id.as_deref().and_then(ShellPaletteKind::row_index) {
            match kind {
                ShellPaletteKind::Search => self.search_selected = index,
                ShellPaletteKind::Find => self.find_selected = index,
            }
        }
        self.route_retained_pointer_move(pointer_id, x, y, input);
        self.sync_context_menu_hover(input);
        self.update_tree_hover(input);
        if let Some((ref item_id, ref drag_data)) = self.pending_tree_drag {
            if down {
                let dx = x - self.tree_drag_origin.0;
                let dy = y - self.tree_drag_origin.1;
                if self.tree_drag.is_none() && (dx * dx + dy * dy) > 25.0 {
                    self.tree_drag = Some(TreeDragState { source_id: item_id.clone(), drag_data: drag_data.clone(), x, y, drop_target_id: None, drop_position: TreeDropPosition::Inside });
                    self.pending_tree_drag = None;
                }
            }
        }
        let tree_drag_payload = self.tree_drag.as_mut().map(|drag| {
            drag.x = x;
            drag.y = y;
            drag.drag_data.clone()
        });
        if let Some(ref drag_data) = tree_drag_payload {
            let graph_surfaces = self.node_graph_states.iter().map(|(id, surface)| (id.as_str(), surface.bounds)).collect::<Vec<_>>();
            crate::engine_canvas::node_graph_sync_flow_widget_ghost(x, y, drag_data, &graph_surfaces);
            drop(graph_surfaces);
            self.sync_world3d_catalogue_drop_preview(x, y, drag_data);
        } else {
            self.sync_world3d_catalogue_drop_preview_from_retained_ui();
        }
        let retained_drag_data = tree_drag_payload
            .is_none()
            .then(|| crate::interpreter::active_retained_drag_sessions())
            .and_then(|sessions| sessions.into_iter().map(|(_, _, _, drag_data)| drag_data).find(|drag_data| drag_data.contains_key(crate::scenes::CANVAS_CATALOGUE_DRAG_MIME)));
        if let Some(drag_data) = tree_drag_payload.as_ref().or(retained_drag_data.as_ref()) {
            self.sync_canvas2d_catalogue_drag(x, y, drag_data, input);
        } else {
            crate::scenes::cancel_canvas_catalogue_drag(input);
        }
        if let Some(drag) = &mut self.tree_drag {
            if let Some(hit) = input.hit_at(x, y) {
                if let Some(target_id) = hit.control_id.as_deref().and_then(tree_hit_item_id) {
                    drag.drop_target_id = Some(target_id.to_string());
                    let rel = (y - hit.rect.y) / hit.rect.h.max(1.0);
                    drag.drop_position = if rel < 0.25 {
                        TreeDropPosition::Before
                    } else if rel > 0.75 {
                        TreeDropPosition::After
                    } else {
                        TreeDropPosition::Inside
                    };
                } else if hit.kind == HitKind::World3d || hit.kind == HitKind::Window {
                    drag.drop_target_id = hit.control_id.clone();
                    drag.drop_position = TreeDropPosition::Inside;
                } else {
                    drag.drop_target_id = None;
                }
            }
        }
        if let Some((payload, origin)) = &self.pending_dock_drag {
            if down && !self.dock.mobile {
                let dx = x - origin.0;
                let dy = y - origin.1;
                if self.dock_drag.is_none() && (dx * dx + dy * dy) > 25.0 {
                    let payload = payload.clone();
                    let origin = *origin;
                    self.pending_dock_drag = None;
                    self.dock_drag = Some(DockDragState { payload, x: origin.0, y: origin.1, drop_zone: None });
                }
            }
        }
        if let Some(drag) = &mut self.dock_drag {
            drag.x = x;
            drag.y = y;
            let geometry = &self.presented_input_geometry;
            drag.drop_zone = compute_dock_drop_zone(x, y, &geometry.dock_drop_tab_bars, &geometry.dock_drop_bodies, geometry.dock_canvas_bounds);
        }
        if input.drag.active && down {
            input.update_drag(x, y);
            if let Some(id) = input.drag.target_id.as_deref() {
                let dx = x - input.drag.start_x;
                let dy = y - input.drag.start_y;
                match id {
                    id if id.starts_with("shell.measures.resize.") => {
                        if let Some(window_id) = self.measures_resize_window_id.clone() {
                            let next = (self.measures_resize_origin_width - dx).clamp(theme.panel_min_width, theme.panel_max_width);
                            self.measures_width.insert(window_id, next);
                        }
                    }
                    id if id.starts_with("panel.resize.") => {
                        if let Some((anchor, inner)) = panel_resize_anchor(id) {
                            let body = self.body_rect(theme);
                            let factor = if anchor.horizontal() == "middle" { 2.0 } else { 1.0 } * if inner { -1.0 } else { 1.0 };
                            let next = (self.panel_resize_origin_width + dx * factor).clamp(theme.panel_min_width, floating_panel_max_width(body, theme));
                            self.anchor_state_mut(anchor).size = next;
                        }
                    }
                    dock_id if dock_id.starts_with("dock.corner.") => {
                        if let Some(path) = self.split_resize_path.clone() {
                            self.dock.apply_split_drag_with_origin(&path, self.split_resize_index, dx, self.split_resize_axis_total, &self.split_resize_origin);
                        }
                        if let Some(path) = self.split_resize_secondary_path.clone() {
                            self.dock.apply_split_drag_with_origin(&path, self.split_resize_secondary_index, dy, self.split_resize_secondary_axis_total, &self.split_resize_secondary_origin);
                        }
                    }
                    dock_id if dock_id.starts_with("dock.split.") => {
                        if let (Some(path), axis) = (&self.split_resize_path, input.drag.axis) {
                            let delta = match axis {
                                Some(DragAxis::Horizontal) => dx,
                                Some(DragAxis::Vertical) => dy,
                                _ => dx,
                            };
                            self.dock.apply_split_drag_with_origin(path, self.split_resize_index, delta, self.split_resize_axis_total, &self.split_resize_origin);
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    /// 🎯️ An abandoned or refused drop is simply nothing: the committed tree was never touched, so
    /// there is no snapshot to re-apply and no `sync_dock` to pay for.
    async fn finish_dock_drag(&mut self, x: f32, y: f32, input: &InputState<ActionDescriptor>) -> Result<(), String> {
        let Some(mut drag) = self.dock_drag.take() else {
            return Ok(());
        };
        drag.x = x;
        drag.y = y;
        if drag.drop_zone.is_none() {
            let geometry = &self.presented_input_geometry;
            drag.drop_zone = compute_dock_drop_zone(x, y, &geometry.dock_drop_tab_bars, &geometry.dock_drop_bodies, geometry.dock_canvas_bounds);
        }
        if let Some(zone) = drag.drop_zone {
            let body_key = self.session.as_ref().and_then(|session| session.app.window_kinds.iter().find(|kind| kind.id == drag.payload.window_kind_id)).map(|kind| kind.body_key.clone());
            if body_key.is_some() && !self.window_topology_publication_has_credit() {
                return Err("window topology publication item credits exceeded".to_string());
            }
            let controller_id = self.shell_command_controller_id();
            if controller_id.is_some() && body_key.is_none() {
                return Err(format!("window kind '{}' has no retained body", drag.payload.window_kind_id));
            }
            let journal_token = if let Some(controller_id) = controller_id {
                let (command_id, label, detail) = if drag.payload.kind == DockDragKind::NewWindow {
                    ("shell.windowSplit", shell_chrome_string("command.splitWindow", self.locale_id == "de"), serde_json::json!({ "windowKindId": drag.payload.window_kind_id, "instanceId": drag.payload.window_id }))
                } else {
                    ("shell.windowMove", shell_chrome_string("command.moveWindow", self.locale_id == "de"), serde_json::json!({ "windowId": drag.payload.window_id }))
                };
                let note = Self::note_shell_command_action(&controller_id, command_id, label, Some(detail));
                Some(self.reserve_window_topology_action(note).map_err(|error| format!("window topology journal refused admission before dock mutation: {error:?}"))?)
            } else {
                None
            };
            if !self.dock.apply_drop(&drag.payload, &zone) {
                if let Some(token) = journal_token {
                    let _ = self.take_window_topology_action(token);
                }
                return Ok(());
            }
            if drag.payload.kind == DockDragKind::NewWindow {
                self.seed_new_window_projection(&drag.payload.window_id, drag.payload.template_id.as_deref());
            }
            self.active_window_id = Some(drag.payload.window_id.clone());
            self.dock.sync_active_window(&drag.payload.window_id);
            self.persist_dock_layout();
            if let Some(body_key) = body_key.as_deref() {
                self.commit_window_topology_publication(&drag.payload.window_id, body_key, journal_token);
            } else {
                self.owe_window_topology_refresh();
            }
        }
        let _ = input;
        Ok(())
    }

    //#region 🎯️RetainedPointerRouting
    /// 🎯️ The retained window body that minted `hit`, with the body rect the registry was minted
    /// against — `None` for every chrome target. See `retained_hit_windows`.
    fn retained_hit_window(&self, hit: &HitTarget<ActionDescriptor>) -> Option<(String, Rect)> {
        self.retained_hit_windows.get(hit.control_id.as_deref()?).cloned()
    }

    /// 🎬️ Admits only the exact published scene hit while its originating surface remains live.
    fn retained_scene_hit_is_live(&self, hit: &HitTarget<ActionDescriptor>, x: f32, y: f32) -> bool {
        use ui_wgpu::wgpu::SurfaceKind;
        let Some(control) = hit.control_id.as_deref() else { return false };
        let Some((rect, scene)) = self.retained_scene_hits.get(control) else { return false };
        let window = &scene.window_id;
        if *rect != hit.rect || !rect.contains(x, y) || !self.retained_hit_windows.get(control).is_some_and(|(owner, body)| owner == window && body.contains(x, y)) {
            return false;
        }
        let kind_matches = match scene.kind {
            SurfaceKind::World3d => hit.kind == HitKind::World3d,
            SurfaceKind::NodeGraph | SurfaceKind::Board2d | SurfaceKind::TiledMap => hit.kind == HitKind::ScrollRegion,
            _ => false,
        };
        kind_matches && crate::interpreter::scene_pointer_target_is_live(scene)
    }

    /// 🖼️ Resolves the exact live Canvas2d scene beneath a secondary press before its context menu opens.
    fn retained_canvas2d_hit_window(&self, hit: &HitTarget<ActionDescriptor>, x: f32, y: f32) -> Option<(String, Rect)> {
        let control = hit.control_id.as_deref()?;
        let scene_entry = self.retained_scene_hits.get(control);
        let owner_entry = self.retained_hit_windows.get(control);
        let live = owner_entry.and_then(|(window_id, body)| crate::interpreter::retained_scene_target_at(window_id, x - body.x, y - body.y));
        let (rect, scene) = scene_entry?;
        let (window_id, body) = owner_entry?;
        let live = live?;
        (*rect == hit.rect && rect.contains(x, y) && body.contains(x, y) && scene.kind == ui_wgpu::wgpu::SurfaceKind::Canvas2d && scene.window_id == *window_id && live.kind == ui_wgpu::wgpu::SurfaceKind::Canvas2d && live == *scene)
            .then(|| (window_id.clone(), *body))
    }

    /// 🧭️ A retained panel tab owns pointer routing but is not an application window instance.
    /// 🧭️ Whether a retained surface is shell chrome rather than a plugin window: a panel open in an
    /// anchor, or any shell-owned leaf wherever it is shown (the `/hub` workspace overlay is the
    /// `framework.hub` leaf with no anchor). Focusing or pressing chrome never makes it the active
    /// window — every plugin action resolves its window kind from `active_window_id`, and a chrome id
    /// there has none, which faulted the frame.
    fn retained_surface_is_panel(&self, surface_id: &str) -> bool {
        self.open_anchors().into_iter().any(|anchor| self.anchor_state(anchor).active_tab() == Some(surface_id)) || self.shell_owned_panel_leaves().iter().any(|leaf| leaf == surface_id)
    }

    /// 🎯️ Publishes one retained body's own registry into the host's `InputState` and remembers who
    /// minted each id. Called by every body that paints a retained document — a dock window and a
    /// panel alike — right after its paint, so the entries land above the window region the chrome
    /// registered before it.
    fn register_retained_body_hits(&mut self, window_id: &str, body: Rect, input: &mut InputState<ActionDescriptor>) {
        if let Some((_, rect)) = self.retained_body_rects_staging.iter_mut().find(|(id, _)| id == window_id) {
            *rect = body;
        } else if self.retained_body_rects_staging.len() < 256 {
            self.retained_body_rects_staging.push((window_id.to_string(), body));
        }
        crate::interpreter::note_accessibility_visible_document(window_id);
        for (control_id, scene, rect) in crate::interpreter::register_clipped_retained_hit_targets(window_id, body, input) {
            if let Some(scene) = scene {
                self.retained_scene_hits_staging.insert(control_id.clone(), (rect, scene));
            } else {
                self.retained_scene_hits_staging.remove(&control_id);
            }
            self.retained_hit_windows_staging.insert(control_id, (window_id.to_string(), body));
        }
    }

    /// 🎬️ Publishes accepted media geometry only in the browser host that owns a DOM player.
    pub(crate) fn presented_media_slots(&self) -> Vec<crate::media_slots::PresentedMediaSlot> {
        #[cfg(target_arch = "wasm32")]
        {
            let geometry = &self.presented_input_geometry;
            let mut slots = crate::interpreter::presented_media_slots(&geometry.retained_body_rects, &geometry.retained_surfaces, &geometry.media_owners, &geometry.panel_rects, &geometry.dock_window_plan);
            if geometry.media_blocked {
                for slot in &mut slots { slot.occluded = true; }
            }
            slots
        }
        #[cfg(not(target_arch = "wasm32"))]
        Vec::new()
    }

    /// 🧭 Resolves one timer owner from this shell's GPU-accepted retained surface roster.
    pub(crate) fn retained_clock_surface(&self, index: usize) -> Option<(&str, ui_wgpu::wgpu::UiSurfaceToken)> {
        self.presented_input_geometry.retained_surfaces.get(index).map(|(id, surface)| (id.as_str(), *surface))
    }

    pub(crate) fn presented_retained_clock_deadline(&self) -> Option<f64> {
        crate::interpreter::presented_retained_clock_deadline(&self.presented_input_geometry.retained_surfaces)
    }

    /// 🪪️ Refreshes bounded app ownership independently from authored media resources.
    async fn refresh_app_document_identity(&mut self, program: &ProgramBridgeEntry, instance_id: u32) -> Result<(), String> {
        let key = (program.plugin_id.clone(), instance_id);
        let spawned = self.session.as_ref().and_then(|session| Self::panel_state_from_view(&session.view_state).ok().flatten()).map(|panel| panel.spawned_apps).unwrap_or_default();
        let active = self.session.as_ref().map(|session| (session.plugin_id.clone(), session.instance_id));
        let mounted = self.spawned_session.as_ref().map(|session| (session.plugin_id.clone(), session.instance_id));
        self.app_document_identities.retain(|owner| Some(owner) == active.as_ref() || Some(owner) == mounted.as_ref() || *owner == key || spawned.iter().any(|app| app.plugin_id == owner.0 && app.instance_id == owner.1));
        let request = self.app_document_identities.begin(key.clone()).ok_or_else(|| "app document identity registry request authority unavailable".to_string())?;
        let identity = match program.read_app_document_identity(instance_id).await {
            Ok(identity) => identity,
            Err(error) => {
                self.app_document_identities.remove(&key);
                return Err(error);
            }
        };
        if !self.app_document_identities.accept(&key, request, identity.app_instance_id, identity.parent_document_id) {
            return Err("app document identity reply is stale or foreign".into());
        }
        Ok(())
    }

    fn media_owner_for_session(&self, session: &ActiveSession) -> Option<crate::media_slots::PresentedMediaOwner> {
        let parent_document_id = self.app_document_identities.document(&(session.plugin_id.clone(), session.instance_id))?.to_string();
        Some(crate::media_slots::PresentedMediaOwner { plugin_id: session.plugin_id.clone(), controller_id: session.app.controller_id.clone(), app_instance_id: session.instance_id, parent_document_id })
    }

    fn candidate_input_geometry(&self, theme: &Theme) -> PresentedInputGeometry {
        let body = self.body_rect(theme);
        let panel_rects = PanelAnchor::ALL.into_iter().filter(|anchor| self.anchor_open(*anchor)).map(|anchor| self.anchor_rect(anchor, body, theme)).collect();
        let active_owner = self.session.as_ref().and_then(|session| self.media_owner_for_session(session));
        let spawned_owner = self.spawned_session.as_ref().and_then(|session| self.media_owner_for_session(session));
        let spawned = self.session.as_ref().and_then(|session| Self::panel_state_from_view(&session.view_state).ok().flatten()).map(|panel| panel.spawned_apps).unwrap_or_default();
        let media_owners = self.retained_body_rects_staging.iter().map(|(id, _)| {
            let owner = if id == "spawned" || spawned.iter().any(|app| &app.id == id) { spawned_owner.clone() } else { active_owner.clone() };
            (id.clone(), owner)
        }).collect();
        let media_blocked = self.candidate_pointer_input_is_modal() || self.overlay_state != OverlayState::None || self.sync_card_kind.is_some() || self.dock_drag.is_some()
            || self.chrome_build.tooltip_hover.as_ref().is_some_and(|hover| self.chrome_build.tooltip_shows(false) && chrome_tooltip_ready(hover, chrome_now_ms()));
        PresentedInputGeometry {
            retained_body_rects: self.retained_body_rects_staging.clone(),
            media_owners,
            media_blocked,
            retained_surfaces: crate::interpreter::staged_retained_clock_surfaces(),
            dock_canvas_bounds: self.dock_canvas_bounds,
            dock_axis_separator: self.dock_axis_separator,
            dock_drop_tab_bars: self.dock_drop_tab_bars.clone(),
            dock_drop_bodies: self.dock_drop_bodies.clone(),
            dock_window_plan: self.dock_window_plan.clone(),
            window_content_rects: self.window_content_rects.clone(),
            window_silhouettes: self.window_silhouettes.clone(),
            modal: self.candidate_pointer_input_is_modal(),
            panel_rects,
        }
    }

    /// 🎞️ Seals the hit, owner, widget-binding and geometry candidates minted by one completed
    /// chrome walk. They remain non-interactive until the matching GPU packet is acknowledged.
    pub(crate) fn seal_presented_input_candidate(&mut self, theme: &Theme) -> Result<PresentedInputCandidateWitness, &'static str> {
        let epoch = self.next_presented_input_epoch.ok_or("presented input candidate generation exhausted")?;
        self.next_presented_input_epoch = epoch.checked_add(1);
        let witness = PresentedInputCandidateWitness(epoch);
        self.presented_input_geometry_staging = self.candidate_input_geometry(theme);
        self.presented_input_candidate = Some(witness);
        if !crate::interpreter::seal_presented_input_candidate(witness.0) {
            self.presented_input_candidate = None;
            return Err("retained presented input candidate could not be sealed");
        }
        crate::scenes::seal_host_temporal_candidates(witness.0);
        crate::scenes::seal_table_stepper_accessibility_candidates(witness.0);
        crate::scenes::seal_table_editable_text_accessibility_candidates(witness.0);
        crate::scenes::seal_table_button_accessibility_candidates(witness.0);
        crate::scenes::seal_vfs_accessibility_candidates(witness.0);
        crate::scenes::seal_block_list_accessibility_candidates(witness.0);
        crate::scenes::seal_event_feed_accessibility_candidates(witness.0);
        crate::scenes::seal_graph_timeline_accessibility_candidates(witness.0);
        Ok(witness)
    }

    pub(crate) fn presented_input_candidate_matches(&self, witness: PresentedInputCandidateWitness) -> bool {
        self.presented_input_candidate == Some(witness) && crate::interpreter::presented_input_candidate_matches(witness.0)
    }

    pub(crate) fn progress_presented_input_candidate(&self, input: &mut InputState<ActionDescriptor>, witness: PresentedInputCandidateWitness) -> crate::interpreter::PresentedInputCandidateProgress {
        if self.presented_input_candidate != Some(witness) {
            return crate::interpreter::PresentedInputCandidateProgress::Stale;
        }
        crate::interpreter::progress_presented_input_candidate(witness.0, input)
    }

    /// 🏁️ Promotes one GPU-accepted frame's complete input authority in one runtime lock. The chrome's
    /// accessibility publication is replaced (and its generation advanced) only when its projection
    /// changed, so the mirror's addresses stay valid across frames that present the same chrome.
    ///
    /// ♿️ The chrome's accessible names ride the SAME promotion as its hit registry (packet W15d)
    /// — a production path, not a diagnostics one, so an assistive technology reads the chrome
    /// whether or not `SEMIO_RUNTIME_DIAGNOSTICS` is armed.
    pub(crate) fn acknowledge_presented_input(&mut self, input: &mut InputState<ActionDescriptor>, witness: PresentedInputCandidateWitness) -> bool {
        if !self.presented_input_candidate_matches(witness) {
            return false;
        }
        if !crate::interpreter::acknowledge_presented_input(witness.0) {
            return false;
        }
        crate::scenes::acknowledge_host_temporal_candidates(witness.0);
        crate::scenes::acknowledge_table_stepper_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_table_editable_text_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_table_button_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_vfs_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_block_list_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_event_feed_accessibility_candidates(witness.0);
        crate::scenes::acknowledge_graph_timeline_accessibility_candidates(witness.0);
        std::mem::swap(&mut self.retained_hit_windows, &mut self.retained_hit_windows_staging);
        std::mem::swap(&mut self.retained_scene_hits, &mut self.retained_scene_hits_staging);
        std::mem::swap(&mut self.widget_maps, &mut self.widget_maps_staging);
        std::mem::swap(&mut self.presented_input_geometry, &mut self.presented_input_geometry_staging);
        input.publish_hits();
        self.presented_input_epoch = witness.0;
        self.presented_input_candidate = None;
        crate::interpreter::publish_accessibility_visible_documents();
        self.resolve_time_travel_focus(input);
        let chrome_accessibility = self.chrome_accessibility_nodes(input.hits());
        let focus_changed = self.presented_chrome_accessibility.iter_mut().zip(&chrome_accessibility).fold(false, |changed, (previous, current)| {
            let focus_changed = previous.focused != current.focused;
            previous.focused = current.focused;
            changed || focus_changed
        });
        let authority_changed = self.presented_chrome_accessibility_generation == 0 || chrome_accessibility != self.presented_chrome_accessibility;
        if authority_changed {
            self.presented_chrome_accessibility = chrome_accessibility;
            self.presented_chrome_accessibility_generation = witness.0;
        }
        if authority_changed || focus_changed {
            crate::interpreter::note_chrome_accessibility(self.presented_chrome_accessibility_generation, self.presented_chrome_accessibility.clone());
        }
        crate::interpreter::note_chrome_hit_registry(input.hits(), &self.retained_hit_windows);
        crate::interpreter::note_chrome_surfaces(&self.chrome_surface_census());
        #[cfg(not(target_arch = "wasm32"))]
        crate::native_accessibility::publish_native_accessibility(crate::native_accessibility::NativeAccessibilityPublication { title: crate::boot_window_title(), windows: crate::interpreter::native_accessibility_windows() });
        true
    }

    pub(crate) fn discard_presented_input_candidate(&mut self, witness: PresentedInputCandidateWitness) -> bool {
        if self.presented_input_candidate != Some(witness) {
            return false;
        }
        if !crate::interpreter::discard_presented_input_candidate(witness.0) {
            return false;
        }
        crate::scenes::discard_host_temporal_candidates(witness.0);
        crate::scenes::discard_table_stepper_accessibility_candidates(witness.0);
        crate::scenes::discard_table_editable_text_accessibility_candidates(witness.0);
        crate::scenes::discard_table_button_accessibility_candidates(witness.0);
        crate::scenes::discard_vfs_accessibility_candidates(witness.0);
        crate::scenes::discard_block_list_accessibility_candidates(witness.0);
        crate::scenes::discard_event_feed_accessibility_candidates(witness.0);
        crate::scenes::discard_graph_timeline_accessibility_candidates(witness.0);
        self.presented_input_candidate = None;
        true
    }

    #[cfg(test)]
    fn publish_retained_hit_registry(&mut self, input: &mut InputState<ActionDescriptor>) {
        self.publish_retained_input_for_test(input, &Theme::default());
    }

    #[cfg(test)]
    fn publish_retained_input_for_test(&mut self, input: &mut InputState<ActionDescriptor>, theme: &Theme) {
        let witness = self.seal_presented_input_candidate(theme).expect("test input candidate witness");
        assert!(self.acknowledge_presented_input(input, witness));
    }

    /// 🪟️ Every surface this frame carries, at the LEVEL React's DOM states through `data-level` and
    /// under React's OWN element id — the census `dumpChrome` publishes beside the hit registry.
    ///
    /// ⚖️ Three levels, because React's shell has three: a window instance the dock planned, a DOCKED
    /// PANEL (one per open anchor — its active tab, named `panelTabElementId(tabId)`) and a dialog
    /// that owns the screen. This renderer models a panel AS a window instance, so a probe reading
    /// only window ids saw every panel a step opened as a new WINDOW where React reported a panel,
    /// and no panel step could match (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY,
    /// `📓️w9c-behaviour-parity-run-2.md` steps 3–8).
    fn chrome_surface_census(&self) -> Vec<(String, &'static str, String)> {
        let mut rows: Vec<(String, &'static str, String)> = self.dock_window_plan.iter().map(|(window_id, _)| (window_id.clone(), "window", window_id.clone())).collect();
        rows.extend(self.open_anchors().into_iter().filter_map(|anchor| self.anchor_state(anchor).active_tab().map(|tab| (tab.to_string(), "panel", panel_tab_introduction_element_id(tab)))));
        if self.chrome_build.tour_state.is_some() {
            rows.push((UI_INTRODUCTION_DIALOG_ELEMENT_ID.to_string(), "dialog", UI_INTRODUCTION_DIALOG_ELEMENT_ID.to_string()));
        }
        if let Some(request) = self.chrome_build.dialog_stack.last() {
            rows.push((request.accessibility_key(), "dialog", request.accessibility_key()));
        }
        if let Some(kind) = match self.overlay_state {
            OverlayState::Search => Some(ShellPaletteKind::Search),
            OverlayState::Find => Some(ShellPaletteKind::Find),
            _ => None,
        } {
            rows.push((kind.dialog_id().to_string(), "dialog", kind.dialog_id().to_string()));
        }
        rows
    }

    /// ⌨️🖱️ The live modifier set the retained router's POINTER events carry — the aggregate
    /// `InputState::modifiers` the ingress refreshes on every pointer and key event, projected onto
    /// `events`' own type. React reads the very same four flags straight off the DOM `PointerEvent`
    /// (`⚙️VirtualFileSystem/🟦️.tsx:520-521`), so a retained press that dropped them could never
    /// express shift-extend or ctrl-toggle on any list surface
    /// (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY, `📓️audit-w14-scenes-residual.md` C1).
    fn retained_event_modifiers(input: &InputState<ActionDescriptor>) -> ui_wgpu::wgpu::EventModifiers {
        ui_wgpu::wgpu::EventModifiers { shift: input.modifiers.shift, ctrl: input.modifiers.ctrl, alt: input.modifiers.alt, meta: input.modifiers.meta }
    }

    /// 🖱️ DOM-standard `MouseEvent.button` code onto the retained event's own button identity.
    fn retained_pointer_button(button: i16) -> ui_wgpu::wgpu::PointerButton {
        match button {
            1 => ui_wgpu::wgpu::PointerButton::Middle,
            2 => ui_wgpu::wgpu::PointerButton::Secondary,
            _ => ui_wgpu::wgpu::PointerButton::Primary,
        }
    }

    /// 👆️ Routes a pointer move over a retained window body into that body's own
    /// `events::EventRouter` — the ONE owner of `NodeFlags::HOVERED`, the hover bubble chain and the
    /// per-surface `UiCommand::Scene` lane. Coordinates are window-local, because the retained tree's
    /// root sits at its own origin while the flat registry above is page-space.
    ///
    /// 🖱️ A live gesture keeps its window until release, the way a browser keeps a captured
    /// pointer with the element that captured it — otherwise a `Slider`/`Ring` drag froze the
    /// instant the pointer left the control's own rect and the registry answered something else.
    ///
    /// 👋️ The body that last owned the hover must be told about the move that LEAVES it. Routing
    /// only the moves that land ON a retained target left `NodeFlags::HOVERED` set forever on the
    /// last row the pointer touched — the router is edge-triggered on the move it receives, so a
    /// move it never receives is a hover it never clears (measured on 6118: hovering
    /// `Add Generation` then moving 300 px away left all three nodes of its bubble chain hovered,
    /// `📓️wgpu-input-hit-runtime-2026-09-13.md` §10.2). The leave carries the pointer's REAL
    /// window-local coordinates, so `events::hit_test` resolves what is actually under it —
    /// nothing, or a plain container — and `update_hover` clears the chain by its own rule. No
    /// sentinel coordinate, and no second notion of "outside".
    fn route_retained_pointer_move(&mut self, pointer_id: ui_render::PointerId, x: f32, y: f32, input: &mut InputState<ActionDescriptor>) {
        let captured = crate::interpreter::retained_pointer_capture_window(pointer_id).and_then(|window_id| self.retained_window_body_rect(&window_id).map(|body| (window_id, body)));
        let current = captured.or_else(|| input.hit_at(x, y).cloned().and_then(|hit| self.retained_hit_window(&hit)));
        if let Some(previous) = self.retained_hover_window.clone() {
            if current.as_ref().map(|(window_id, _)| window_id.as_str()) != Some(previous.as_str()) {
                if let Some(body) = self.retained_window_body_rect(&previous) {
                    let _ = crate::interpreter::dispatch_ui_pointer_event(&previous, pointer_id, ui_wgpu::wgpu::UiEvent::PointerMove { x: x - body.x, y: y - body.y, modifiers: Self::retained_event_modifiers(input) }, input);
                }
            }
        }
        self.retained_hover_window = current.as_ref().map(|(window_id, _)| window_id.clone());
        let Some((window_id, body)) = current else { return };
        let _ = crate::interpreter::dispatch_ui_pointer_event(&window_id, pointer_id, ui_wgpu::wgpu::UiEvent::PointerMove { x: x - body.x, y: y - body.y, modifiers: Self::retained_event_modifiers(input) }, input);
    }

    /// 👆️ A press on a retained body target. A control the retained router itself owns (a text
    /// `Input`'s focus, a `Select`'s popup and options, a tree row's selection or drag handle) is routed there;
    /// everything else dispatches the action the node's own spec declared through the
    /// same `dispatch_action` funnel every chrome hit uses, so a document row and a chrome row are
    /// one dispatch path.
    ///
    /// 🎛️ EVERY retained interactive control routes into the retained router, which is the ONE
    /// authority that turns a press on one into its own guest action (`events`' 🔖️Commit region)
    /// and retires any overlay the gesture owned. Select options are synthesized retained Stacks
    /// published as `HitKind::Button`; dispatching that hit directly fired `setAppearance` while
    /// bypassing `OverlayClosed`, leaving the listbox painted over the updated Settings panel.
    /// Restricting this to `Input`/`Select` left a `Toggle`/`Slider`/`NumberStepper`/`Ring`/
    /// `IconSelect` press falling into the `action`-dispatch branch below with `action: None` —
    /// i.e. dispatching nothing at all (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
    /// `📓️audit-wgpu-parity-2026-09-13.md` gaps #1/#6).
    ///
    /// 🪟️ Pressing a window's BODY activates that window, on the press, exactly as pressing its
    /// chrome does. The keyboard follows `active_window_id`
    /// (`handle_keyboard_async`'s content-focus routing reads `content_has_focus(active)`), and a
    /// retained body press was the one way into a window that never set it: focus landed on the
    /// pressed `Input` — `content focus window=generation3d-generations node=Some(..)` — while
    /// every keystroke was still routed at `procedural-main`, the app's first window kind, whose
    /// content had no focus. So an inline rename editor could be opened and never typed into, on
    /// any window but the first (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
    /// `📓️wgpu-generation-publication-2026-09-13.md`).
    ///
    /// 🪟️ React's `activateWindow` is `setActiveWindowInLayout(prev, windowId)` plus
    /// `onActiveWindowChange` (`🧱️elements/🎨️Canvas/🟦️.tsx:1446-1452`) — the DOCK's notion of the
    /// active stack moves with the shell's active window, which is what paints the stack accent.
    /// Setting `active_window_id` alone left `dock.active_stack` on the previously focused
    /// stack, so a body press focused a window whose stack never lit up.
    ///
    /// 👆️ A click is press AND release, and the action fires on the RELEASE — the same rule
    /// `events::EventRouter` already applies to a `Button` (`PointerUp` inside the pressed
    /// node), and the same rule a browser applies.
    ///
    /// 🩸️ This used to fire on the press instead, and on 6118 that meant it never fired at
    /// all: `InputState`'s pointer registry is drained one entry per frame-build boundary
    /// step (`FrameBuildPhase::InputFrame`), so a `PointerDown` arriving inside that window
    /// resolves an EMPTY registry. Browser-measured, 2026-09-13: every `PointerDown` reported
    /// `targets=0 hit=None` while the matching `PointerUp` reported `targets=36` and the
    /// correct row — so `Add Generation` resolved perfectly and dispatched nothing
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️wgpu-retained-controls-wires-2026-09-13.md` §7).
    ///
    /// 🪟️ The row belongs to THIS window instance, so its dispatch must be addressed to it
    /// rather than to whatever window happens to be focused.
    async fn route_retained_pointer_press(
        &mut self,
        window_id: &str,
        body: Rect,
        x: f32,
        y: f32,
        down: bool,
        button: i16,
        kind: HitKind,
        action: Option<ActionDescriptor>,
        pointer_id: ui_render::PointerId,
        input: &mut InputState<ActionDescriptor>,
    ) -> Result<(), String> {
        Self::debug_log(&format!("[TRACE] wgpu-shell retained press window={window_id} kind={kind:?} down={down} action={:?}", action.as_ref().map(|descriptor| descriptor.action.clone())));
        if down && !self.retained_surface_is_panel(window_id) {
            let owner = window_pane_owner(window_id).unwrap_or(window_id).to_string();
            self.chrome_build.clear_sibling_pane_focus(window_id);
            self.dock.sync_active_window(&owner);
            self.active_window_id = Some(owner);
        }
        if retained_router_owns_pointer(kind) {
            let event = if down {
                ui_wgpu::wgpu::UiEvent::PointerDown { x: x - body.x, y: y - body.y, button: Self::retained_pointer_button(button), modifiers: Self::retained_event_modifiers(input) }
            } else {
                ui_wgpu::wgpu::UiEvent::PointerUp { x: x - body.x, y: y - body.y, button: Self::retained_pointer_button(button), modifiers: Self::retained_event_modifiers(input) }
            };
            let commands = crate::interpreter::dispatch_presented_ui_pointer_event(window_id, pointer_id, event, input);
            self.chrome_build.note_content_focus_commands(&commands);
        } else if !down {
            if let Some(mut action) = action {
                scope_action_to_window(&mut action, window_id);
                self.dispatch_action(action).await?;
            }
        }
        self.drain_gesture_bound_work().await;
        self.owe_settle();
        Ok(())
    }
    //#endregion 🎯️RetainedPointerRouting

    /// 🎬️ Whether a live engine surface is painted under this point — the wheel's twin of the press
    /// path's own `state.bounds.contains(x, y)` claim, and the same set of surfaces the four wheel
    /// phases go on to offer the notch to.
    pub fn scene_surface_contains(&self, x: f32, y: f32) -> bool {
        self.world3d_states.values().any(|state| state.bounds.contains(x, y))
            || self.node_graph_states.values().any(|surface| surface.bounds.contains(x, y))
            || self.tiled_map_states.values().any(|surface| surface.bounds.contains(x, y))
            || self.board2d_states.values().any(|surface| surface.bounds.contains(x, y))
    }

    /// 🎡️ A published scene hit owns its notch after modal and anchored-panel precedence.
    pub fn wheel_reaches_scene_surface(&self, x: f32, y: f32, input: &InputState<ActionDescriptor>, theme: &Theme) -> bool {
        !self.pointer_input_is_modal() && !self.pointer_is_over_open_panel(x, y, theme) && input.hit_at(x, y).is_some_and(|hit| self.retained_scene_hit_is_live(hit, x, y))
    }

    /// 🛑️🖱️ Whether a PRESS at this hit belongs to the shell's own chrome rather than to the engine
    /// surface underneath it.
    ///
    /// 🩸️ The World3d overlay row — the compute-status pill and the cancel control
    /// ([`surface_overlay_controls_for`]) — is painted INSIDE the surface's own rect, and the
    /// renderer's press path claimed a point for a World3d surface on `bounds.contains` alone and
    /// returned before the shell ever saw it (`🧊️renderer/🦀️.rs`, the `world_consumed` guard). The
    /// RELEASE path calls the shell first, but `handle_shell_hit` deliberately fires on the press —
    /// so the only pointer phase that reached the shell over a World3d surface was the one it
    /// ignores. Measured on 6118: the cancel control paints, hit-tests as
    /// `NavbarItem("shell.world3d.cancel::procedural-preview")`, and a click on it dispatched
    /// NOTHING, every time (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
    /// `📓️wgpu-progress-visibility-2026-09-14.md`). A cancel that cannot be pressed is not a cancel.
    ///
    /// ⚖️ Chrome kinds, plus the two NAMESPACES the shell alone mints. It is still never a list of
    /// control ids — `shell.` and `ui.introduction.` are prefixes no engine surface can produce,
    /// because every surface-minted target is keyed by its own `surface_id`
    /// (`🎞️Scenes/🎯️targets/🧊️wgpu/🦀️.rs`'s `scroll_key(&scene.surface_id, …)` and siblings).
    ///
    /// 🩸️ Kinds ALONE were not enough, and the gap swallowed a whole control family. A pane's
    /// overlay chips — `Actions`, `Search`, `Window Options`, `Utilities` and `Projection` — are
    /// `HitKind::Toggle` painted at React's `Pane` anchors INSIDE a world pane's rect
    /// ([`Self::window_pane_chips`]), so a press on any of them resolved to a chrome target, failed
    /// this predicate, and was handed to `enqueue_world3d_event` instead: `handle_shell_hit` never
    /// ran, the fold never flipped, and the unfolded body therefore never painted. Measured live at
    /// 1440×900 (`🗑️generated/w9b-projection-live/console.txt`): the press on
    /// `shell.projection.fold.puzzle3d-main-perspective` produced exactly ONE
    /// `wgpu-shell pointer button` line, `down=false` — the release the shell ignores — and the hit
    /// ledger stayed at 43 rows through ten 1.5 s retries.
    ///
    /// 🧯️ React has no such gap to close: a `Pane` chip is a DOM button in a layer ABOVE the
    /// `<canvas>` (`🖱️ui/🎯️targets/⚛️react/🟦️.tsx`'s `Pane`), so the canvas never sees the press at
    /// all. The `ui.introduction.` namespace is that same rule for the tour's veil and its three
    /// card controls, which own EVERY pointer in the app while they block
    /// (`📓️w5b-interaction-parity-probe.md` §4.3).
    /// 🩸️ The dock's own STRUCTURE was the second family the kind list missed. A split gutter is
    /// registered at the seam between two panes, and a pane's rect starts ON that seam
    /// (`puzzle3d-main-perspective@1063x914+534,54` against `dock.split..0@20x936+524,32`), so the
    /// press on the gutter resolved to `HitKind::DockSplit`, failed this predicate, and was enqueued
    /// into the world surface instead — `begin_drag` never ran, the split never moved and the
    /// release journalled no `shell.windowResize` where React journals one
    /// (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY, `📓️w9c-behaviour-parity-run-2.md` step 15).
    /// `PanelResize`, `PanelTab` and the join corner share the geometry and therefore the rule; the
    /// `dock.` namespace is the dock's twin of `shell.`, minted by [`crate::dock`] alone.
    pub fn pointer_press_belongs_to_shell_chrome(hit: Option<&HitTarget<ActionDescriptor>>) -> bool {
        Self::pointer_hit_owner(hit) == PointerHitOwner::Chrome
    }

    /// 🎯️ WHO owns a pointer at this hit — the whole DOM stacking rule in one answer, and the single
    /// routing predicate the renderer's press, move, release and wheel ingress all ask.
    ///
    /// ⚖️ The topmost hit is the owner: chrome painted over an engine surface takes the pointer from
    /// it, exactly as a DOM element above the `<canvas>` does, and a point that hits nothing is the
    /// surface's. [`Self::pointer_press_belongs_to_shell_chrome`] is this answer read as a bool. A retained pane body's rows are
    /// keyed `<surface>/<id>` (`PanelProjection::key`), so it is their surface-local id that names them chrome.
    pub fn pointer_hit_owner(hit: Option<&HitTarget<ActionDescriptor>>) -> PointerHitOwner {
        let chrome = hit.is_some_and(|hit| {
            matches!(hit.kind, HitKind::NavbarItem | HitKind::DropdownItem | HitKind::ContextMenu | HitKind::Select | HitKind::DockSplit | HitKind::DockJoinCorner | HitKind::PanelResize | HitKind::PanelTab)
                || hit.control_id.as_deref().is_some_and(|id| {
                    id.starts_with("shell.")
                        || id.starts_with("ui.introduction.")
                        || id.starts_with("dock.")
                        || id.starts_with("panel.resize.")
                        || id.starts_with(WINDOW_PANE_CHIP_PARENT)
                        || id.starts_with(WORLD_PROJECTION_PANE_PARENT)
                        || id.split_once('/').is_some_and(|(_, local)| local.starts_with(WORLD_PROJECTION_PANE_PARENT))
                        || id.starts_with(WINDOW_UTILITY_RAIL_PARENT)
                })
        });
        if chrome {
            PointerHitOwner::Chrome
        } else {
            PointerHitOwner::Surface
        }
    }

    /// 🚧️ Whether an overlay is MODAL for pointer input — React's menus, dropdowns, dialogs and the
    /// tour render into a layer above everything with their own backdrop, so while one is open no
    /// pointer of any phase reaches the canvas, wherever it lands. The tour's veil is already a
    /// full-screen hit target (`ui.introduction.veil`), so it answers through
    /// [`Self::pointer_hit_owner`] too; the other three publish hit rows for their own items only,
    /// and the point BESIDE an open menu is exactly the one that used to reach the world.
    fn candidate_pointer_input_is_modal(&self) -> bool {
        self.context_menu.is_some() || matches!(self.overlay_state, OverlayState::Search | OverlayState::Find) || self.chrome_build.dialog_open() || self.chrome_build.tour_is_open() || self.open_selects.values().any(|open| *open)
    }

    pub fn pointer_input_is_modal(&self) -> bool {
        self.presented_input_geometry.modal
    }

    /// 📑️ Whether this point is inside an OPEN anchored panel's painted box. A panel is an opaque
    /// layer over the dock's body — React's is a DOM element above the `<canvas>`, so the pointer
    /// never reaches the pane beneath it even where the panel's own content registers nothing (its
    /// padding, a gap between tree rows, the empty space under the last one). The boxes are this
    /// frame's own, from the same [`Self::anchor_rect`] the paint, the hit test and the published
    /// panel boxes read.
    pub fn pointer_is_over_open_panel(&self, x: f32, y: f32, _theme: &Theme) -> bool {
        self.presented_input_geometry.panel_rects.iter().any(|rect| rect.contains(x, y))
    }

    /// 🎯️ [`Self::pointer_hit_owner`] with this shell's live overlay LAYERS folded in — a modal
    /// overlay, an open panel's box, the retained body that minted the topmost hit, then the static
    /// hit classifier. The answer the renderer's ingress uses for a real point.
    pub fn pointer_owner_at(&self, x: f32, y: f32, input: &InputState<ActionDescriptor>, theme: &Theme) -> PointerHitOwner {
        if self.pointer_input_is_modal() || self.pointer_is_over_open_panel(x, y, theme) {
            return PointerHitOwner::Chrome;
        }
        let hit = input.hit_at(x, y);
        if let Some(hit) = hit.filter(|hit| self.retained_hit_window(hit).is_some()) {
            return if self.retained_scene_hit_is_live(hit, x, y) { PointerHitOwner::Surface } else { PointerHitOwner::Chrome };
        }
        PointerHitOwner::Chrome
    }

    /// 🧲️ Resolves one published scene identity after the shell's modal and panel layers.
    pub fn scene_pointer_target_at(&self, x: f32, y: f32, input: &InputState<ActionDescriptor>, theme: &Theme) -> Option<crate::interpreter::ScenePointerTarget> {
        if self.pointer_input_is_modal() || self.pointer_is_over_open_panel(x, y, theme) {
            return None;
        }
        let hit = input.hit_at(x, y)?;
        if !self.retained_scene_hit_is_live(hit, x, y) {
            return None;
        }
        let (_, target) = self.retained_scene_hits.get(hit.control_id.as_deref()?)?;
        crate::interpreter::scene_pointer_target_is_live(target).then(|| target.clone())
    }

    /// 🖼️ Captured input may outlive its rectangle, but never its published scene owner.
    pub fn scene_pointer_target_is_published(&self, target: &crate::interpreter::ScenePointerTarget) -> bool {
        self.retained_scene_hits.values().any(|(_, published)| published == target) && crate::interpreter::scene_pointer_target_is_live(target)
    }

    /// 🪟️ A press anywhere inside a window's own box ACTIVATES that window — React's
    /// `🪟️Window/🟦️.tsx`'s `onPointerDownCapture={… onActivate?.()}`, a capture-phase handler on the
    /// whole window element, so it fires for the window's chrome AND for the scene canvas filling its
    /// body, before any inner handler runs. It reaches `Mode`'s `activateWindow`
    /// (`🎨️Canvas/🟦️.tsx:1446`), whose `onActiveWindowChange` is the one funnel
    /// `🏛️ShellHost/🟦️.tsx:10389`'s `handleActiveWindowChange` notes `shell.windowActivate` from.
    ///
    /// 🩸️ This renderer had eleven sites writing `active_window_id` and not one of them was a press
    /// into a window BODY, so orbiting a pane never activated it: React's `orbit-drag` journals a
    /// `noteShellCommand` for the press into the perspective pane and the wgpu pane journalled none
    /// (`🗑️generated/w12c-parity-run-19/steps.json` step 19, ticket 26/09/17 packet W13c §1).
    ///
    /// The boxes are `dock_window_plan` — this frame's own solved window bodies, the same rects the
    /// dock paints and hit-tests. A modal layer owns every pointer and activates nothing (React's
    /// menus and dialogs are portaled OUTSIDE the window element, so no capture handler of theirs
    /// ever fires), and the empty-id row the dock plans after a cap close names no window.
    /// [`Self::arm_window_activation_note`] turns the change into the history note on the next drain.
    pub fn activate_window_under_pointer(&mut self, x: f32, y: f32, theme: &Theme) -> bool {
        if self.pointer_input_is_modal() || self.pointer_is_over_open_panel(x, y, theme) {
            return false;
        }
        let Some(window_id) = self.presented_input_geometry.dock_window_plan.iter().rev().find(|(id, rect)| !id.is_empty() && rect.contains(x, y)).map(|(id, _)| id.clone()) else {
            return false;
        };
        if self.active_window_id.as_deref() == Some(window_id.as_str()) {
            return false;
        }
        self.dock.sync_active_window(&window_id);
        self.active_window_id = Some(window_id);
        true
    }

    /// 🖱️ Whether a LIVE drag has captured the pointer for the shell's own chrome — the MOVE twin of
    /// [`Self::pointer_press_belongs_to_shell_chrome`], and React's `setPointerCapture` on a resize
    /// handle. The dock's structural drags travel across whatever the pointer sweeps over, so the
    /// engine surfaces under it must not also receive those moves.
    pub fn drag_captures_pointer(drag: &ui_wgpu::wgpu::DragState) -> bool {
        drag.active && matches!(drag.kind, Some(HitKind::DockSplit | HitKind::DockJoinCorner | HitKind::PanelResize | HitKind::PanelTab))
    }

    /// 📜️ The open context menu's own scroll offset lives on `ContextMenuState`, not the generic
    /// per-control `scroll_offsets` map — see `render_context_menu_level`'s clip/scroll handling.
    pub fn handle_pointer_wheel(&mut self, x: f32, y: f32, delta_x: f32, delta_y: f32, input: &mut InputState<ActionDescriptor>) -> bool {
        if self.widget_maps.scroll_select_popup_at(input, &mut self.scroll_offsets, x, y, delta_y) {
            return true;
        }
        let Some(hit) = input.hit_at(x, y).cloned() else {
            return false;
        };
        if self.retained_scene_hit_is_live(&hit, x, y) {
            return false;
        }
        if let Some((surface, body)) = self.retained_hit_window(&hit) {
            let modifiers = Self::retained_event_modifiers(input);
            let _ = crate::interpreter::dispatch_ui_event(&surface, ui_wgpu::wgpu::UiEvent::Scroll { x: x - body.x, y: y - body.y, delta_x, delta_y, modifiers }, input);
            return true;
        }
        if hit.kind != HitKind::ScrollRegion {
            return false;
        }
        let Some(id) = &hit.control_id else {
            return false;
        };
        if id == "shell.context.menu.scroll" {
            let Some(menu) = self.context_menu.as_mut() else {
                return false;
            };
            menu.scroll_offset = (menu.scroll_offset + delta_y).max(0.0);
            return true;
        }
        let entry = self.scroll_offsets.entry(id.clone()).or_insert(0.0);
        let delta = if id.starts_with("shell.panel.tabs.") && delta_x != 0.0 { delta_x } else { delta_y };
        *entry = (*entry + delta).max(0.0);
        true
    }

    pub async fn handle_world3d_input(&mut self, x: f32, y: f32, down: bool, button: i16, shift: bool, ctrl: bool, alt: bool, meta: bool, wheel_delta: f32, drag_dx: f32, drag_dy: f32) -> Result<(), String> {
        let modifiers = PointerModifiers { shift, ctrl, alt, meta };
        for state in self.world3d_states.values_mut() {
            if !state.bounds.contains(x, y) {
                continue;
            }
            let wheel = WorldInteractionIntent::wheel(x, y, wheel_delta, &modifiers);
            let button_intent = WorldInteractionIntent::pointer_button(x, y, down, button, &modifiers);
            let move_intent = WorldInteractionIntent::pointer_move(x, y, drag_dx, drag_dy, down, button, &modifiers);
            let mut drag = move_intent;
            drag.phase = WorldInteractionPhase::PointerDrag;
            let has_wheel = wheel_delta.abs() > 0.0;
            let has_drag = down && (drag_dx.abs() > 0.0 || drag_dy.abs() > 0.0);
            let admitted = match (has_wheel, has_drag) {
                (true, true) => enqueue_world3d_events(state, [wheel, drag, button_intent, move_intent]).is_ok(),
                (true, false) => enqueue_world3d_events(state, [wheel, button_intent, move_intent]).is_ok(),
                (false, true) => enqueue_world3d_events(state, [drag, button_intent, move_intent]).is_ok(),
                (false, false) => enqueue_world3d_events(state, [button_intent, move_intent]).is_ok(),
            };
            if !admitted {
                return Err("world3d fixed interaction credits exhausted".into());
            }
        }
        Ok(())
    }

    pub(crate) async fn handle_accessibility_event(&mut self, target: &ui_render::AccessibilityTarget, event: &ui_render::AccessibilityEvent, input: &mut InputState<ActionDescriptor>) -> Result<bool, String> {
        if target.window_id != crate::interpreter::SHELL_CHROME_ACCESSIBILITY_WINDOW_ID {
            let event = match event {
                ui_render::AccessibilityEvent::Focus => ui_wgpu::wgpu::AccessibilityUiEvent::Focus,
                ui_render::AccessibilityEvent::Blur => ui_wgpu::wgpu::AccessibilityUiEvent::Blur,
                ui_render::AccessibilityEvent::Activate => ui_wgpu::wgpu::AccessibilityUiEvent::Activate,
                ui_render::AccessibilityEvent::Value(value) => ui_wgpu::wgpu::AccessibilityUiEvent::Value(value.clone()),
            };
            let focused = matches!(event, ui_wgpu::wgpu::AccessibilityUiEvent::Focus);
            let Some(commands) = crate::interpreter::dispatch_accessibility_event(&target.window_id, target.window_generation, target.node_id, &target.node_key, event, input) else { return Ok(false) };
            self.chrome_build.note_content_focus_commands(&commands);
            if focused && !self.retained_surface_is_panel(&target.window_id) {
                let owner = window_pane_owner(&target.window_id).unwrap_or(&target.window_id).to_string();
                self.chrome_build.clear_sibling_pane_focus(&target.window_id);
                self.dock.sync_active_window(&owner);
                self.active_window_id = Some(owner);
            }
            return Ok(true);
        }
        if target.window_generation != self.presented_chrome_accessibility_generation {
            return Ok(false);
        }
        if !self.presented_chrome_accessibility.iter().any(|node| node.node_id == target.node_id && node.key == target.node_key) {
            return Ok(false);
        }
        if self.handle_chrome_dialog_accessibility_event(&target.node_key, event) {
            return Ok(true);
        }
        if target.node_key == icon_export::CONTROL_ID {
            match event {
                ui_render::AccessibilityEvent::Activate => self.cancel_icon_export(),
                ui_render::AccessibilityEvent::Focus => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                }
                ui_render::AccessibilityEvent::Blur => self.accessibility_focused_control_id = None,
                ui_render::AccessibilityEvent::Value(_) => return Ok(false),
            }
            return Ok(true);
        }
        let palette_kind = match self.overlay_state {
            OverlayState::Search => Some(ShellPaletteKind::Search),
            OverlayState::Find => Some(ShellPaletteKind::Find),
            _ => None,
        };
        if let Some(kind) = palette_kind {
            match event {
                ui_render::AccessibilityEvent::Focus if target.node_key == kind.input_id() => {
                    let query = self.palette_query(kind).to_string();
                    self.set_palette_query(kind, query, input);
                }
                ui_render::AccessibilityEvent::Focus if target.node_key == kind.close_id() => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                }
                ui_render::AccessibilityEvent::Focus => {}
                ui_render::AccessibilityEvent::Blur if target.node_key == kind.input_id() => {
                    input.blur_input();
                    self.accessibility_focused_control_id = None;
                }
                ui_render::AccessibilityEvent::Blur => {}
                ui_render::AccessibilityEvent::Activate if target.node_key == kind.close_id() => {
                    self.close_command_palette(input);
                }
                ui_render::AccessibilityEvent::Activate if target.node_key == kind.input_id() => {
                    let query = self.palette_query(kind).to_string();
                    self.set_palette_query(kind, query, input);
                }
                ui_render::AccessibilityEvent::Activate => {
                    let index = match kind {
                        ShellPaletteKind::Search => self.filtered_search_items().iter().position(|item| item.id == target.node_key),
                        ShellPaletteKind::Find => self.filtered_find_items().iter().position(|item| item.id == target.node_key),
                    };
                    if let Some(index) = index {
                        match kind {
                            ShellPaletteKind::Search => self.activate_search_item(index).await?,
                            ShellPaletteKind::Find => self.activate_find_item(index).await?,
                        }
                        input.blur_input();
                        self.accessibility_focused_control_id = None;
                    }
                }
                ui_render::AccessibilityEvent::Value(value) if target.node_key == kind.input_id() => {
                    self.set_palette_query(kind, value.clone(), input);
                }
                ui_render::AccessibilityEvent::Value(_) => {}
            }
            return Ok(true);
        }
        if let Some(anchor) = self.panel_tab_anchor(&target.node_key) {
            match event {
                ui_render::AccessibilityEvent::Focus => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                    self.reveal_panel_tab_row(anchor, &target.node_key);
                }
                ui_render::AccessibilityEvent::Blur => {
                    if self.accessibility_focused_control_id.as_deref() == Some(target.node_key.as_str()) {
                        self.accessibility_focused_control_id = None;
                    }
                }
                ui_render::AccessibilityEvent::Activate => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                    self.reveal_panel_tab_row(anchor, &target.node_key);
                    self.select_panel_tab(anchor, &target.node_key).await?;
                }
                ui_render::AccessibilityEvent::Value(_) => return Ok(false),
            }
            return Ok(true);
        }
        if let Some(window_id) = dock_tab_select_window_id(&target.node_key).map(str::to_string) {
            match event {
                ui_render::AccessibilityEvent::Focus => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                }
                ui_render::AccessibilityEvent::Blur => {
                    if self.accessibility_focused_control_id.as_deref() == Some(target.node_key.as_str()) {
                        self.accessibility_focused_control_id = None;
                    }
                }
                ui_render::AccessibilityEvent::Activate => {
                    input.blur_input();
                    self.accessibility_focused_control_id = Some(target.node_key.clone());
                    if self.dock.activate_window(&window_id) {
                        self.active_window_id = Some(window_id);
                    }
                }
                ui_render::AccessibilityEvent::Value(_) => return Ok(false),
            }
            return Ok(true);
        }
        let Some(hit) = input.hits().iter().find(|hit| hit.control_id.as_deref() == Some(target.node_key.as_str())).cloned() else { return Ok(false) };
        if input.focused_id.as_deref().is_some_and(|id| id != target.node_key) {
            self.commit_focused_input(input).await?;
        }
        if hit.kind != HitKind::Input {
            input.blur_input();
        }
        self.accessibility_focused_control_id = Some(target.node_key.clone());
        match event {
            ui_render::AccessibilityEvent::Focus => {
                if hit.kind == HitKind::Input {
                    let seed = ShellPaletteKind::from_input_id(&target.node_key).map(|kind| self.palette_query(kind).to_string()).or_else(|| self.widget_maps.input_metas.get(&target.node_key).map(|meta| meta.value.clone())).unwrap_or_default();
                    input.focus_input_owned(target.node_key.clone(), seed);
                }
            }
            ui_render::AccessibilityEvent::Blur => {
                if input.focused_id.as_deref() == Some(target.node_key.as_str()) {
                    self.commit_focused_input(input).await?;
                }
                if self.accessibility_focused_control_id.as_deref() == Some(target.node_key.as_str()) {
                    self.accessibility_focused_control_id = None;
                }
            }
            ui_render::AccessibilityEvent::Activate => {
                if self.handle_shell_hit(&hit, input).await? {
                    if matches!(target.node_key.as_str(), "ui.search.toggle" | "ui.find.toggle") {
                        if let Some(kind) = match self.overlay_state {
                            OverlayState::Search => Some(ShellPaletteKind::Search),
                            OverlayState::Find => Some(ShellPaletteKind::Find),
                            _ => None,
                        } {
                            self.set_palette_query(kind, self.palette_query(kind).to_string(), input);
                        }
                    } else if ShellPaletteKind::row_index(&target.node_key).is_some() {
                        input.blur_input();
                        self.accessibility_focused_control_id = None;
                    }
                } else {
                    if let Some(action) = hit.event {
                        self.dispatch_action(action).await?;
                    }
                }
            }
            ui_render::AccessibilityEvent::Value(value) => {
                if let Some(kind) = ShellPaletteKind::from_input_id(&target.node_key) {
                    self.set_palette_query(kind, value.clone(), input);
                    return Ok(true);
                }
                if target.node_key.ends_with(".input") {
                    let base = target.node_key.trim_end_matches(".input");
                    if let Some(meta) = self.widget_maps.stepper_metas.get(base).cloned() {
                        if let Ok(value) = value.parse::<f64>() {
                            self.dispatch_action(ActionDescriptor { controller_id: meta.on_absolute.controller_id, action: meta.on_absolute.action, args: crate::action_args_json!({ "value": value }) }).await?;
                        }
                        return Ok(true);
                    }
                }
                if let Some(meta) = self.widget_maps.input_metas.get(&target.node_key).cloned() {
                    if let Some(value) = meta.commit_value(value) {
                        let args = merge_committed_args(meta.on_change.args.as_ref(), value);
                        self.dispatch_action(ActionDescriptor { controller_id: meta.on_change.controller_id, action: meta.on_change.action, args }).await?;
                    }
                }
            }
        }
        Ok(true)
    }

    /// 🪟️ The five pane chips answer FIRST and by decode, not by prefix: their ids carry the window
    /// instance in the middle (React's `framework.window.<segment>.<pane>.<verb>`), so a
    /// `starts_with` arm cannot name them. See [`WindowPaneChip::control_id`].
    ///
    /// 🔼️ A `Select` popup's scroll chevron (`{select}.scroll.up`/`.down`). Answered BEFORE the
    /// `match` for the same reason the pane chips are: the id is decoded, not prefixed, and the
    /// press handler cannot clamp — it only arms a direction that the popup's own painter prices
    /// in `select_scroll_step` pixels and clamps with `select_clamped_scroll`, because only the
    /// painter holds the item count and the collision-resolved popup height
    /// (ticket 26/09/17 packet W15a; the chevrons painted and did nothing before it).
    ///
    /// 👁️✏️ The surface-role group. Switching roles is a TRANSACTIONAL session switch, not a
    /// view-state flip: the successor instance is created before the predecessor is retired,
    /// so no render ever observes two live instances of one plugin.
    ///
    /// 🛑️ The World3d compute cancel — dispatches whatever id the surface's own status
    /// document named, never a verb this shell knows.
    ///
    /// 🔀️ The pane's own Projection chip — React's `framework.worldOrbit.projection.<segment>.pane.fold`,
    /// ONE id on both sides of the fold (`Pane`'s `chromeToggleId = toggleId ?? childElementId(id,
    /// "pane", "fold")`, `🖱️ui/🎯️targets/⚛️react/🟦️.tsx:10006`), flipping the pane's own local
    /// `folded` state and nothing else.
    ///
    /// 🪟️ React gates the cap on `canMaximize` — a mode with ONE window has nothing to
    /// maximize away from, exactly as `focus_active_window` already refuses there.
    ///
    /// 🖥️ React's `applyNamedLayout` searches `[...builtinLayouts, ...userLayouts]`
    /// (`📌️ChromePanels/🟦️.tsx`'s `useNamedLayoutHost`), so a layout the user SAVED resolves
    /// exactly like one the app declared. This arm used to search the app's declarations
    /// alone, which is why a restored `namedLayouts` entry was inert.
    ///
    /// 🎓️ The introduction's own four controls, answered HERE rather than by a rect test inside
    /// the painter — React wires them as ordinary `onClick`/`onPointerDown` handlers on real
    /// elements, and routing them through the one press funnel is what makes the veil able to
    /// swallow a press instead of letting it through to the surface below.
    ///
    /// 📱️ The mobile panel's flattened tab row selects a path in the ONE mobile panel instead
    /// of an anchor's, and a tool leaf arms its tool exactly as the desktop row does.
    ///
    /// 📑️ A panel tab is addressed by React's own BARE id (`framework.panel.artifact`), so the
    /// anchor is derived here from whichever anchor's tab tree carries it — exactly as React
    /// derives it from the tab's own `group` — instead of being carried in the control id.
    ///
    /// 🖱️ Group rows (`menu.group.<category>`, but any row with `children`) open their submenu on
    /// click, not just hover — matched by path (not a flat top-level id scan) so nested rows work.
    ///
    /// 🍿️ A row the surface answers ITSELF never reaches the guest — React's
    /// `dispatchTextEditorMenu` short-circuits its own `localActions` the same way.
    ///
    /// 🔀️ The picked value is MERGED into whatever the node authored, never
    /// substituted for it — see `merge_committed_args` (packet W15d).
    async fn handle_shell_hit(&mut self, hit: &HitTarget<ActionDescriptor>, input: &InputState<ActionDescriptor>) -> Result<bool, String> {
        let Some(id) = hit.control_id.as_deref() else {
            return Ok(false);
        };
        if let Some((window_id, chip)) = self.window_pane_chip_target(id) {
            self.toggle_window_pane_chip(&window_id, chip)?;
            return Ok(true);
        }
        if ui_wgpu::wgpu::arm_select_scroll(&mut self.scroll_offsets, id) {
            return Ok(true);
        }
        if let Some((kind, index)) = ShellPaletteKind::row_index(id) {
            match kind {
                ShellPaletteKind::Search => self.activate_search_item(index).await?,
                ShellPaletteKind::Find => self.activate_find_item(index).await?,
            }
            return Ok(true);
        }
        match id {
            "framework.hub.scrim" => return Ok(true),
            "framework.hub.signIn" => {
                self.push_uri("/hub".to_string());
                self.apply_shell_uri("/hub").await?;
                return Ok(true);
            }
            "ui.nav.back" => {
                if self.uri_index > 0 {
                    self.uri_index -= 1;
                }
                self.apply_pending_shell_uri().await?;
                return Ok(true);
            }
            "ui.nav.forward" => {
                if self.uri_index + 1 < self.uri_history.len() {
                    self.uri_index += 1;
                }
                self.apply_pending_shell_uri().await?;
                return Ok(true);
            }
            "ui.nav.up" => {
                let uri = self.shell_uri();
                if let Some(parent) = uri.rsplit_once('/').map(|(p, _)| p.to_string()) {
                    if !parent.is_empty() {
                        self.push_uri(parent);
                    }
                }
                self.apply_pending_shell_uri().await?;
                return Ok(true);
            }
            "playground.navbar.fixture" => {
                let open = matches!(&self.overlay_state, OverlayState::Dropdown(id) if id == "example");
                self.overlay_state = if open { OverlayState::None } else { OverlayState::Dropdown("example".to_string()) };
                return Ok(true);
            }
            id if id.starts_with("playground.navbar.roles.") => {
                let requested = match id.trim_start_matches("playground.navbar.roles.") {
                    "editor" => semio_framework::manifest::AppRole::Editor,
                    "viewer" => semio_framework::manifest::AppRole::Viewer,
                    _ => return Ok(true),
                };
                self.switch_to_session_role(requested).await?;
                return Ok(true);
            }
            id if id.starts_with("playground.navbar.modes.") => {
                let mode_id = id.trim_start_matches("playground.navbar.modes.").to_string();
                self.apply_navbar_mode(&mode_id).await?;
                return Ok(true);
            }
            id if id.starts_with("shell.world3d.cancel::") => {
                let host_id = id.trim_start_matches("shell.world3d.cancel::").to_string();
                let action = world3d_cancel_affordance(self.world3d_status.get(&host_id).map(String::as_str));
                let owner = self.world3d_states.get(&host_id).map(|world| (world.controller_id.clone(), world.surface_id.clone()));
                if let (true, Some((controller_id, surface_id))) = (action.cancellable, owner) {
                    Self::debug_log(&format!("[TRACE] shell world3d cancel {}", serde_json::json!({ "host": host_id, "surface": surface_id, "action": action.cancel_action })));
                    let mut args = action.cancel_args;
                    args.insert("surfaceId".to_string(), Value::String(surface_id));
                    self.dispatch_action(ActionDescriptor { controller_id, action: action.cancel_action, args: Some(semio_framework::DslValue::from(Value::Object(args))) }).await?;
                }
                return Ok(true);
            }
            id if id.starts_with("framework.utility.collection.") => {
                let collection_id = id.trim_start_matches("framework.utility.collection.");
                let expanded = self.utility_collection_expanded.get(collection_id).copied().unwrap_or(false);
                self.utility_collection_expanded.insert(collection_id.to_string(), !expanded);
