#[cfg(test)]
pub(crate) fn is_reserved_shell_chord(action: &ui_wgpu::wgpu::KeyAction, modifiers: &PointerModifiers) -> bool {
    is_reserved_shell_chord_in(&shell_shortcut_table(&HashMap::new()), action, modifiers)
