    let command = InferCommand {
        plugin_id: "wfc".into(),
        artifact_kind: "s.wfc.wfc3d".into(),
        inference_schema: "s.wfc.wfc3d.solve".into(),
        revision: 4,
        generation: 0,
        cancellation_id: "cancel-1".into(),
        work_units: 64,
        canonical_payload: b"{\"seed\":7}".to_vec(),
        artifact_id: String::new(),
        artifact_document: None,
