    host.pointer_up_screen(screen.x - 180.0, screen.y, false, false, false);
    assert_eq!(host.dag.engine.edges.len(), 2);
    assert_eq!(host.host_snapshot.synapses.len(), 2);
    host.retire_cold();
}

