}
#[test]
fn leaves_the_document_untouched() {
    let raised = <En1992Mutation as protocol::Mutation<En1992Snapshot>>::diff(&mutation(), &before());
    let after = <En1992Diff as protocol::MutationDiff<En1992Snapshot>>::apply(raised.diff(), &before()).expect("apply");
    assert_eq!(after, before());
    assert_eq!(semio_framework_pack_json::from_json_str::<En1992Snapshot>(AFTER).expect("after"), before());
}

