//! 🧪️ Committed vector `➕️insert-building` / `⛔dupe`: re-applying the op to the after-snapshot it already produced is refused with `mutation.duplicate-id` (fatal) and leaves the document untouched.
use crate::{En1998Diff, En1998Mutation, En1998Snapshot};
const BEFORE: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/⛔dupe/📸️snapshot/⬅️before/🔣️.json");
const AFTER: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/⛔dupe/📸️snapshot/➡️after/🔣️.json");
const MUTATION: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/⛔dupe/🦠️mutation/🔣️.json");
const DIFF_ABSENT: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/⛔dupe/🔺️diff/🚫️.absent");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/⛔dupe/🎯️outcome/🔣️.json");
fn before() -> En1998Snapshot { semio_framework_pack_json::from_json_str(BEFORE, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("before") }
fn mutation() -> En1998Mutation { semio_framework_pack_json::from_json_str(MUTATION, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("mutation") }
#[test]
fn mutation_is_the_canonical_wire() {
    let _: En1998Mutation = store::os_store::test_support::assert_wire_witness(MUTATION);
}
#[test]
fn refuses_with_the_declared_code() {
    let raised = <En1998Mutation as protocol::Mutation<En1998Snapshot>>::diff(&mutation(), &before());
    let outcome: serde_json::Value = serde_json::from_str(OUTCOME).expect("outcome");
    let raised_codes: Vec<(String, String)> = raised.messages().iter().map(|message| (format!("{:?}", message.level).to_lowercase(), message.code.0.clone())).collect();
    assert_eq!(raised_codes, vec![(outcome["messages"][0]["level"].as_str().expect("level").to_string(), outcome["code"].as_str().expect("code").to_string())]);
    assert_eq!(outcome["status"], "rejected");
    assert_eq!(*raised.diff(), En1998Diff::default());
    assert!(DIFF_ABSENT.is_empty());
}
#[test]
fn leaves_the_document_untouched() {
    let raised = <En1998Mutation as protocol::Mutation<En1998Snapshot>>::diff(&mutation(), &before());
    let after = <En1998Diff as protocol::MutationDiff<En1998Snapshot>>::apply(raised.diff(), &before()).expect("apply");
    assert_eq!(after, before());
    assert_eq!(semio_framework_pack_json::from_json_str::<En1998Snapshot>(AFTER).expect("after"), before());
}

//! 🧪️ Committed vector `➕️insert-building` / `✅apply`: the canonical wire of the op reaches the committed after-snapshot and diff, and its own inverse restores the before-snapshot.
use crate::{En1998Diff, En1998Mutation, En1998Snapshot};
const BEFORE: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/✅apply/📸️snapshot/⬅️before/🔣️.json");
const AFTER: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/✅apply/📸️snapshot/➡️after/🔣️.json");
const MUTATION: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/✅apply/🦠️mutation/🔣️.json");
const DIFF: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/✅apply/🔺️diff/🔣️.json");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/➕️insert-building/✅apply/🎯️outcome/🔣️.json");
fn before() -> En1998Snapshot { semio_framework_pack_json::from_json_str(BEFORE, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("before") }
fn mutation() -> En1998Mutation { semio_framework_pack_json::from_json_str(MUTATION, semio_framework_pack_json::JsonMemberPolicy::Reject).expect("mutation") }
fn apply(mutation: &En1998Mutation, base: &En1998Snapshot) -> En1998Snapshot {
    let raised = <En1998Mutation as protocol::Mutation<En1998Snapshot>>::diff(mutation, base);
    assert!(raised.messages().is_empty(), "insert-building raised {:?}", raised.messages());
    <En1998Diff as protocol::MutationDiff<En1998Snapshot>>::apply(raised.diff(), base).expect("apply")
}
#[test]
fn mutation_is_the_canonical_wire() {
    let _: En1998Mutation = store::os_store::test_support::assert_wire_witness(MUTATION);
}
#[test]
fn applies_to_committed_after_and_diff() {
    let base = before();
    let raised = <En1998Mutation as protocol::Mutation<En1998Snapshot>>::diff(&mutation(), &base);
    assert_eq!(*raised.diff(), semio_framework_pack_json::from_json_str::<En1998Diff>(DIFF).expect("diff"));
    let after = apply(&mutation(), &base);
    assert_ne!(after, base, "insert-building must move the document");
    assert_eq!(after, semio_framework_pack_json::from_json_str::<En1998Snapshot>(AFTER).expect("after"));
}
#[test]
fn inverse_restores_before() {
    let base = before();
    let inverse = <En1998Mutation as protocol::Mutation<En1998Snapshot>>::inverse(&mutation(), &base);
    assert!(!inverse.is_empty(), "insert-building changes the document, so its inverse must not be empty");
    let restored = inverse.iter().fold(apply(&mutation(), &base), |snapshot, step| apply(step, &snapshot));
    assert_eq!(restored, base);
}
#[test]
fn declared_outcome_holds() {
    assert_eq!(serde_json::from_str::<serde_json::Value>(OUTCOME).expect("outcome")["status"], "applied");
}

pub(crate) mod context {
    use super::super::*;
    use semio_framework_plugin::artifact_app_laws::{close_registered_fixture_app, meta, new_app_with_registry_and_members as framework_new_app_with_registry_and_members, settle_registered_typed_operation};
    use semio_framework_plugin::{EditorApp, InvocationResult, PluginApp, VcsArtifactApp, ViewModel, ViewWindowInstance};

    pub const WRITER_TEST_WINDOW_ID: &str = "writer-main-test";

    pub fn main_window_view() -> ViewModel {
        ViewModel { window_id: Some(WRITER_TEST_WINDOW_ID.into()), window_instances: vec![ViewWindowInstance { id: WRITER_TEST_WINDOW_ID.into(), window_kind_id: WRITER_PLAY_WINDOW_KIND.into() }], ..ViewModel::new(semio_framework_ui_locale::Locale::En, semio_framework_ui_locale::Terminology::Native) }
    }

    /// WriterPlayApp implements the AUTHORING trait ArtifactEditor, not the runtime ArtifactApp --
    /// EditorApp<WriterPlayApp> (SDK adapter, contract 2.1) is the real ArtifactApp implementor
    /// VcsArtifactApp wraps, the same way PluginBuilder::editor::<WriterPlayApp> builds it.
    type MountedWriterApp = VcsArtifactApp<EditorApp<WriterPlayApp>, semio_s_artifact_stdio_semio::SemioMembers>;

    /// 🔒️ Self-closing app handle: every registry-backed app owns Stores that must retire through the
    /// bounded close protocol before drop (`artifact store reached Drop without its exact terminal-empty
    /// shallow-shell witness`), so `Drop` runs `close_registered_fixture_app` for every test that returns
    /// early — a panicking test leaves the witness alone so the FIRST failure stays the reported one.
    pub struct WriterApp(MountedWriterApp);

    impl std::ops::Deref for WriterApp {
        type Target = MountedWriterApp;
        fn deref(&self) -> &Self::Target {
            &self.0
        }
    }

    impl std::ops::DerefMut for WriterApp {
        fn deref_mut(&mut self) -> &mut Self::Target {
            &mut self.0
        }
    }

    impl Drop for WriterApp {
        fn drop(&mut self) {
            if !std::thread::panicking() {
                close_registered_fixture_app(&mut self.0);
            }
        }
    }

    /// 🧪️ Constructs the Writer app with its declared command registry.
    pub async fn new_app() -> WriterApp {
        let mut app = framework_new_app_with_registry_and_members::<EditorApp<WriterPlayApp>, semio_s_artifact_stdio_semio::SemioMembers>(writer_app_manifest_for_tests).await;
        app.bind_instance_id(meta("local").instance_id).await;
        WriterApp(app)
    }

    /// Adapts create_writer_app's AppDefinition (contract 2.4) into the App { definition, examples }
    /// shape artifact_app_laws::new_app_with_registry/assert_declared_actions_bridge_to_commands still expect --
    /// framework test context gap (framework crate outside this packet's lease), not modifiable here.
    fn writer_app_manifest_for_tests() -> semio_framework_plugin::App {
        semio_framework_plugin::App { definition: create_writer_app(), examples: Vec::new() }
    }

    semio_framework_plugin::history_edit_acceptance_law!("writer", WriterPlayApp, writer_app_manifest_for_tests, "../..");

    /// 🧪️ An app wired to the real manifest registry — enforces View/Shell kind discipline.
    pub async fn new_app_with_registry() -> WriterApp {
        new_app().await
    }

    /// ✍️ Loads the canonical jack fixture into the store, returning the app ready to exercise.
    /// 🌱️ Whole-document replace is not an in-history mutation (`SetSnapshot` is banned outright —
    /// see `reset_document_effect`'s doc comment), so `setActiveExample` no longer lands via
    /// `dispatch_typed` alone; this loads the same document pack a real host would apply from that
    /// command's `Effect::LoadDocument`, via `PluginApp::load_document_pack` directly — the same
    /// technique `📐️cad`'s own `two_instances_converge_disjoint_edits_via_backbone` test uses.
    pub async fn app_with_jack() -> WriterApp {
        let mut app = new_app().await;
        let document = crate::document_dsl::jack_example_document();
        let (schema, id) = (document.schema.clone(), document.id.clone());
        let envelope = store::create_document_envelope::<WriterSnapshot, WriterMutation>(&schema, &id, document, None);
        let files = store::print_document_pack(&envelope).await.expect("print jack document pack");
        retire_writer_envelope(envelope);
        app.load_document_pack(&files).await.expect("load jack");
        app
    }

    /// 🧹️ A document envelope a test builds only to print a pack is a TERMINAL SHELL: `ArtifactEnvelope`
    /// asserts in `Drop` that an app-owned bounded retirement authority detached its nested owners first
    /// ("artifact envelope terminal shell reached Drop before its app-owned bounded retirement authority
    /// detached every nested owner"), and only a store ever runs that protocol. No store adopts this one,
    /// so the artifact's OWN owner catalog retires it here — the same shape `🖨️raster`'s
    /// `retire_raster_envelope` uses for exactly this fixture pattern.
    pub fn retire_writer_envelope(envelope: store::ArtifactEnvelope<WriterSnapshot, WriterMutation>) {
        let mut retirement = crate::spr::writer_document_store_owners().retire_envelope_uninstalled(envelope).expect("an uninstalled writer owner catalog retires one envelope");
        for _ in 0..1_000_000 {
            if store::ErasedSnapshotRetirement::terminal_is_empty(retirement.as_ref()) {
                return;
            }
            store::ErasedSnapshotRetirement::close_step(retirement.as_mut(), 1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES).expect("writer test envelope retires within its exact grant");
        }
        panic!("writer test envelope did not reach its terminal-empty shell")
    }

    pub async fn dispatch(app: &mut WriterApp, command: WriterCommand) -> InvocationResult {
        let mut meta = meta("local");
        meta.view_state = Some(main_window_view());
        let mut result = app.dispatch_typed(command, &meta).await.expect("dispatch");
        result.requested_effects.extend(drain_typed_operations(app).await);
        for effect in &result.requested_effects {
            if let semio_framework_plugin::Effect::LoadDocument { pack, spr } = effect {
                let files = store::ArtifactPackFiles { pack: pack.clone(), spr: spr.clone(), ops: String::new() };
                app.load_document_pack(&files).await.expect("test host applies load-document effect");
            }
        }
        result
    }

    /// ↩️ An `undo`/`redo` verb is a FRAMEWORK-RESERVED job, not a typed command: admitted, then
    /// committed through its reserved job, then published — all three steps or the projection never moves.
    pub async fn history_verb(app: &mut WriterApp, action: &str) -> InvocationResult {
        let admitted = app.handle_action(action, None, &meta("local")).await.unwrap_or_else(|fault| panic!("history verb {action} admission: {fault:?}"));
        let settled = semio_framework_plugin::app::settle_framework_reserved_admission(&mut app.0, admitted).await.unwrap_or_else(|fault| panic!("history verb {action} reserved-job commit: {fault:?}"));
        drain_typed_operations(app).await;
        settled
    }

    /// 🚰️ Completes every admitted retained operation and acknowledges its bounded output pages.
    ///
    /// 🧹️ Delegates to the FRAMEWORK's own settle helper rather than re-rolling the pump. The
    /// hand-rolled loop this replaces drained the lane pages, the effects, the events and the ui
    /// scopes — but never the terminal-witness outbox (`take_typed_operation_completion`), the
    /// composed-result outbox or the local interaction-query replies, all three of which
    /// `has_pending_typed_operations` COUNTS. Every writer command whose operation published no
    /// further lane page therefore spun this loop to its 30 s deadline and failed with "Writer
    /// retained operations did not finish" (fleet-brief stale-test bucket 6; the same defect
    /// ticket 26/09/09/PROCEDURAL-3D-END-TO-END fixed inside the helper). It also takes ONE page
    /// per turn where the helper drains every presented page, so a command publishing an artifact
    /// AND a config lane reported only one of them.
    pub async fn drain_typed_operations(app: &mut WriterApp) -> Vec<semio_framework_plugin::Effect> {
        let receipt = settle_registered_typed_operation(&mut app.0, meta("local").instance_id).await.unwrap_or_else(|fault| panic!("Writer retained operations did not settle: {fault:?}"));
        receipt.effects
    }

    /// ⌨️ The main text window's typing buffer (its editor surface id).
    pub const WRITER_TYPING_BUFFER: &str = "writer.main";

    /// ⌨️ One live typing delivery of the main text window at `now_ms`: `action` with `args` plus the window's `typing` buffer,
    /// admitted and published — the window folds it into its typing run (design §13.2 of ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-
    /// EDITING).
    pub async fn type_delivery(app: &mut WriterApp, action: &str, mut args: Vec<(String, dsl::DslValue)>, now_ms: u64) -> InvocationResult {
        let mut meta = meta("local");
        meta.view_state = Some(main_window_view());
        args.push((semio_framework_plugin::TYPING_BUFFER_ARG.into(), dsl::DslValue::String(WRITER_TYPING_BUFFER.into())));
        app.set_tool_clock_ms(Some(now_ms));
        let result = app.handle_action(action, Some(&dsl::DslValue::Object(args)), &meta).await.unwrap_or_else(|fault| panic!("typing delivery {action}: {fault:?}"));
        drain_typed_operations(app).await;
        result
    }

    /// 🏁️ The host's commit signal for the main text window's run (`reason`, no edit) at `now_ms`.
    pub async fn end_typing_run(app: &mut WriterApp, action: &str, reason: &str, now_ms: u64) -> InvocationResult {
        let args = vec![(semio_framework_plugin::TYPING_COMMIT_ARG.to_string(), dsl::DslValue::String(reason.into()))];
        type_delivery(app, action, args, now_ms).await
    }

    pub async fn render(app: &mut WriterApp, body_key: &str) -> String {
        semio_framework_plugin::artifact_app_laws::project_and_retire_fixture_tree(app.render(body_key, None, &main_window_view()).await.expect("render")).expect("render json")
    }

    pub async fn main_window_measures(app: &mut WriterApp) -> Vec<WindowMeasure> {
        app.window_measures(&main_window_view()).await.get(WRITER_TEST_WINDOW_ID).cloned().expect("main window measures")
    }
}

