use crate::{En1998Diff, En1998Mutation, En1998Snapshot};
const BEFORE: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/💪️change-system-v-rd-n/✅apply/📸️snapshot/⬅️before/🔣️.json");
