        ],
        "spreads": [
            { "id": "spread-1", "name": "Spread 1", "pageIds": ["page-1"] }
        ],
        "pages": [
            {
                "id": "page-1", "name": "Page 1", "spreadId": "spread-1", "parentPageId": "master-1",
                "width": 210.0, "height": 297.0,
                "margins": { "top": 10.0, "right": 10.0, "bottom": 10.0, "left": 10.0 },
                "columns": { "count": 1, "gutter": 0.0 },
                "guides": [], "layerIds": [], "layers": [], "frames": [], "overrides": []
            }
        ],
        "printTarget": null
    });
    semio_framework_pack_json::from_json_str(&json.to_string(), semio_framework_pack_json::JsonMemberPolicy::Reject).expect("valid layout snapshot json")
}
//#endregion 🧸️Fixtures

//#region 🧪️InferenceLaws
#[semio_framework_async_macros::async_test]
async fn inference_determinism_law() {
    let snapshot = snapshot_with_master_and_spread();
    assert_eq!(LayoutInference::infer(&snapshot), LayoutInference::infer(&snapshot));
}

#[semio_framework_async_macros::async_test]
async fn inference_default_law() {
    let empty = semio_framework_pack_json::from_json_str::<LayoutSnapshot>(
        &(serde_json::json!({
            "schema": "semio.layout/v1",
            "name": "",
            "grid": { "baselineGrid": 12.0, "baselineOffset": 0.0, "snapToBaseline": false },
            "paragraphStyles": [], "characterStyles": [], "stories": [], "links": [],
            "parentPages": [], "spreads": [], "pages": [], "printTarget": null
        }))
        .to_string(),
    )
    .expect("valid empty layout snapshot json");
    assert_eq!(LayoutInference::infer(&empty), LayoutInference::default());
}

#[semio_framework_async_macros::async_test]
async fn page_topologically_follows_its_master_and_spread() {
    let snapshot = snapshot_with_master_and_spread();
    let inferred = LayoutInference::infer(&snapshot);
    let master_index = inferred.topology.topo_order.iter().position(|id| id == "master-1").unwrap();
    let spread_index = inferred.topology.topo_order.iter().position(|id| id == "spread-1").unwrap();
    let page_index = inferred.topology.topo_order.iter().position(|id| id == "page-1").unwrap();
    assert!(master_index < page_index);
    assert!(spread_index < page_index);
    assert!(inferred.topology.cycle_free);
    assert_eq!(inferred.topology.node_count, 3);
}
//#endregion 🧪️InferenceLaws

//! ⚡️ Layout artifact — OpText/OpBinary codecs for `LayoutMutation`. Mutation apply/inverse (via
//! `protocol::Mutation`/`protocol::SemanticMutation`, generated by `#[derive(dsl_derive::Mutations)]`
//! on the dispatch enum in `../🦀️.rs`) is NOT this file's concern; this file only wires the
//! operation-log line/binary encodings.
//!
//! Every `LayoutMutation` variant wraps a plain local payload struct now (no foreign generic — the
//! pre-migration collection-op-flattening `LayoutMutationDsl`/`FramePatchDsl`/`ColorPatch`
//! mirrors this file (and `../💾️binary/🦀️.rs`) used to carry, needed only to route around
//! the orphan rule for that op type's foreign generic and `FramePatch.fill`/`.stroke`'s
//! doubly-optional `Option<Option<[f32;4]>>` fields, are gone with it). `serde_json`'s compact
//! (single-line, declaration-order) encoding satisfies `OpText`/`OpBinary`'s laws directly:
//! `print_op` never contains `\n`, `parse_op(op.print_op()) == op`, and encoding is deterministic.

pub use crate::mutations::LayoutMutation;

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

//#region 🔖️OpText
impl protocol::OpText for LayoutMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        protocol::json::from_json_str(line).map_err(|e| store::__rt::field_error(format!("invalid layout mutation line: {e}")))
    }
    fn print_op(&self) -> String {
        protocol::json::to_json_string(self)
    }
}
//#endregion 🔖️OpText

