    matches!(
        action,
        "setActiveExample"
            | "addObjectKind"
            | "deleteSelection"
            | "duplicateSelection"
            | "setSelectionFlag"
            | "setSelectionHidden"
            | "setSelectionLocked"
            | "patchInspector"
            | "engagementSubmit"
            | "engagementRepeatLast"
            | "createAttraction"
