fn bounded_chunk_values_match_the_json_oracle() {
    let vectors: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🔣️chunks.json")).unwrap();
    for vector in vectors.as_array().unwrap() {
